/* 令和7年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r07.committeeSessions.push(...[{"id":"r07-20250630-8","meetingId":"r07-cm06","date":"2025年6月30日","dateIso":"2025-06-30","committee":"建設委員会","time":"午前１０時００分～午後 ３時１１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を81件抜き出しています。","topics":[{"id":"topic-01","title":"第７１号議案、令和７年度品川区一般会計補正予算（歳出 建設委員会所管分）","agenda":"第７１号議案、令和７年度品川区一般会計補正予算（歳出 建設委員会所管分）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"グリーンインフラですけれども、有効性を検証とありますが、検証後の展開の考え方について伺いたいのですけれども、どうでしょうか。併せて、勝島地区の耐震化についてですけれども、今回どうしてこちらが追加になったのか、伺いたいと思います。耐震化が未実施の地区内残留地区というのはほかにあるのでしょうか、伺いたいと思います。","respondent":"森道路課長、関根河川下水道課長","answer":"私からは、グリーンインフラについての２点のご質問にお答えいたします。今後の展開というところですけれども、区として、今回のようなグリーンインフラの舗装を別のところでやるというのは、今のところ計画はしておりません。最後に、安全性をどのぐらい確保できるのかというご質問にも関連いたしますが、既に地区内残留地区の耐震化より先に、避難所ですとか例えば災害復旧拠点などは、優先的に既に耐震化を進めており、実施済みですので。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"民間井戸は、共産党としても２０１９年の代表質問で具体的に求めてきておりましたので、こちらは歓迎いたします。それと、感震ブレーカーですけれども、現在の感震ブレーカーの普及状況について伺いたいのですが、どれぐらいになっていますでしょうか。補助対象は区内全域に広がったと思うのですが、区内全域で実施している自治体というのは都内にどれぐらいあるのでしょうか、伺います。","respondent":"遠藤防災体制整備担当課長","answer":"感震ブレーカーの普及状況につきましては、令和６年の世論調査によりますと、「防災対策として感震ブレーカーを設置している」と答えた人が全体の４.７％になっております。感震ブレーカーの設置台数に関しましては、これまで８６９件、令和６年度までに実績があります。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"まだまだ通電火災を防ぐには至っていないというか、それに向けて、今回、都の補助金も活用していくということだと思うのですけれども、そちらはそちらで目標を持って進めていっていただきたいなというのが要望です。ただ、中長期的に見て、やはりマンホールトイレですとか耐震トイレを必要数整備していく必要があるのではないかと思うのですけれども、そちらについての区の今後のお考えをお伺いします。","respondent":"遠藤防災体制整備担当課長","answer":"トイレの中長期的なところで、マンホールトイレの整備はどうかというお話ですが、こちらにつきましても、区としてもやはりマンホールトイレを活用できるような形で、災害時のトイレの対策は幅広く考えていかなければいけないと認識しておりますので。","id":"exchange-003"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"５つ項目があるので、少し区切って質疑させていただきたいと思います。道路改良事業、雨水貯留浸透舗装整備について、ＰＲ用の看板を設置とありますが、この看板にはどのような内容が記載されるのか、もう少し詳しくお聞きできればと思います。続けて、下水道管改修事業、地区内残留地区（勝島地区）で、今回の設計内容だと、耐震化は管延長２.９キロメートル、人孔浮上抑制対策は９２か所となっています。","respondent":"森道路課長、関根河川下水道課長","answer":"看板の内容といたしましては、東京都と品川と雨水しみこみアンバサダーの事業者で連携してやっていくということと、それから、浸透・貯留といった機能がなぜ必要なのか。今回実施するのが２.９キロメートルで、実施地区の一部ということでご説明させていただきましたが、実施地区全体でいきますと、延長としては約１３キロちょっと、１３.４キロメートルとなっておりますので。","id":"exchange-004"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"これは要望で終わります。続けて、防災体制整備費、災害対策用井戸事業について、「３.予算額」で、維持補修費はどこまでが維持補修費で、どこからが設置工事費になるのかというのを具体的にお聞きできればと思います。命に関わる対策なので必要不可欠なのですけれども、現場の声はいかがでしょうか。備蓄のスペースはどうなのか、声を受けているのか、そこだけ確認させていただきたいと思います。","respondent":"森道路課長、遠藤防災体制整備担当課長","answer":"そういった情報を例えばＱＲコードで読めるようにするなど、様々なＰＲ方法ができないかということも、所管課と話をしながら検討していきたいと思います。感震ブレーカー、２月までの間に今回の１６０件の予算額を超える場合といったご質問だったと思いますが、こちらにつきましては、超える見込みが立った場合、東京都と柔軟に、補助が漏れないような形で。","id":"exchange-005"},{"speaker":"ゆきた委員","kind":"確認","question":"ＰＲ用看板については、ぜひ進めていただければと、検討していただければと思います。防災用井戸につきましては、確認させていただきました。感震ブレーカーについてですけれども、こちらも確認させていただきました。最後に、トイレについてですけれども、こちらは集中備蓄倉庫ということで確認させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"初めに、グリーンインフラ、雨水貯留浸透舗装ということで、先ほどもやり取りがありましたけれども、やはり今後の展開を伺いたいと思います。今後の展開について、ぜひ広げていただきたいと思いますが、いかがでしょうか。今回の工事はどの程度期待できるものなのか。自然が相手ですから、液状化現象を思うと、ある程度は期待できるのかなと思いつつ、実際のところはどう把握されているのか、伺いたいです。","respondent":"森道路課長、関根河川下水道課長","answer":"浸透機能のある浸透ますを設置しまして浸透を図っているというところがあります。これまで４,９００個以上の浸透施設を導入しまして、流域全体として整備を進めているです。具体的な数値ではございませんが、浮上抑制によって、緊急車両の通行を阻害するほど飛び出たりしないような形で浮き上がりを防止するということで、弁の数ですとか配置ですとか、そういったものを検討して。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"幾つか伺いたいのですけれども、これはマンションも対象なのかどうか。私のマンションでもこれは話題になりまして、分電盤だと自己負担が１万２,０００円というところで、なかなかみんなの合意にはまだ至っていないのですけれども、ぜひ既存のマンションにも感震ブレーカーが普及するようにしていただきたいと思いますが、そこの点のお考えを伺いたいと思います。","respondent":"森道路課長、大友公園課長、遠藤防災体制整備担当課長","answer":"今回、計画的にこれと同じような形で進めていく予定はないと申し上げたのは。１点目、感震ブレーカーはマンションは対象ではないのかというご質問ですが、こちらにつきましては。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"グリーンインフラですけれども、私が言うまでもなく、こういう浸透させる機能というのは、面積が広ければ広いほど効果が大きくなるわけですから、ぜひ今後、東京都とも連携しながら拡大していただきたいと要望したいと思います。感震ブレーカーですけれども、ぜひマンションも対象にしていただきたいと思います。なぜできないのか、そのお考えを伺いたいと思います。併せて、民間井戸とトイレのことです。","respondent":"遠藤防災体制整備担当課長","answer":"仮設トイレという認識だと思いますが、仮設トイレの確保につきまして、こちら、区と工事関係のレンタル会社と災害協力協定を締結しておりまして、災害時に仮設トイレをレンタル会社と連携して配備できるかどうかといったところも今後検討していきたいと考えております。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"初めにトイレについてですけれども、回収についても、しっかり計画を点検していただきたいと強く要望しておきたいと思います。感震ブレーカーですけれども、マンションを対象にしない理由が、建物が丈夫だからと。ぜひ考えを改めていただいて、マンションも感震ブレーカー設置補助の対象に入れていただきたいと改めて求めますが、いかがでしょうか。","respondent":"遠藤防災体制整備担当課長","answer":"委員のご質問についてですが、区としても在宅避難というところはやはり今後考えていかなければいけないというところで、支援の仕方については引き続き検討させていただきたいと思います。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"マンションについて支援の仕方を検討したいということなので、今日はここで終わりにしますけれども、やはり品川は、木造住宅に住んでいる方よりもマンションに住んでいる方のほうが世帯も人数も多いというのがまちの特徴です。支援の仕方を検討したいということなので、ぜひ早急にご検討いただきたいと要望して、終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"松永委員","kind":"質問","question":"私からは１点なのですが、第７１号議案の道路におけるグリーンインフラについて伺いたいと思います。耐震性というのはどのくらいなのか、伺いたいと思います。図から見ると、先ほどもいろいろご説明がありましたが、案内板の位置についても、例えば透明なガラスの上に立たないと見えないというのもどうかなと思いますので、そうした対策についてお知らせください。","respondent":"森道路課長","answer":"そうすると直接見ることができますので、そういった形でやるか、そうした場合には、ＰＲの看板については、ここではなくて少し横のほうであるとかいうようなことを、今、様々検討しているところです。","id":"exchange-012"},{"speaker":"松永委員","kind":"質問","question":"怖がる方もいらっしゃるので、ぜひそういった対策をとっていただければと思います。メンテナンスについても、どのくらいの頻度とかが分かり次第、ご説明いただければと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"せお副委員長","kind":"質問","question":"委員の皆さんの質疑でほとんど分かったのですけれども、２点だけ。感震ブレーカーなのですけれども、東京都からというのは、どういうスキームでというか、今回１万円を１６０件とこちらには書いてあるのですが、東京都からはどのように事業内容として来ているのかというのだけ教えてください。","respondent":"遠藤防災体制整備担当課長","answer":"我々もやはり災害対策用井戸は区内全域に展開するということが理想かなと考えていますので、そちらに向けて引き続き検討していきたいなと考えているところです。","id":"exchange-014"},{"speaker":"せお副委員長","kind":"意見","question":"感震ブレーカーについては理解いたしました。先ほど安藤委員かな、他区ではどうなっているのかという話があったと思うので、そこら辺も私は分からないので、東京都の中でどういったスキームというか、どういう流れ、経緯でこうなってきているのかなというのが気になっていたのですが、おおむね理解いたしました。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"}]},{"id":"topic-02","title":"令和７年請願第９号、本掘進に入る前の今こそリニア新幹線の中止を決断するようＪＲ東海に求める請願","agenda":"令和７年請願第９号、本掘進に入る前の今こそリニア新幹線の中止を決断するようＪＲ東海に求める請願","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"資料の２のところの説明会なのですけれども、１２月と５月の２回の説明会、それぞれの参加人数は何人と聞いているのか。それとあと、本格掘進ですけれども、いつ行うとＪＲから聞いているのでしょうか。それとも聞いていないのでしょうか。こちら、行う時期が決まったとしたら、品川区ですとか品川区民には、いつ、どのような形で知らされると聞いているのかも伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"２点目の本掘進につきましては、ＪＲ東海からは、現在本格的な掘進に向けた段取り替えを実施しており、今年の夏頃より、準備ができ次第、開始する予定であると聞いているところです。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問","question":"私も参加はしたのですけれども、特に５月は、両日参加したわけではないですし、かなり長い時間やっているのです。それで、ホームページにも公表されておらず、区としても伺っていないということなのです。これは伺っていないで済ませるわけにいかないのではないかと思うのですが、これはきちんと区として把握する必要があると思うのですけれども、いかがですか。","respondent":"大石まちづくり立体化担当課長","answer":"説明会の結果について区として把握すべきではないのかですけれども、ＪＲ東海からは、先ほどの繰り返しになりますけれども、使用した資料についてはホームページに掲載していると聞いているところです。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"私は、ＪＲ東海のこのひどい隠蔽体質というのですか、どういうことをやったのか、何のために説明会をやったのかなと。それで、品川区が何もやっていないならここまで言わないのですけれども、先ほど説明がありましたが、昨年、１２月１９日に要請もしているわけではないですか。そういうふうに見えるのですが、実際はどうなのでしょうか。実際行われたのでしょうか、伺います。","respondent":"大石まちづくり立体化担当課長","answer":"原因究明につきましては、今、ＪＲ東海では、山の状況等を引き続き注視しつつ、対応について検討していくと聞いているところです。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"先ほど伺ったように、原因究明が行われていないことに対して区はどう考えているのかということと同時に、対応について検討していきますとＪＲは言っていますけれども、仮にこのまま、検討中のまま、原因究明が行われないまま、明日から、来週からでもいいですけれども、工事を始めますと言ったら、区としては納得するのですか。それも併せて伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"区といたしましては、原因究明が今まさに検討されているというところと認識してございまして、要請書の発出に至った理由といたしましては、繰り返しになりますけれども、シールド掘進位置の近傍が発生地点となっていること、区民から不安や懸念の声が寄せられていたこと、また。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"原因究明が今まさに行われているという認識だとおっしゃいましたけれども、そうなのですかね。そこは確認してください。原因究明をやっているのですかと。対応について検討していくとしかＪＲは言っていないわけですから、そこは必ず確認していただきたいのですけれども、いかがでしょうか。原因究明は今まさに行われているのですか、やっているのですかというのを聞いてもらいたい。","respondent":"大石まちづくり立体化担当課長","answer":"今現在、原因究明が行われているのかというところにつきましては、先ほどの繰り返しになりますけれども、現状、泡の状況等を引き続き注視しつつ、対応について検討していくとＪＲ東海から聞いているところです。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"私は、この請願を採択をして、やはり議会として品川区は区民の財産と命を守っていく立場に立ってくださいと強く求めるべきだと思うので、ぜひほかの委員の皆さんにも採択していただきたいなと。最後に２つだけ、すみません、お伺いしたいのですが、品川区の資料の３番目のところです。もう一つは、請願書に書いてありますが、中止を決断するよう求めてくださいと項目の３番目にあります。","respondent":"大石まちづくり立体化担当課長","answer":"中止を求めない理由ですけれども、こちらも繰り返しになりますが、リニア中央新幹線につきましては、ＪＲ東海が国から認可を受けて、ＪＲ東海の責任の下に実施されている事業となっています。区といたしましては、ＪＲ東海に対して引き続き必要な要請を行っていく考えです。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"そこら辺についての説明などは受けていないのでしょうか。私は理不尽極まりないというか不誠実だと思いますけれども、それはどうかという点を伺います。でも、中止を求める事業というのはあるわけであって、中止を求めない理由というのはそれ以外にないのですかと。今のご説明だと説明になっていないと思うので、改めて伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"区といたしましては、引き続きＪＲ東海に対しまして、安全な施工の実施と区民への丁寧な対応、工事に関する情報の適時適切な発信を求めるなど、必要な要請を行ってまいります。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問","question":"様々伺ってまいりましたけれども、到底、今の状況で本掘進に入るということは許されないと思います。品川区はＪＲ東海に対して中止を含め厳しく意見を言うべきだと思いますし、議会としても、そのような立場に立って、この請願を採択すべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問・要望","question":"本掘進に入る前の今こそリニア新幹線の中止を決断するようＪＲ東海に求める請願ということで、品川区民の会より、代表ほか２８０名の方から請願が提出されております。担当課長に伺いたいのは、なぜこうして繰り返し、しかも多くの方から区に対してリニアの中止を求める請願が上がっているのか。この区民の気持ちをどう理解しているのか。理由と気持ち、そこを伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"区といたしましても、そのような声を受け止めまして、しっかりとＪＲ東海に必要な要請を行ってきたところでございまして、今後も必要な要請は行っていきたいと考えているところです。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"それに対して、必要な要請をしていくと。では、気泡について伺いますけれども、５月１２日の建設委員会でも、担当課長と質疑をさせていただきました。先ほども説明はありましたが、ＪＲには原因究明を求めていると。ＪＲ自身は観測をしていると。私は、なぜ安全と言えるのか、区の認識を伺いたいと思います。こんなので何で安全だと言えるのかと私は思いますけれども、いかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"今現在行われております観測井戸での酸素濃度測定につきましても、大気と同等の結果が出ているということで報告を受けているです。","id":"exchange-025"},{"speaker":"中塚委員","kind":"質問","question":"異常がない、結果が出ているとおっしゃいますが、ならば、どこで調査をしているのか、どんな方法で調査をしているのか、異常がないという数値を区は把握しているのですか。","respondent":"大石まちづくり立体化担当課長","answer":"酸素濃度測定の詳細につきましては、シールドマシン周辺の観測井戸にて定期的に酸素濃度測定を行っていると聞いているところです。","id":"exchange-026"},{"speaker":"中塚委員","kind":"確認","question":"定期的にというだけで、具体的に数値を区は認識しているのですか。前回の建設委員会でのやり取りで、していないということが明らかになっているのだから、この場でもすぐ認めればいいではないですか。改めて伺います。つまりは、どこでどんな調査をしているのか、どういう数値が出ているのか、その客観的なデータが示されないで、なぜ安全と言えるのか、異常がないと確認できたとなぜ言えるのか、伺います。","respondent":"大石まちづくり立体化担当課長","answer":"なぜ安全と言えるのかですけれども、まず酸素濃度測定につきましては、ＪＲ東海からは、周辺環境に影響が認められる結果、これはすなわち酸素濃度測定結果が大気中の酸素濃度約２１％を下回った場合が異常が認められるとＪＲ東海のほうで考えているということで、今。","id":"exchange-027"},{"speaker":"中塚委員","kind":"質問・要望","question":"前回も指摘して、やり取りしましたけれども、結局データは出ていないのです。ただ単にＪＲが異常がないと言っているだけなのです。それでなぜ安全と言えるのかと私は思います。結局は安全神話みたいなものなのです。そう言うのであれば、測定の方法だったり、結果だったり、データを公表すべきだと、区にも知らせるべきだと、それをＪＲに求めていただきたいと思いますが、いかがですか。","respondent":"大石まちづくり立体化担当課長","answer":"こちらで、いずれの測量点においても変位はプラスマイナス３ミリ程度に収まっており、沈下や隆起が続く傾向は見られませんでしたというところで、広く説明会で説明していると認識しております。","id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"説明会では１１月１１日にと、書いてありますよ。その調査の場所や方法、数値をＪＲに求めろと言っても、その考えはない。１回ぽっきりの調査ではなくて、現状どうなっているかを注視しているわけだから、そのデータを出せという立場に立つべきだと改めて伺いますが、ご答弁いただきたいと思います。別の言い方をすると、ＪＲが進めていると、なぜ品川区は中止を求めないのか、伺います。","respondent":"大石まちづくり立体化担当課長","answer":"現在の調査の追加の数値ですけれども、ＪＲ東海からは、５月に開催したオープンハウス型の説明会にて、目黒川の泡の状況などについては説明を行っていると聞いているところです。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"５月の説明をしたことは、さっきも言ったではないですか。区がつくった今日の資料に書いてあるのです。なぜ国に中止を求めないのかということで、中止ではなく安全に施工と今ご答弁がありました。つまり、品川区としては、リニア新幹線は早く完成してほしいという立場ですか。","respondent":"大石まちづくり立体化担当課長","answer":"繰り返しになりますが、リニア中央新幹線はＪＲ東海が国から事業認可を受けて進めているものです。区といたしましては、ＪＲ東海に対して、引き続き安全な施工と区民への丁寧な対応、工事に関する情報の適時適切な発信を求めるなど、必要な要請を行っていく考えです。","id":"exchange-030"},{"speaker":"中塚委員","kind":"質問","question":"中止ではなく安全に施工と先ほどおっしゃいましたよね。中止ではなく安全に施工とは、どういう意味ですか。","respondent":"大石まちづくり立体化担当課長","answer":"安全な施工ですけれども、こちら、一つにはまず地上に影響がないような形ですね、そういったものを含めまして、総括的に安全な施工の実施と区民への丁寧な対応、工事に関する情報の適時適切な発信を求めているものです。引き続き必要な要請を行ってまいります。","id":"exchange-031"},{"speaker":"中塚委員","kind":"質問・要望","question":"影響がないように安全に施工ということは、つまり、リニア新幹線を進めてほしいというのが区の立場でしょう。なぜそこを隠そうとするのですか。区としては、リニア新幹線、安全に工事が行われてほしい、つまりは進んでいただきたいと思っているのですというのだったら、そう言えばいいではないですか。何でそれは言えないのですか。改めて伺います。だから、リニアに賛成だと正直に言えばいいではないですか。","respondent":"大石まちづくり立体化担当課長","answer":"区といたしましては、ＪＲ東海に対して、引き続き安全な施工の実施と区民への丁寧な対応、工事に関する情報の適時適切な発信を求めるなど、必要な要請を行ってまいります。","id":"exchange-032"},{"speaker":"中塚委員","kind":"質問","question":"こんな答弁で私が納得すると思いますか。リニア新幹線の完成が前提なのでしょう。何で賛成だという立場を隠そうとするのですか。なぜその立場が表明できないのですか。お互いの意見が表明されないと、議論が深まらないではないですか。そうだろうなと思っていらっしゃるとは思いますけれども、さっきから、ぐだぐだ言わないで、賛成だという立場がなぜ表明できないのかを伺います。","respondent":"新妻委員長、大石まちづくり立体化担当課長","answer":"傍聴人に申し上げます。審査の妨げになりますので傍聴人はご静粛に願います。私語はできません。区といたしまして、飯田市との連携協定等の話ですけれども、そういった事業認可がなされているというところで、協定を結んで、未来のご近所というところでお話合いが進められているものと考えているところです。","id":"exchange-033"},{"speaker":"中塚委員","kind":"質問・要望","question":"この押し問答を聞いて、担当課長の答弁は的を射ているなと思った人はいないと私は思います。国から認可を受けているから、区は賛成なのだけれども賛成と言えない。何だかこんなやり取りではいけないなと思います。いずれにしても、この請願の中では、国に中止するよう求めております。これまでも繰り返し示されておりました。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"せお副委員長","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。区はできる限りの取組や対応をしてきていますし、今後もしていただきたいということを要望して、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"松永委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いいたします。区民からご意見や要望が本区へ届いていることから、昨年の１２月１９日に要請文をＪＲ東海に求めて、教室型、また、オープンハウス型の説明会を行っております。今後も順次説明会を行っていくとおっしゃっており、また、リニア新幹線は国が進めている政策であると認識しているため、今回の請願については、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"理事者の説明からも、改めての原因究明については求めていること、また、区として適時適切な説明を求めている中に教室型説明会も含まれていること、さらに、区としては安全な施工と区民への情報発信をしていく姿勢を確認できましたので、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"安藤委員","kind":"質問・要望","question":"品川区は地元の自治体として、住民の不安と中止を求める声に応えるべきだと思います。今の対応はあまりにも不十分ですし、リニア新幹線は国が進めている国策、民間の政策だということもあるかもしれませんけれども、それであっても、住民の暮らしと環境に関わってくる重大な事業であれば、これは毅然と意見を申し述べるべきだと思いますので、採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"中塚委員","kind":"質問・要望","question":"今日結論を出すということと、採択でお願いします。やはり品川区議会としてもリニア中止の声を上げるべきだと思います。品川区長に対しても、中止の決断をＪＲ東海に求めるべきだと思います。併せて、先ほど質疑させていただきましたが、品川区には、やはりここは議会ですから、誠実な答弁を重ねて求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"請願第９号の採決の中で、適時適切な説明を求める中に教室型説明会が含まれていることとして不採択とさせていただきましたが、こちらは、区民への丁寧な説明をしていくということを確認させていただいたため不採択と訂正させていただきたいと思います。大変失礼いたしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"}]},{"id":"topic-03","title":"議案審査、(1)第８４号議案、品川区災害弔慰金の支給等に関する条例の一部を改正する条例","agenda":"議案審査、(1)第８４号議案、品川区災害弔慰金の支給等に関する条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"この審査委員会の２３区での設置状況が分かれば教えてください。それと、災害による死亡あるいは障害か否かの判定なのですが、何か判定基準のようなものがあるのでしょうか。審査委員の判定の基準になるようなものについてどうなっているのか、伺いたいと思います。それとあと、審査委員会ですけれども、これは常設なのでしょうか。総務委員会のことも含むかもしれませんが、関連するので伺います。","respondent":"羽鳥防災課長","answer":"他区の状況についてですけれども、こちら、２３区中５区が審査会の設置について条例で定めているところです。港区、新宿区、台東区、墨田区、杉並区、以上の５区になります。判定基準についてですけれども、こちら、一定の基準は設けられていません。","id":"exchange-041"},{"speaker":"安藤委員","kind":"質問","question":"６区目ということになると。分かりました。すみません、基準について、よく聞き取れなかったというか、ふだんからひな形みたいな判定の基準が共通であって、それを使うのか、それとも、改めて審査委員会の中でみんなで話し合って判定基準みたいなものを定めるのか、そこら辺、もう少し教えてください。","respondent":"羽鳥防災課長","answer":"基準についてですけれども、過去の災害における審査委員会の事例におきましても、統一の基準というものはこれまでありません。それぞれ災害の中で開かれる審査委員会において一定の基準が定められるという流れになります。","id":"exchange-042"},{"speaker":"中塚委員","kind":"質問・要望","question":"幾つか伺います。この条例改正がされる前とされた後について。もう１点、条例改正にどのような災害かというのは書かれているのですけれども、いわゆる大規模災害になった際、首都直下型大震災のように被害の規模が大きい場合というのは、日常の災害の被害とは規模が異なるから、これに限らず、行政機能が止まらないように様々準備をしているのは当然ですけれども、大規模災害のときはどういう動きになるのか。","respondent":"羽鳥防災課長","answer":"それなりの規模になるだろうということも想定しますので、やはり各自治体で平時から審査会を設置する必要があると考えています。ですので、具体的な期間というのは分からないですけれども、災害の規模にも応じますが、早急に対応できるように準備を進めるです。","id":"exchange-043"},{"speaker":"ゆきた委員","kind":"質問","question":"品川区災害弔慰金の支給等に関する条例に関連して、現在までの火災・風水害に対する品川区災害弔慰金および災害見舞金の支給要綱についてお聞きします。品川区のホームページで検索して、タイトルが出てきてもアクセスできないということになっています。ここについて詳細をお聞きできればと思います。","respondent":"羽鳥防災課長","answer":"お支払いする弔慰金は５万円という形になります。今回ご審議いただいているものに関しましては、災害救助法が適用になる大規模災害で、弔慰金の金額は５００万円という形になります。","id":"exchange-044"},{"speaker":"ゆきた委員","kind":"確認","question":"確かに品川区小災害見舞金等支給要綱は、火災・風水害のところから拝見することができるのを確認しました。令和７年６月１日に名称が変更されているとも分かりました。説明を受ければ分かりますけれども、区民からすれば、今までの火災・風水害の見舞金はどれぐらいなのか、調べようとしても、名目が変わっているので、なかなか分かりにくいと思われます。この辺について改めてお聞きできればと思います。","respondent":"羽鳥防災課長","answer":"今回、名称のほう、分かりやすいように変更させていただきましたので、引き続き区民の方に分かりやすいように、丁寧に説明していきたいと考えております。","id":"exchange-045"}]},{"id":"topic-04","title":"請願・陳情審査、(2)から(4)までの陳情３件につきまして、関連する内容のため一括して議題に供します。 進め方としまして、３件の陳情","agenda":"請願・陳情審査、(2)から(4)までの陳情３件につきまして、関連する内容のため一括して議題に供します。 進め方としまして、３件の陳情","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"その前に、小山三丁目第１地区、陳情にもちょっとありましたけれども、改めて、第１地区の事業費と、あと補助金額、予定されている額は幾らなのかというのを伺いたいのと、あと再開発準備組合への加入状況などについても伺いたいのですが、ここの地区の総地権者数は何人で、そのうちの内訳として、土地所有者数、借地権者数、マンション区分所有者数は何人いるかを伺いたいのと。","respondent":"中道都市開発課長","answer":"今、資金計画上での補助金額につきましては、こちらに２２９億８,０００万円と記載されておりますが、こちらにつきましては、今後組合を設立した際に、区のほうと東京都または国との調整によって変更してくるというようなものです。","id":"exchange-046"},{"speaker":"安藤委員","kind":"質問","question":"地権者数についても伺ったのですが、総地権者数と、土地所有者数、借地権者数、マンション区分所有者数、そして今、再開発への同意率は把握しているということでしたので、それぞれの同意率について伺いたいと思います。","respondent":"中道都市開発課長","answer":"同意率につきましては、土地所有者の方が７３％、また、マンションが５棟ありますが、そこの区分所有者の方の平均をとりますと８４％の方が同意されているです。借地権者の方につきましては約９１％の方が同意しているという状況です。","id":"exchange-047"},{"speaker":"安藤委員","kind":"質問","question":"それと、地区内には５つのマンションがあるのですけれども、その合意状況についてもう少し伺いたいのですが、ここに書いているように、１区分所有者の人は全体で１つの権利の中の１人に過ぎないです。マンションごとに意思決定というのですか、先ほどの同意申請、そういうのはしているのでしょうか。その５つのマンションというのはどのように意思決定をしているのか。そこら辺、伺いたいと思います。","respondent":"中道都市開発課長","answer":"そうした理由を踏まえまして、現段階では今この数字がいわゆる同意がとれるというかご理解をいただける状況という認識の下、東京都と相談した上で、こういった事業認可を進めているです。","id":"exchange-048"},{"speaker":"安藤委員","kind":"質問","question":"もう少し伺いたいのですが、３月２４日と４月１８日に総会が行われたと。それが何％だったのかというのを、これが区に対して本組合認可申請の根拠になった総会と言われているものですから詳しくお伺いしているのですけれども、いかがでしょうか。","respondent":"中道都市開発課長","answer":"組合にもヒアリングを行いましたけれども、今、陳情にあります４番と５番ですか、参加者人数等につきましては、準備組合からは非公表でお願いしたいと聞いてあります。","id":"exchange-049"},{"speaker":"安藤委員","kind":"質問・要望","question":"それで、区で把握していないことが多い。これ、だって、何億円の税金が入っているのですかという話なのです。受理して送付したというわけですから、もう一度、先ほどの回答に、同意率というところになるかもしれませんが、今品川区が把握しているところというのは何なのか、それはぜひ教えていただきたい。そういうお知らせとかがどういうふうになされていたのかという点についても伺いたいと思います。","respondent":"中道都市開発課長","answer":"１番につきましては、先ほどご説明したとおりです。２番につきましては、地権者総議決権数は５７、区分所有者の議決権数につきましては５名、土地所有地権者議決権数は１９、借地権者の議決権数は３３となっています。","id":"exchange-050"},{"speaker":"安藤委員","kind":"質問","question":"区としては、最後に課長がおっしゃったようなことであるならば、これは、そうあってほしかったということではなかったわけですから、私は、区の権限がどこまであるのか分かりませんが、もう１回やり直してくれと言ったほうがいいと思います。これはまちづくりでも何でもない。それで、改めて陳情第２２号についても伺っていきたいと思います。かなりいると思うのです。","respondent":"中道都市開発課長","answer":"最終的にアーケードをどうするかという決定権は商店街にあると思いますが、まずは商店街としましても、そういった検討資料などを踏まえて検討していく必要があるのかなと考えています。","id":"exchange-051"},{"speaker":"安藤委員","kind":"質問","question":"で、その陳情理由、第２２号の４についても最後伺いますが、指導する人ということで、国会決議について問われていますけれども、指導する人というのは誰なのか改めて伺いたいのと、区はどのような指導、この国会決議にあるような指導を行ったのか。同意を得られない者の立場を十分に考慮して、極力円満に設立手続を進めるよう指導することとあるわけですが、そこについて具体的に伺いたいと思います。","respondent":"中道都市開発課長","answer":"具体的にどのような指導をしたかというところにつきましては、やはり一人一人丁寧に対応していただきたいというのを常々、準備組合のほうには求めてあります。そうした中で、ちょっと時間をかけて同意率も上げてきたというふうに考えてあります。","id":"exchange-052"},{"speaker":"安藤委員","kind":"質問・要望","question":"結果的に、先ほどもあったように、そういう手続をするというお知らせもなしに手続が行われ、区に送付された後に地権者にそういう話が行くという状況があったりとか、３５名の方々が取り残されているという状況もあったりということで、やはり国会決議の規定に照らして、今回の設立認可申請受理、送付という品川区が行った行為は、私は整合性が取れていないと思うんですけれども、今回のケースにおいて。","respondent":"中道都市開発課長","answer":"（７月２８日に「８４％の方」と答弁訂正あり） また、区といたしましては、同意率３分の２以上というところで、権限はございませんけれども、やはり丁寧に対応していただきたい、より多くの方にご理解いただいた中で進めていただきたいということは常々。","id":"exchange-053"},{"speaker":"安藤委員","kind":"質問","question":"ですから、出すなって言っていいと思うんです。この段階であなた方、全然駄目でしょうと、この国会決議に照らして努力しているんですか、周知徹底不十分じゃないですか、考慮してくださいよと、やっぱり強く言うべきだと思うんです。私はそう思います。指導者として、指導する立場の者として、国会決議と整合性が取れているという立場ということでよろしいんですか。伺います。","respondent":"中道都市開発課長","answer":"都市開発課の課長といたしまして、現在、事業認可申請を東京都のほうに送付いたしました。指導の仕方としましては、今現在やるべきことはきちんとやったというふうな考えです。","id":"exchange-054"},{"speaker":"中塚委員","kind":"質問","question":"今もやり取りを伺いましたけれども、まちづくりの主体である地域住民が強く反対している武蔵小山再開発は直ちに中止すべきだと、初めに述べておきたいと思います。要するに中止してくださいと、小山３丁目再開発を中止してくださいと上がっているのだから、区の考えをまず示すのが行政の姿勢じゃないですか。は区の立場を表明する、そういうことが必要だと思うんですけれども、いかがでしょうか。","respondent":"中道都市開発課長","answer":"質疑の中でこういった明確な形で対応するです。ですが、今、委員からそのようなお話がございましたので、今後、円滑な議会運営というところで、どのように対応していくのか検討したいと思います。","id":"exchange-055"},{"speaker":"中塚委員","kind":"質問・要望","question":"ありがとうございました。やはり区民の方がここについて説明してくださいという陳情に対しては、冒頭、区としてはこう考えていますとか、この数字は何人ですとか、この数字は準備組合から非公表だと言われているので区としては把握していませんとか、まずそこは出さないと議論が始まらないと思いますので、ぜひ今後の対応について、まずご検討いただきたいと、これは要望しておきたいと思います。","respondent":"中道都市開発課長","answer":"反対している方々もいらっしゃいますが、やはりこういったまちづくりに賛成している方々もいらっしゃるというところで、繰り返しになりますけれども、区といたしましては、１人でも多くの方にご理解をいただきたいという中で進めてきましたが、今。","id":"exchange-056"},{"speaker":"中塚委員","kind":"質問","question":"地域住民が反対しているのになぜ進めるのかと伺いましたら、反対の人もいるけれども賛成の人もいるから、賛成の人の側に立って進めていくという、ひどい答弁だなと思いますよ。賛成と反対が分かれているのであれば、引き続き協議していくというのだったら分かります。これが区長の言う、また部長も言った、まちづくりの主体は地域住民であるという答弁の意味なんですか。伺います。","respondent":"中道都市開発課長","answer":"区といたしましても、もちろん１００％の同意という中でまちづくりを進めたいという思いは委員と同じですが、一方で、そういった中で賛成の方が非常に多くいらっしゃる、時間も非常にかけた中で今現在に至っているというところで、最終的には。","id":"exchange-057"},{"speaker":"中塚委員","kind":"質問","question":"がしかしという説明でしたけれども、じゃあ、ちょっとトーンを変えて、反対している住民も地域住民だと、そういうふうに区は考えているということなのか、それとも賛成している住民しか地域住民と考えないと乱暴なことを考えているのか、そこを伺います。その中で、区長も部長も言う地域住民というのは、賛成している人だけなんですか。反対している人も入っているんですか。そこを伺いたいと思います。","respondent":"中道都市開発課長","answer":"区といたしましては、引き続き、準備組合に対して多くの同意をいただいた中で進んでいくといった形で進めていきたいというのは常々、準備組合のほうにも伝えておりますし、準備組合も今後、権利変換を行う中で。","id":"exchange-058"},{"speaker":"中塚委員","kind":"質問・要望","question":"やめてほしいというのが住民の願いですから、そこは理解していただきたいと思います。いよいよこういう取組が必要だと思うんです。改めて伺いたいのは、もう一度その都市計画決定の取消しの手続をご説明いただきたいのと、小山３丁目第１地区で何人かの地権者の方々が取消しのために、まちづくりを変えようと集まった際には、区としてはまちづくりとして支援をするのか伺いたいと思います。","respondent":"高梨都市計画課長","answer":"都市計画の変更の手続ですけれども、かねてよりご答弁していますように、現在決まっている都市計画を変えようという場合には、都市計画の変更の手続、決定のときと同様に、都市計画の案を都市計画審議会にかける等々して、変更の手続がそこでできるという審議がなされれば。","id":"exchange-059"},{"speaker":"中塚委員","kind":"質問・要望","question":"今、課長からご説明があったように、変更の手続を進めていく、そのためには、まちづくりの支援として小山３丁目第１地区の何人かの地権者に集まっていただいて、決定の取消しを進めていこうということに対して、今、課長の答弁でも、方向にかかわらず自主的なまちづくりを支援していくというふうにおっしゃるわけですから、ぜひこの再開発、都市計画決定の取消し。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"せお副委員長","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。課長からの答弁もありましたように、区は、準備組合に対して引き続き丁寧な説明をということで対応していただいているので、そういったところも引き続き行っていただきたいという要望も入れて不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"松永委員","kind":"意見","question":"本日結論を出すで、不採択でお願いいたします。先ほどの説明とか議論を踏まえて、再開発については法律にのっとって住民同士は話し合うものであるから、そこの意見をぜひ尊重していただければと思います。で、不採択にいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-062"},{"speaker":"ゆきた委員","kind":"確認","question":"本日結論を出すで、不採択でお願いします。準備組合の臨時総会の中身についてのことであり、区では把握するのが難しい点と、資金計画や工期の変更についても、民間である準備組合が進める事業であることを確認させていただきましたので、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"安藤委員","kind":"質問","question":"本日結論を出すで、採択でお願いしたいんですが、２２９億円もの税金が投じられる事業でありまして、決定に関わる情報というのは当然、こうした形で区民の方も、特に当事者の方が自分の暮らしをかけて問うているわけですから、当然こういった情報は出すべきだと思いますので、賛成です。採択をお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"中塚委員","kind":"質問・要望","question":"今日結論を出すということと、採択でお願いいたします。重ねて述べますけれども、やはり説明を求めるという陳情に対しては、まず区の考えを示してほしいということと、説明を求めるというこの対応は、通常、開発の窓口でも説明できることだと思うんです。あわせて、武蔵小山の再開発は直ちに中止をと、重ねて求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"ゆきた委員","kind":"確認","question":"本日結論を出すで、不採択でお願いします。先ほどの内容と重なるところもありますが、それとあわせて、理事者からもご説明があったように、地権者からの都市計画書では８０％以上の同意書が集まって、都市計画法に基づいた内容で進められている点を確認させていただきましたので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"安藤委員","kind":"意見","question":"本日結論を出すで、武蔵小山再開発、小山３丁目第１地区は本当に中止すべきだと思います。それが前提なんですが、法の枠組みで、区長は出された申請を無効とすることまではできないんですけれども、今回の準備組合のこの反対住民を多数残したままの申請というのは、もう不当そのものだと考えています。したがいまして、趣旨採択でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-067"},{"speaker":"中塚委員","kind":"質問","question":"今日結論を出すということと、趣旨採択でお願いします。理由は先ほどと同じように、武蔵小山の再開発はやめるべきだと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。区としても、説明会等を踏まえて周辺住民に情報を周知するように準備組合にお願いをしていくといったところで、現在求められているのを確認させていただきましたので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"安藤委員","kind":"質問・要望","question":"本日結論を出すで、採択をお願いしたいんですが、１０１名の方から中止を求める陳情ということで出されております。住民を追い出して、環境を壊して、莫大な税金投入と、こういった開発はやめるべきだと思いますので、採択をお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"中塚委員","kind":"質問・要望","question":"今日結論を出すということと、採択でお願いいたします。再開発について様々議論をしてきましたけれども、今日は特にテーマはこのことですが、最近、住宅が高騰したり、家賃が高騰したり、その要因がこの再開発の拡大だということも指摘されております。今日もいろいろ意見させていただきましたけれども、抜本的な見直しを強く求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"}]},{"id":"topic-05","title":"第１２期品川区廃棄物減量等推進審議会答申","agenda":"第１２期品川区廃棄物減量等推進審議会答申","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"１点だけ。今回の答申で、家庭ごみの有料化というのは入ったのでしょうか。伺います。","respondent":"篠田品川区清掃事務所長","answer":"今回の答申の中では、家庭ごみの有料化というのは具体的な項目としては入ってございません。議論の中では一部の委員からもお話がございましたけれども、答申の中には含まれていないものです。","id":"exchange-072"},{"speaker":"安藤委員","kind":"意見","question":"よく分かりました。有料化は、一時的に減ったとしても、すぐまたリバウンドするということで、区民負担を増やすだけということが言われております。今、この物価高で、区民生活が苦しい中で、安易に行うべきではないと、絶対行うべきではないということを改めてこの場をお借りいたしまして申し上げておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-073"},{"speaker":"ゆきた委員","kind":"確認","question":"令和６年度から資源プラスチックの回収が本格的に始まって、答申の２１ページにも、令和６年度の回収実績は令和５年度より２１％増加と、効果が出ているというのを確認させていただきました。ですが、現場からは、どのくらいの実績が出ているのかをさらに周知してほしいと、そういったお声もあります。厳しいお声の中では、パレット以外、ほかは何になっているのだというようなお声もあります。","respondent":"篠田品川区清掃事務所長","answer":"こちらの周知につきましては、ホームページ等もありますけれども、また私どもでも「ごみ・リサイクル通信」といったものも発行していますので、様々な媒体を使って区民の皆様へのお知らせに努めてまいりたいと考えているところです。","id":"exchange-074"},{"speaker":"ゆきた委員","kind":"確認","question":"確認できました。周知の方法で、広報しながわでの特集を増やしたりとか、あと、短い動画で、活用するものがこういったものになっているというのをさらに周知していくことを検討していただければと思います。より一層広報に努めていって、教育にもつながるような形にしていただければと思いますので、お願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"中塚委員","kind":"質問・要望","question":"審議会でも熱中症対策を伺って、ファンがついている服を着てやられているということで、私も確認をしておりますけれども、やはりさらに暑くなっているという面では、職員の方が働きやすい環境といいますか、６月なのに朝からこんなに暑いという状態ですので、より一層の熱中症対策、働きやすい環境は知恵を出して生かしていただきたいなと思うのです。","respondent":"篠田品川区清掃事務所長","answer":"今、委員からご紹介いただいたとおり、昨年度からファンつきの作業服を入れまして、それが相当涼しいということで、実は、入れてないころには、外が３５度のときに３５度の温風を入れても暑いだけではないかという指摘もあったのですが、作業している者からすると。","id":"exchange-076"},{"speaker":"せお副委員長","kind":"質問・要望","question":"こちらにも書かれているように、私も事業系ごみがすごく気になっています。本当に区は頑張ってやっていただいていると思います。こちらの答申の中にも、東京都の３Ｒアドバイザーと連携してというのもあるのですけれども、もっと何か東京都と連携できることはないのかなと思っています。そういったところで今考えていることがあれば教えていただきたいです。","respondent":"篠田品川区清掃事務所長","answer":"そういう意味では、資料にも書かせていただいているとおり、東京都と様々な形で連携をするような形も考えているところではあるのですけども、やはり東京都も直接収集しているわけではないものですから、なかなかそういったところで難しい点があります。","id":"exchange-077"}]},{"id":"topic-06","title":"西小山分室の閉鎖","agenda":"西小山分室の閉鎖","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"３点伺いたいです。それと、区民サービスの低下なしと書かれています。３点目は、今日をもってということですが、西小山分室というのはどれぐらいの建物で、どれぐらいの敷地面積で、それは区が所有しているものなのかとか、どこにあるのかとかというのをちょっと改めて伺いたいと思います。","respondent":"篠田品川区清掃事務所長","answer":"地上３階建てで、敷地面積が２３５.８７平米ということで、延べ床面積が３１８.９２平米ということになります。施設としては本当に小さい施設です。現状は先ほど申し上げたとおり、今日までいる職員は全部で１６人の職員がいるという施設です。","id":"exchange-078"},{"speaker":"安藤委員","kind":"質問","question":"待ち時間が増えるということになりますと、いわゆる拘束時間、労働時間が増えてしまうのではないかとかと、ちょっと心配してしまうのですが、待ち時間が若干増えるかなという点に対しての対策とかというのは考えていらっしゃるのかというのと、それとあと、もう廃止ということなのですけれども、この跡地については何かもう既にお考えを持っているのか、どんな検討を、これからなのか。","respondent":"篠田品川区清掃事務所長","answer":"職員が全員ここから出ていくことになりますと、完全に空いた施設となります。区役所の場合は、施設の有効活用、跡地活用に関しましては、企画課のほうで担当していますので、そちらのほうに話を持っていって、今後の対応については検討してもらっているという状況です。","id":"exchange-079"}]},{"id":"topic-07","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"所管質問ということで、のだて稔史議員の一般質問で、「２９号線道路と戸越公園駅北地区再開発は中止し、住民参加で緑と福祉のまちづくりを」という項目から質問したいです。質問ですけれども、部長の答弁では、風の状況について区民から声が寄せられていると。区長に伝えたということなので、そのリアクションというのですか、そこを質問したいなと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"安藤委員","kind":"質問","question":"所管質問なのですけれども、６月２７日の筒井議員の「新駅の可能性について」の質問で、東山手ルートでの可能性について質問があったと思います。検討事業と予算にも計上されていると思うのですけれども、その内容と、あと現時点でどのルートのどこで検討可能性を探っているのかということの候補地について教えていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-081"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/570689?Template=document&Id=7097#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":70359,"voices":221}},{"id":"r07-20250630-9","meetingId":"r07-cm06","date":"2025年6月30日","dateIso":"2025-06-30","committee":"文教委員会","time":"午前１０時００分～午後 ２時０１分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を73件抜き出しています。","topics":[{"id":"topic-01","title":"第８５号議案、学校教育職員の勤務時間、休日、休暇等に関する条例の一部を改正する条例、(10)第８７号議案、幼稚園教育職員の勤務時間、休日","agenda":"第８５号議案、学校教育職員の勤務時間、休日、休暇等に関する条例の一部を改正する条例、(10)第８７号議案、幼稚園教育職員の勤務時間、休日","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回の条例改正では、区の固有教員と区立幼稚園教員の方が対象になるということなのか、対象を伺いたいと思います。今の実際の品川区内での子育て部分休暇の利用の実態はどうなっているのか伺います。","respondent":"酒川指導課長","answer":"今回の条例の対象は、区の固有教員、それから幼稚園教員、区費の職員になります。都費の一般の教員については、都の条例で定められております。休暇の取得状況について、統計等は今、ご説明申し上げられませんが、十分取得が勧奨されていると捉えております。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"利用人数というのは、この間、いつからか使えるようになってから、ある時点で何人利用したとか、そういったことは分からないのでしょうか。","respondent":"酒川指導課長","answer":"今回の８５号議案と８７号議案についてでしょうか。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、利用数が分からないということなので、ぜひ、この制度ができたわけなので、利用していただきたいと思いますし、また、新たにこの取得パターンができるということで、今後、区としては、この利用が進む想定なのか、進めていきたいという思いもあるのかというところで伺いたいと思います。","respondent":"酒川指導課長","answer":"先ほど説明したところで少し分かりにくかったかもしれませんが、これまでは３０分を単位として１日に２時間以内ということで、１日に２時間という上限があったわけですけれども、この上限を年間７７時間３０分の範囲で取れるということで。","id":"exchange-003"},{"speaker":"まつざわ委員","kind":"意見","question":"だから、その部分に関して、例えば職員のマニュアルといいますか、こういうのを取っていいのですよ、どんどん取りましょうとか、そういったマニュアルを配布して、こういう部分休暇を取りやすいようにするべきではないかと思うのですけれども、今何かやっていることはありますか。","respondent":"酒川指導課長","answer":"そういった情報提供、マニュアルですとかは、通知をしています。広報等々を通して広く全職員に周知するということをやっております。今回の条例では、そういったことを周知することが所属長に義務づけられたということで、今まで以上に周知が図られると捉えております。","id":"exchange-004"},{"speaker":"横山委員","kind":"確認","question":"１点確認だけなのですけれども、令和７年度の３８時間４５分というのは、１０月からスタートということで、その分短くなっているということで大丈夫でしょうか。","respondent":"酒川指導課長","answer":"そのとおりです。","id":"exchange-005"},{"speaker":"高橋（し）委員","kind":"質問","question":"改正の概要の２番目・３番目のところに、先ほどお話ありましたけれども、管理職が意向等を配慮とかを義務づけるとありますが、これは都費の先生も一緒だと思うのですけれども、義務づけるということは、どうしますか、取りますかという話をしたときに、何か書類というか、残すものが、現在もやっているとすると、そういうのがあって。","respondent":"酒川指導課長","answer":"そういった書類での約束の取り交わしというのは想定しておりませんで、まずはそういった申告があった教員に対して、こういう制度がありますという紹介をして、どうしましょうかという意向確認をした上で、その後は当該職員がそういった紹介に基づく制度の申請をするということで。","id":"exchange-006"},{"speaker":"高橋（し）委員","kind":"確認","question":"確認を義務づけるとあるので、聞きましたと話を管理職の方が言っただけでは、別に言った、言わないで云々という意味ではなくて、このように確認しました、そうしたら教職員が取りたいと言いました、それで取りましたという流れみたいなものは、年休とかを取るのはきちんと書類が出たりするのですけれども、ここに義務づけるとわざわざ書いてあるところが。","respondent":"酒川指導課長","answer":"現在そういった確認を行いましたということを確認するといいましょうか、立証するというか、そういった書類等々はないわけですけれども、管理職へは確実にこれを周知し、意向確認を行うように改めて伝えていきたいと考えています。","id":"exchange-007"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"情報提供はしていただくというのは、先ほどほかの委員からもお答えいただいたのですけれども、そこのところは何らかの形式というか、方式を整えていただいたほうがいいと思います。これは要望で、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"若林委員","kind":"質問","question":"今の高橋しんじ委員のお話も、ごもっともなお話だなと。この場合、校長先生の責務というのでしょうか、義務づけに対する役割というのはどういうものなのですか。","respondent":"酒川指導課長","answer":"本来は、これは教育委員会が周知の責任を負っております。それを直属の現場の所属長である校長が代行するという形で、申請は教育委員会が受け取るという形になっております。","id":"exchange-009"},{"speaker":"若林委員","kind":"質問・要望","question":"最終的には教育委員会が、義務づけについてはしっかりと確認をしていくという、確認という言葉を私は使いますけれども、教育委員会が最終的に確認すると。そして、こういう委員会等で１年間、いろいろな報告の中で私たちのほうから確認した場合に、しっかりと義務づけが徹底されています、そのエビデンスはこういうことですというようなご答弁がいただけるということを確認させていただきたい。","respondent":"酒川指導課長","answer":"そのようにするものと捉えております。","id":"exchange-010"}]},{"id":"topic-02","title":"第８６号議案、学校教育職員の旅費に関する条例の一部を改正する条例","agenda":"第８６号議案、学校教育職員の旅費に関する条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"確認なのですけれども、都の改正内容と今回の改正内容というのは同じ改正内容になるのかというのと、宿泊費のところで、上限があって、そこまでは実費支給になるということでしたけれども、上限をオーバーするようなことというのはあり得るのか伺いたいと思います。","respondent":"酒川指導課長","answer":"その他の地域については１万円が上限だったのですが、例えば今回の改正では、埼玉・東京・京都は１万９,０００円まで上限を引き上げますということで、８,０００円アップ、これは近頃の宿泊費の高騰への対応と認識しております。","id":"exchange-011"},{"speaker":"のだて委員","kind":"質問・要望","question":"宿泊費のところでは上限額が引き上がったということで、今までよりはオーバーする可能性が減ったのかなというのもありますけれども、つまりは教員の負担になってしまうような事態というのがどのくらい起こり得るのか、あまりそういった負担にならないようにしていただきたいと思っているのですが、いかがでしょうかというのと、今回いろいろ名称変更などもありますが、改正したときに。","respondent":"酒川指導課長","answer":"私自身の経験を踏まえても、かなりこの上限額の引上げというのは経済的負担が減ると考えておりますし、今回の条例改正全体を通しても、かなり柔軟な移動・宿泊が可能になると捉えております。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問","question":"実感も含めて、負担が減るということですので、そうすると、今まで結構、教員の方は、旅費としていろいろ負担をされてきたということなのですか。今までの実態を少し説明いただけたらと思います。","respondent":"酒川指導課長","answer":"一例になりますけれども、例えば関西地方に出張するといったところで、大阪までは新幹線で移動できました。それから、大阪を起点に南北に１００ｋｍ程度移動するとなったときに、１００ｋｍを超える場合は特急料金が出ます。ただ、１００ｋｍを超えない場合、特急料金は出ません。","id":"exchange-013"},{"speaker":"高橋（し）委員","kind":"確認","question":"今お話あったように、柔軟な対応になったということで、パックができるというのは、かなり教職員の方にとっては利用しやすい状況と思ったのですが、それはそれとして、改正の概要の（１）の4)のところのレンタカーの賃料等の仕組みを変えるということで、今までタクシーで移動したところをレンタカーになるので、引率の先生方にとっては使い勝手がいい、どこかから行ってまたタクシーとかいうよりも。","respondent":"酒川指導課長","answer":"当然、事故が起こる可能性もありますし、公務災害という部分になりますので、保険等々の補償をしっかりしていくということと、あわせて、レンタカーを使うといった場合は気をつけましょうというのは、これは私どもがあえて言うことではないのかもしれませんけれども。","id":"exchange-014"}]},{"id":"topic-03","title":"第７６号議案、品川区給付型大学奨学金条例、(2)第７７号議案、品川区給付型大学奨学金運営委員会条例の２議案","agenda":"第７６号議案、品川区給付型大学奨学金条例、(2)第７７号議案、品川区給付型大学奨学金運営委員会条例の２議案","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"よりよいものにという思いで質問したいと思うのですけれども、まず確認ですが、今回、申請を見込んでいる人数はどのぐらいなのか、そして対象の学部に、これらに類する学位を授与できる学部ということで書かれているのですが、どういったものが対象になるのか伺います。","respondent":"柏木子育て応援課長","answer":"１つ目の申請者数の見込みですが、約２７０名と見込んです。","id":"exchange-015"},{"speaker":"のだて委員","kind":"質問","question":"学部のところは、理工学部とかというところもあったりします。そういうところは明らかに対象になると思いますけれども、そういうものが対象になるということで、分かりました。それと、もう１つ要件として、区内地域貢献活動への定期的な参加ということで書いてありますけれども、これはどういったものになるのか伺いたいと思います。","respondent":"柏木子育て応援課長","answer":"今想定していますのは、町会・自治会のボランティア活動で地域防災など、あと、青少年育成や環境美化、消防団の活動、社会福祉協議会のボランティア活動、そういうものを想定していますけれども、今後要綱でもう少し詳しく決めていきたいと考えています。","id":"exchange-016"},{"speaker":"のだて委員","kind":"質問・要望","question":"学業が本分だと思うので、そこをおろそかにして、定期的に参加をしなければいけない、おろそかと言うと言い過ぎかもしれませんけれども、そういうことにもなりかねないという危惧もあるし、参加できなくなってしまう、参加できないと取消しにもなってしまうということになるので、そうしたことがないように、多くの子どもたちに学ぶ機会を保障していただきたいと思うのですけれども、いかがでしょうか。","respondent":"柏木子育て応援課長","answer":"例としましては、大学によっては１年生のときに、他県のキャンパスに１年間、全寮制で通うという大学もあると聞いてありますので、そうなってくると、その方とかは長期の休みでないと参加できないというのもありますので。","id":"exchange-017"},{"speaker":"のだて委員","kind":"質問","question":"今ご紹介いただいたように、他県に行かなければいけないということもあるので、そうでなくても、他県の大学に入学したりすると、全寮制でそこに住むことになったりすると。そういった人も、区内の地域貢献活動に参加をするということなので、また新たなハードルになってしまうのではないかという危惧があるのですけれども、その点はどのようにお考えでしょうか。","respondent":"柏木子育て応援課長","answer":"他県等の大学の場合は、時間的制約等はありますけれども、先ほど申しましたとおり、地域の将来に不可欠な人材育成というものを重視していますので、当然、学業が優先にはなると思いますけれども、地域に貢献する活動について、必ず参加していただきたいです。","id":"exchange-018"},{"speaker":"のだて委員","kind":"質問・要望","question":"柔軟な対応、今後運用を見ていきたいと思います。それと、運営委員のメンバーなのですけれども、今回、区議会議員と学識経験者、区の職員ということで、約１０人以内ということなのですが、人数構成はどうなっているのか伺いたいのと、これが公平・公正に選定されるようにしていかなければならないと思うのですけれども、恣意的にならないようにするというのはどのように担保していくのか伺います。","respondent":"柏木子育て応援課長","answer":"運営委員会の構成人数ですが、今、想定ですけれども、区議会議員につきましては２名、学識経験者、説明の中で高等学校の校長先生と申し上げましたが、４名。区の職員が、幹部職員でありますけれども、こちらの４名で、計１０名というのを想定しています。","id":"exchange-019"},{"speaker":"のだて委員","kind":"質問・要望","question":"恣意的にならないように個人名を伏せたやり方でやっているということで、そうすると、この間、高校生の奨学金制度では、そうした恣意的な事例というのはないという認識でいいのか、確認させていただきたいのと、あと給付額、今回年額で５４万円ということで、国立大学の授業料を参考に定めていると伺っているのですけれども、東京大学は今年度入学者から１０万円も値上げして。","respondent":"柏木子育て応援課長","answer":"次に給付額ですけれども、今回給付額につきましては、文部科学省が定めております国立大学の授業料を基本としていますので、今後、国が授業料等の増額をした場合につきましては、その状況を見ながら、年額について改定することはあり得ると思います。","id":"exchange-020"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回、医療系と理工農系に限られているわけですけれども、そこの学部に絞った理由を伺いたいと思います。この中で、短期大学ですとか、大学院、専門学校は除かれているということで、ここを除いた理由を伺いたいと思います。今後はぜひこうしたところも対象拡大をしていっていただきたいと思うのですけれども、いかがでしょうか。","respondent":"柏木子育て応援課長","answer":"今後学部を拡大するのかというお問合せですけれども、まずはこちらの医療系学部と理工農系学部に特化した事業として実施をしていきたいと考えています。ただ、今後、国の制度等を注視しつつ、区民の声を聴きながら、事業内容については検討するものと考えています。","id":"exchange-021"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"それで、今、区内地域貢献活動、大変すばらしいと思っているのですけれども、それこそ、せっかくそういったものを対象にしてやるのであれば、例えば仮に、せっかくそういうのが集まったときに、年に１回可視化をして、そういった方たちの地域貢献がどういうことをやっていますとか、そういった部分のこういうボランティアはいいですよとか、せっかくならそういった見える化といいますか。","respondent":"柏木子育て応援課長","answer":"最初にいただきました夜学ですとか、そういう部分の件ですけれども、今後この事業を実施していきながら、区民の声等も聴きながら、事業内容については検討していきたいと考えています。それと、地域貢献活動の奨学生同士の情報交換という感じですか。","id":"exchange-022"},{"speaker":"まつざわ委員","kind":"質問","question":"１つ、連帯保証人なのですけれども、今回、連帯保証人は親がやりますよね。大学の承認をつけてやりますけれども、少し調べると、現在の奨学金は保証人不要型というのがあるのですか。","respondent":"柏木子育て応援課長","answer":"高校生の奨学金事業も同じく、高校生ですので連帯保証人の設定をしています。連帯保証人は、特に誰という指定はないのですが、大体保護者等１名を想定しています。","id":"exchange-023"},{"speaker":"横山委員","kind":"質問・要望","question":"今、議論になったところなので、私も連帯保証人のところで気になっていた部分があるのですけれども、こちらなのですが、なかなか確保が難しいような、保護者の方がなかなか理解していただけないとか、何らかの理由があって、例えば本人のお気持ちとしたり、また、地域貢献活動をしたりとか、学業成績も優れていて、それ以外の部分は意欲もあってというところであっても。","respondent":"柏木子育て応援課長","answer":"６年制の医学部等にどれぐらいいるのかによりまして変わりますので、そこの見込みはまだできてはございません。学部の拡大につきましては、今後、区民の方からいろいろなお声をいただくと思いますので、そういう声を聴きながら検討していきたいと考えています。","id":"exchange-024"},{"speaker":"横山委員","kind":"質問・要望","question":"初めてスタートしていくものですから、これから区民の方々ですとか、子どもたちご本人にもいろいろ意見を聴いていただいて、制度をよりすばらしいものにしていっていただきたいと考えていますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"すみません、幾つかお尋ねします。文系の要素もありますけれども、経営工学とかの世界だと、それで情報学士とかになるので、そういったものも理系だと思うので、お願いします。そこを確認します。それからもう１つは、先ほど申請者の名前は分からないようにするとあったのですけれども、区の関係者や、例えば議員の子弟からも、これは応募ができるのでしょうかというところの確認です。お願いします。","respondent":"柏木子育て応援課長","answer":"その詳細については今後詰めていく予定です。次は、区の職員ですとか、区議の子どもとかも申請できるのかと。特にそこは制限を設けてございませんので、申請は可能です。それと、地域貢献のプロジェクトですが、今後検討していきたいと考えています。","id":"exchange-026"},{"speaker":"高橋（し）委員","kind":"質問","question":"最後に１点だけ、不良の話は、４年生まで奨学金をもらって勉強していたのだけれども、これで４年では卒業できないな、５年生になってねという話になったときには、５年生のときはもちろん奨学金は出ないですけれども、１年から４年までの全部を返してとなるのかどうかというところも、今後検討になるわけですか。","respondent":"柏木子育て応援課長","answer":"返還の全部なのか一部なのかという部分につきましては、これまでのその子どもの活動等を踏まえた上で、運営委員会で審議をして決定するという運びになります。詳細は今後また詰めていきたいと考えています。","id":"exchange-027"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"現状の高校３年生、あるいはその後の２年生、１年生の保護者、本人も大変期待している仕組みですので、ぜひしっかりと進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"若林委員","kind":"質問・要望","question":"いわゆる運営委員会の決定があって、一応、今のところ１００人ということで、当然、申請者数のほうが多いでしょうという見立ての中で、この決定に不服があったときの手続等の取決めが、この条例にはないのですが、なぜないのかというか、考え方というか、そこは手続がどうなるのかという、情報公開も含めて、情報公開しないと理由については明らかにできないのかというところを教えていただきたいなと。","respondent":"柏木子育て応援課長","answer":"来年度以降の給付のスケジュールですが、現状では今回と同様の考えですけれども、今、委員からいただいた意見も含めて、来年度のスケジュールについては改めて検討したいと考えています。","id":"exchange-029"},{"speaker":"若林委員","kind":"確認","question":"来年度以降のスケジュールについては、４月に入学して３月に確認・給付というのは、現実的には、これを受けて大学に通う学生たちにとっては酷かなというところもありますので、ぜひ柔軟に、前向きに決めていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"筒井副委員長","kind":"意見","question":"私からは、給付期間中、給付要件として、区内における地域貢献活動に定期的に参加できることというのがあるのですけれども、今回、目的として、将来、地域社会に貢献する人材を育成することを目的とするとありますが、今述べたように、給付期間中は区内において地域貢献活動をやることを要件に、やられると思うのですけれども、将来、地域社会に貢献する人材ということで、卒業した後。","respondent":"柏木子育て応援課長","answer":"それと、それに関わる審査ですけれども、今、審査基準については、中で検討していますが、将来的なところも入れるのかどうかというのは、また検討の中で考えたいと思います。","id":"exchange-031"},{"speaker":"筒井副委員長","kind":"質問・要望","question":"当然、縛りというのは現実的に難しいと思うのですけれども、ただ、そういった現実的な状況がある中、申請者の方が申請段階で、すごく私は品川区のために、品川区に住んで、そして品川区の関連企業に入って、品川区に貢献したいという方がいらっしゃったら、それは結構ポイントが高いというか、優先順位が高くなると個人的に思うのですけれども、その辺り。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"高橋（し）委員","kind":"質問","question":"すみません、さっき聞き忘れてしまったのですけれども、日本学生支援機構の奨学金があると思うのですが、それを借りるときに、品川区からこの奨学金をもらっているとすると、それが借りられなくなってしまう可能性はあるのですか。それとも、それは大丈夫なのですか。","respondent":"柏木子育て応援課長","answer":"そちらの奨学金につきましては、品川区の奨学金と併用可能と確認しています。","id":"exchange-033"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、逆に日本学生支援機構の奨学金をもらっていても、品川区のほうは申請ができるということでよろしいですか。逆のこともオーケーだと。","respondent":"柏木子育て応援課長","answer":"今、委員ご指摘のとおりです。","id":"exchange-034"}]},{"id":"topic-04","title":"第８０号議案、品川区家庭的保育事業等の設備および運営の基準に関する条例の一部を改正する条例","agenda":"第８０号議案、品川区家庭的保育事業等の設備および運営の基準に関する条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、管理栄養士養成施設卒業者が、栄養士の免許を取得していなくて管理栄養士になれるということで、この卒業者というのは、栄養士と同等の知識などを持っているのかどうかというところを伺いたいと思います。つまり、安全性が変わらないのかどうかというところを伺いたいのと、あと、区内ではこの対象になるところがあるのかどうか伺います。","respondent":"佐藤保育事業担当課長","answer":"対象施設についてですが、今回の対象の特例の適用を受ける施設ですが、区内にあります家庭的保育事業所等の中で、自園調理を行っていない施設というのはほぼ、ありませんので、本改正に与える影響というのはほとんどないと考えております。","id":"exchange-035"},{"speaker":"のだて委員","kind":"質問","question":"管理栄養士養成施設卒業者は同等の知識を持っているということなので、安全性は変わらないということでよろしいですか。","respondent":"佐藤保育事業担当課長","answer":"おっしゃるとおりです。","id":"exchange-036"}]},{"id":"topic-05","title":"第８１号議案、品川区児童福祉施設の設備および運営の基準に関する条例の一部を改正する条例","agenda":"第８１号議案、品川区児童福祉施設の設備および運営の基準に関する条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、この条例改正をしないと、認証保育所と児童発達支援センターの子どもたちが交流することというのはできないのかどうか伺います。","respondent":"佐藤保育事業担当課長","answer":"改正を行えない場合は、保育所の施設と児童発達支援センターに通われている児童が交流したりするということが、今の段階ではできないというものです。","id":"exchange-037"},{"speaker":"のだて委員","kind":"質問","question":"具体的にできないというところがあれば伺いたいと思います。それを伺います。","respondent":"佐藤保育事業担当課長","answer":"説明が分かりづらくて大変申し訳ございませんでした。一般的な公園とかで交流するということは可能なのですけれども、保育所において、保育所の施設内で一緒に保育を行うということはできないというものです。","id":"exchange-038"},{"speaker":"のだて委員","kind":"質問","question":"なるほど。公園ではできるけれども、保育園内ではできないということになるということですね。今回それができるようになるということで、１つ危惧をしているのは、兼務することで、人員配置が緩和されてしまうということにならないのかと思っているのですが、そこを伺いたいのと、あと、区内にはこういった施設はあるのかどうかと、今後何かできる予定、見込みみたいなのはあるのでしょうか。","respondent":"佐藤保育事業担当課長","answer":"こういった施設があるのかというご質問ですけれども、区内に認証保育所と児童発達支援センターが併設しているような施設というのは、現在はございません。が、認可保育所においては１施設、私立において保育所と児童発達支援センターが併設されている施設はあります。","id":"exchange-039"}]},{"id":"topic-06","title":"第８２号議案、品川区乳児等通園支援事業の設備および運営の基準に関する条例","agenda":"第８２号議案、品川区乳児等通園支援事業の設備および運営の基準に関する条例","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"区の今まで実施してきたトキドキ保育との関係性というのはどうなるのかというのと、これは国が法改正して、こども誰でも通園制度ができたということで、これを区でもできるようにするのだと思うのですけれども、区としてはこれを実施していくつもりなのか伺います。","respondent":"佐藤保育事業担当課長","answer":"続きまして、区としてこれを実施していくのかですが、誰でも通園制度は、令和８年度になりますと給付事業となりまして、全国の自治体が実施しなければならないものであると定められてありますので、実施をしていくものです。","id":"exchange-040"},{"speaker":"のだて委員","kind":"質問","question":"実施しなければならないというところで、そうすると、区立の保育園でも実施していくという考えなのか伺いたいと思います。","respondent":"佐藤保育事業担当課長","answer":"実施施設についてですけれども、現在検討中でございまして、ニーズですとか、あとは本事業を実施していただく施設といったものを勘案しながら、区立での実施についても検討していきたいと考えております。","id":"exchange-041"},{"speaker":"のだて委員","kind":"質問・要望","question":"なので、保育士の配置をきちんとしていかないと、これは子どもにとっても保育士にとっても負担が大きくなるということになってしまうと思うのですけれども、保育士の配置基準を伺いたいのと、保育士の方からお話を伺うと、常に来る子ではない子が入ってくるとなると、そういう落ち着かない部分が多くなってくるので、１人に対して１人の保育士で見られるようにしてほしいと要望があったので。","respondent":"佐藤保育事業担当課長","answer":"このスペースについては、なかなか事業所で確保することが難しいというところではありますけれども、今年度では１０程度の事業所において、一般型のスペースを活用した事業実施をしていますので、区としてもそうした事業者のお話を聞きながら。","id":"exchange-042"},{"speaker":"のだて委員","kind":"質問・要望","question":"一応、支援策を考えていきたいということでした。いかがでしょうか。実際の保育の現場の意見をしっかりと聞いていただきたいと。先ほどもいろいろ聞いているというお話でしたけれども、そこの意見を聞き取って、しっかり子どもたちにとっても、そして保育現場にも負担がかからないようにしていっていただきたいと思いますけれども、いかがでしょうか。","respondent":"佐藤保育事業担当課長","answer":"保育所の配置基準、１対１での配置基準についてですけれども、当然、保育士の方がしっかりと配置されていることというのが、お子様にとって大切なことであると考えていますので、先ほどお伝えしたような補助制度の対象経費の拡大や、補助額の拡大という取組を通じて。","id":"exchange-043"},{"speaker":"のだて委員","kind":"質問・要望","question":"支援をしていくということで、ぜひ人員配置、そして別室を用意できるといった支援をしていっていただきたいと思います。それがなければ、実施していくということは慎重になるべきだと思います。そこのところを区としてもどのように考えているのかというところを伺いたいと思います。今、いろいろな課題が出ている中で、子どもたちにも負担がかかっていると思うのですけれども、いかがでしょうか。","respondent":"佐藤保育事業担当課長","answer":"別室の整備と人員配置につきましては、区としてどういったことができるのかにつきまして、様々継続して議論をしていきたいと考えています。","id":"exchange-044"},{"speaker":"のだて委員","kind":"質問","question":"今回の国の制度ですと、事業者で参入できるのが株式会社を含め、営利企業も参入可能だと思うのですが、そこのところを伺いたいのと、そうした企業が入ってくると、保育の施設ですとか、経験豊富な保育士をきちんと確保できるのかという問題があると思うのですけれども、いかがでしょうか。","respondent":"佐藤保育事業担当課長","answer":"本事業の参加できる企業についてですけれども、まず、本事業は区として認可をした事業所に実施していただくということになりますので、しっかりと人員配置でありましたり、実施する施設の基準であったりというのは把握した上で認可をしていきますので。","id":"exchange-045"},{"speaker":"のだて委員","kind":"質問・要望","question":"十分な配慮をする、認可できちんと確認していくということですけれども、様々な子どもたちが代わりばんこに来るわけなので、経験豊かな保育士が必要になってきますので、なかなか確保していくというのは難しいと思いますし、営利企業の参入というのは、そういう面でもやめるべきだと求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"}]},{"id":"topic-07","title":")第７８号議案、品川区保育の実施等に関する条例の一部を改正する条例、(4)第７９号議案、品川区私立認定こども園","agenda":")第７８号議案、品川区保育の実施等に関する条例の一部を改正する条例、(4)第７９号議案、品川区私立認定こども園","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"確認なのですけれども、資料の中で新旧対照表のところで、最後のほうに延長保育料のところが出てくるのですが、赤い字になっていると思うのですけれども、ここについては変更があるのかどうか伺いたいと思います。それと、認証保育園がどうなっているのかも含めて、認証保育園は対象施設の中には入っていないのですが、現状を伺いたいと思います。","respondent":"芝野保育入園調整課長","answer":"２つのご質問をいただきました。延長保育料の変更ですが、今回の条例の改正附則で改正する形になっております。","id":"exchange-047"}]},{"id":"topic-08","title":"第７１号議案、令和７年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第７１号議案、令和７年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"補正予算の説明がありました。区では、認証保育所に入っている方への補助もあると思うのですけれども、これを併せて利用すれば、無償化と同様になるのか、伺いたいと思います。それと、病児・病後児保育の事業拡大ということで、今回、補正でやられるわけですけれども、補正で組むことになった理由を伺いたいと思います。","respondent":"芝野保育入園調整課長、染谷保育施設運営課長","answer":"無償化になるかどうかですが、認可保育園につきましては、今回無償化が達成されるということで、認可外保育施設のほうも認可保育所と同水準までの助成、こちらが想定で８万円を考えているのですが、こちらまで引き上げることによって。実際に開設のめどが立たない場合については、最終補正で減額をするといった対応をしている中ですが、先日の文教委員会でもご報告申し上げたとおり、南品川の１件、施設開設のめどが立っております。","id":"exchange-048"},{"speaker":"のだて委員","kind":"質問","question":"病児・病後児保育は、今なかなか保護者の方も仕事を休めないとか、そうしたことがある中で、病気になった子を預ける場所があるというのは、利用者にはすごく助かると思うのですけれども、本来あるべき姿というのは、子どもが病気になったときに、子どもを見てあげられる、仕事を休むことができるという社会環境をつくっていくということが、子どもにとっても保護者にとってもいいことだと思いますけれども。","respondent":"染谷保育施設運営課長","answer":"そういった体制というのは、区として責任を持って整備していく必要があると考えているところです。","id":"exchange-049"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ区としても、保護者の方が仕事を休んで子どもを見られるという環境整備に力を尽くしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"横山委員","kind":"質問","question":"私からは、病児保育のところをお聞きしたいと思うのですけれども、先ほど２の補正内容の（３）でご説明あったのですが、少し聞き漏らした部分がありまして、７施設とありますが、病児保育施設が６施設と、病後児保育が１施設ということになるのでしょうか。予約システムはすばらしいと思っているところなのですけれども、９月運用開始ということで、まずは３施設から始めるということなのでしょうか。","respondent":"染谷保育施設運営課長","answer":"システムにつきましては、病後児保育につきましても、こちらは公立の部分も含めてですけれども、対象となるように現状準備を進めているところでございまして、当初予算で対応を予定している南品川につきましても、開設は今、９月１日を予定しておりますので。","id":"exchange-051"},{"speaker":"まつざわ委員","kind":"質問","question":"病児・病後児保育で、要は、地域偏在と施設が不足しているというので増やしたわけです。そうすると、増やしたときに、品川区全体のバランスを見て、区としてこれで取りあえず落ち着いたと考えるのか、まだまだ足りないと考えるのか、まず教えてください。","respondent":"染谷保育施設運営課長","answer":"病児保育の需給状況につきましては、現状、こども計画で試算をしているといいますか、計画している需要と供給の数の部分につきましては、今回の２施設を追加することによって、十分需要は満たせるかなと考えております。","id":"exchange-052"},{"speaker":"まつざわ委員","kind":"意見","question":"そうしますと、ある程度落ち着いたというか、区としてはそういう考えがあるわけです。そうすると、病後児保育・病児保育は日中が主なのですけれども、例えば早朝とか夜間の利用の声は、非常に根強くあるわけです。その辺の考え方というのは。","respondent":"染谷保育施設運営課長","answer":"病児保育で早朝・夜間のご利用の枠の考え方ですけれども、これまでもいろいろと区民の方から、病児保育に関するニーズ、お声をいただいているところもありますので、そういったお声をきちんとお聴きする中で、必要性について検討させていただければと考えております。","id":"exchange-053"},{"speaker":"まつざわ委員","kind":"意見","question":"うちの会派のせお議員からお話してほしいというので、要は、障害児の利用助成が増えるということは、それだけ需要があるということに関して、ベビーシッターの方の、例えば障害児、見られますという人の需要と供給というのが、相互性というのは取れるのかというのを聞かせてください。","respondent":"芝野保育入園調整課長","answer":"ただし、この事業が拡充されることによって、また不足するような事態がございましたら、そちらは東京都と連携を取りながら、情報も収集しながら、何か施策が取れるかどうかというのは検討していきたいと考えております。","id":"exchange-054"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"１つ、最後にスケジュールなのですけれども、これが始まるのが令和７年７月です。そうすると、周知が結構大事なのかなと思ったのです。そうすると、いわゆる情報弱者という方は、障害児の家庭であったり、ひとり親であったりというのが、なかなか情報リテラシーに乏しいというところもあったりするので、例えばその辺に特化した周知というのは何か考えているのか教えてください。","respondent":"芝野保育入園調整課長","answer":"今回のベビーシッターのスケジュール案の周知のことですが、４月利用分まで遡って申請を受け付けるということで、四半期ごとに申請を行っておりますので、その際に、こういう事業をしっかりやっていますという周知をさせていただきたいと考えております。","id":"exchange-055"},{"speaker":"まつざわ委員","kind":"質問","question":"四半期ごとにやっているから、今度のものはいいけれども、前の分も改めて、こうやって周知はしてくれるということですか。","respondent":"芝野保育入園調整課長","answer":"すみません、言葉が足りませんでした。４月からしっかりとやっていますということを周知して、４月に遡って申請を受け付けさせていただきたいと考えております。","id":"exchange-056"},{"speaker":"若林委員","kind":"質問・要望","question":"一方で、ベビーシッターについては、既存の一時預かり事業では対応可能な事業者が幼児を預かることもあったのだけれども、今回、都は検証事業として、質とか安全性、派遣体制を確保した認定事業者に対して、１時間当たりの補助基本額を大幅に増額し、支払いも都が直接事業者に行うなど、事業者と利用者双方にとって拡充された事業を、東京都が今年度行っているという、東京都の事業ですけれども。","respondent":"染谷保育施設運営課長、芝野保育入園調整課長、佐藤保育事業担当課長","answer":"１点目、早期開設の部分ですけれども、こちらについては、補正予算が議決をいただけた場合については、速やかに準備を進めてまいりまして。最後に、補助金の今回の値上げによって、事業者がどのような動き、値上げをするのかですが、認可外保育施設ですので。加えまして、プログラムの検討などをすることで、保育者間の連携というのも強化されたというお声も聞いております。","id":"exchange-057"}]},{"id":"topic-09","title":"令和７年陳情第２０号、「税負担化」を「無償化」とミスリードする公立学校の制服無償化事業の廃止及び、住民税の減税を求める陳情","agenda":"令和７年陳情第２０号、「税負担化」を「無償化」とミスリードする公立学校の制服無償化事業の廃止及び、住民税の減税を求める陳情","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"制服無償化をやめて住民税減税をということですけれども、実際、住民税を減税すると、１人当たり幾らになるのかというのは計算されているのか伺います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"のだて委員","kind":"質問","question":"年収８００万円のところまで、一番重いのは消費税ということになりますので、そうしたところにこそ目を向けるべきではないかと思います。物価高で暮らしが大変なので、負担を下げてほしいという思いは分かりますけれども、考え方が少し違うのではないかと思います。実際、無償化すると、制服をなくすことができないのかというのを区に伺いたいと思います。","respondent":"石井学務課長","answer":"様々な選択肢がある中で、きちんと制服の在り方について考えていくことが必要と考えております。","id":"exchange-059"},{"speaker":"のだて委員","kind":"意見","question":"制服の無償化と必要性については、別問題だということでした。制服の無償化がなぜ必要かといえば、やはり制服の負担が重いということです。いろいろ負担をする中で、全体を合わせれば１０万円程度になってくるということになる。区も引き合いに出していますけれども、憲法第２６条の義務教育の無償化、これを実現していく第一歩ということだと思いますので、私はぜひ必要なものだと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-060"},{"speaker":"筒井副委員長","kind":"確認","question":"確認を含めて、現在、品川区の学校では生徒全員が制服を着ているのかということと、あと、制服の教育的効果というのはどのようにお考えなのでしょうか。","respondent":"石井学務課長","answer":"教育的な効果の部分につきまして、私が教育的効果についてそこまで言及するのは難しいのですけれども、令和７年の予算特別委員会の議論の中では、教育的な効果の部分としては、例えば教育環境を整えることですとか、生徒の安全の確保。","id":"exchange-061"},{"speaker":"筒井副委員長","kind":"確認","question":"今回、無償化といっても、クーポンを支給するということで、要は現金を渡してという形ではないのですよね。その確認です。","respondent":"石井学務課長","answer":"紙クーポンではなく電子クーポンの導入ができないかということで、現在、事業者と詳細を詰めているところです。","id":"exchange-062"},{"speaker":"若林委員","kind":"質問・要望","question":"トレードオフみたいな形で減税を求めてくるというのは、今回は標準服の無償化というのが１つのターゲットにされたみたいで、言葉が過ぎるかもしれませんけれども、私は非常に不愉快で、だから減税を求めるのに、トレードオフの対象の事業は何でもいいのではないかと、私は厚生委員会と文教委員会の２つに参加して、そのように感じていますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"筒井副委員長","kind":"質問","question":"本日結論を出すで、不採択でお願いします。理由は、今回の陳情者の方の思いは、私のさきの一般質問でも述べさせていただきましたとおり、現役世代を中心に、物価高騰の一方、給与は上がらず、生活は苦しいという背景があるかと思います。その中で、税の使われ方に対して非常に厳しい見方をされる方が増えてきている。この方も含めて、そうだと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"高橋（し）委員","kind":"質問","question":"結論を出すで、不採択です。理由は、学務課長のお話等を伺って、それで理解しましたので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"横山委員","kind":"質問","question":"結論を出すで、不採択でお願いいたします。先ほどの質疑を伺いまして、子育て・教育に係る経済的負担の軽減は大切だと考えますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"}]},{"id":"topic-10","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"高橋（し）委員","kind":"質問","question":"２５号のほうなのですけれども、自動二輪車というのは、いわゆるバッテリーがついている自転車なのでしょうか。それは教育総合支援センターの庁有自転車なのでしょうかということをまずお尋ねします。","respondent":"丸谷教育総合支援センター長","answer":"こちらの自動二輪車についてですけれども、原動付自転車ということで、いわゆるスクーターのようなものです。教育総合支援センターが所有している庁有車です。","id":"exchange-067"},{"speaker":"高橋（し）委員","kind":"質問","question":"ということは、それで勤務中にこういったことを起こしたので、区の責任で賠償したということでよろしいですか。","respondent":"丸谷教育総合支援センター長","answer":"おっしゃるとおり、勤務中の事故です。","id":"exchange-068"}]},{"id":"topic-11","title":"その他","agenda":"その他","exchanges":[{"speaker":"高橋（し）委員","kind":"質問","question":"これはお尋ねしたいのですけれども、特別委員会ができて、所管が分かれたのですが、例えば、これを質問するという意味ではないのですけれども、５歳児健診のところで、保育園・幼稚園のいわゆる巡回相談のお話が出てきたのですが、そのことをこの委員会で所管質問してもいいのですか。しないのですけれども、所管的にはいいのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"高橋（し）委員","kind":"質問","question":"在り方になってしまうから、あちらになってしまうのですかということを。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"高橋（し）委員","kind":"質問","question":"それで、もしかしたらここの所管ではないのかもしれませんけれども、事務的な対応とか、あと２３区で協力してとか、そういうところはいろいろお話が出てきたのですが、前に私が一般質問でお尋ねした、都立児童相談所が移転するので、そこをというお話をしたことがあって、それは企画のお話になってしまうかもしれませんけれども、そういうことを含めて、児童相談所として、区の中の所管に、今。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ということで、大変な状況の中で一時保護がやられているということは認識していますので、それを解決するために、区の中の他セクションにこういう体制をということで働きかけていただきたいと思っているので、そういうのをしていただけているかどうかというのをお尋ねしたいと思います。答えられる範囲で、担当部署がどういう対応をしているのかということをお答えいただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そうです。具体的に聞けるならば、都児童相談所跡についてどのように、要望しているというと言い方はあれでしょうか、働きかけをしてほしいというふうに他部署もしているかということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/178682?Template=document&Id=7095#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":54512,"voices":317}},{"id":"r07-20250630-5","meetingId":"r07-cm06","date":"2025年6月30日","dateIso":"2025-06-30","committee":"総務委員会","time":"午前１０時００分～午後 ３時２３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を103件抜き出しています。","topics":[{"id":"topic-01","title":"はじめに、(7)第９０号議案、五反田文化センター他４施設空調設備改修工事請負契約","agenda":"はじめに、(7)第９０号議案、五反田文化センター他４施設空調設備改修工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"けれども、一定の期間が来るとこのように自動的というのはおかしいですが、期間が来れば空調設備を更新していくという考え方で進めているのでしょうか。教えてください。","respondent":"長尾施設整備課長","answer":"委員がおっしゃるように、空調設備についてですとおおむね１５年から２０年使用した辺りで、更新時期がやってまいります。故障しているわけではなくても、一定の更新期限が来た辺りで更新することで、利用に支障なく使えるようにということで、予防保全的な措置を行っております。","id":"exchange-001"},{"speaker":"須貝委員","kind":"質問","question":"それぞれ故障云々というような状況、または異常な状況を感じたら交換していくというようなお話を聞いたので、自治体としてはやはりある一定の期間が来れば、それはもう順次更新していくというやり方に全てなっているということでよろしいでしょうか。","respondent":"長尾施設整備課長","answer":"原則としては委員がおっしゃっているように、計画的に順次更新をかけていくという考えです。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"これは１５年から２０年という幅がありますけれども、決まっているのですか。というのは、これは同じくらいの時期に建設した施設なのかと思っているのですけれども、そういう関係で一気に出てきているという認識でいいのか、それとも段階的に違いはあるけれども、今回の機会の全部替えてしまおうということになっているのか、機械的なのか管理的なのか教えてください。","respondent":"長尾施設整備課長","answer":"今回の五反田文化センター他４施設ということで、空調設備の改修をかけますが、この他４施設というものも含めて、複合施設として一体に建築した施設になっておりますので、設備についての更新時期については併せて行うというのが、経済的にも合理性があるというところです。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"交換するタイミングが１５年から２０年の幅があるようなのですけれども、決め手というのはどういう決まりなのですか。","respondent":"長尾施設整備課長","answer":"１５年が来たら必ず替えたいというところはあったとしても、現実的に集中してそういった工事を行うことが難しい場合もありますので、おおむね１５年から２０年程度の範囲を目安として、順次替えていくというところを目安に設定しております。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"そういった場合の考え方として、１５年サイクルの状況で見直しを図っていくということになっているのかどうかということと、そうすると金額が小さくなると思うのです。その場合に、議会のほうに上がるというよりは、もう報告で終わりという部分もあり得るのではないかと思うのですけれども、その辺はどのような考え方で、議会への報告とかは考えられているのでしょうか。","respondent":"長尾施設整備課長","answer":"ほかの施設につきましても、更新時期の考え方については今回と同じように、１５年程度というところが目安になっております。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"要は逆に言うと、本来は１５年もたっていて交換時期なのに、まだ使えるから交換しなくてもいいねというようなものが出てきてしまう可能性もあるのかなと。そこはきちんと計画的に、この施設は今年で１５年たつからもうそろそろですね、というのがある程度施設全体の中での計画がたっているのではないかと思うのですけれども、そういう形で計画的にやっているということなのか、それはいかがでしょうか。","respondent":"長尾施設整備課長","answer":"更新時期が１５年で必ず更新をしているかというと、やはり多少長く使っている施設というのもありますけれども、そういった場合も設備の運転に支障がないかどうかというところは我々も確認しながら、定期的な検査であったり点検。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"別件なのですが、私だけなのかもしれないけれども、今、委員会室で音がしていますよね。これは空調の音なのですか。いや年齢的に私が上だからしようがないのかもしれないけれども、こういうこともそれぞれ交換はしているのだろうけれども、やはりこういう会議の場では少し異様に聞こえるので、そういうのも改善していただけるとありがたいなとそれだけ一言、今気がついたので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"}]},{"id":"topic-02","title":"第８８号議案、荏原平塚総合区民会館ひらつかホール照明・音響設備更新その他電気設備工事請負契約","agenda":"第８８号議案、荏原平塚総合区民会館ひらつかホール照明・音響設備更新その他電気設備工事請負契約","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ひらつかホールの照明と音響設備の更新ということで、先ほど空調のところでも１５年から２０年というというお話だったのですけれども、音響というのもそうした耐用年数というのはどれぐらいなのか分かれば教えていただきたいのと、あとこの照明のところで、４ページの工事概要で、ハロゲンランプを使用しているためということなのですけれども、これは最初からＬＥＤではなかった。","respondent":"長尾施設整備課長","answer":"音響設備の更新時期ですけれども、先ほど申した空調設備とは少し違って、おおむね１０年前後が音響設備の更新時期といいますか、そういうタイミングになっております。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"これらは新しいものに替えるという意味なのでしょうか。それからあと、音響設備で１０年前後ということなのですけれども、故障する可能性が高くというのは、音響設備は結構故障するものなのですか。だからもっと頻繁にとか、それか１０年より前に故障して直さなくてはいけないとか、そういう状況なのか、その辺の実態を教えていただきたいと思います。","respondent":"長尾施設整備課長","answer":"利用者の方が使われると、持ち込んでくる機材などもどんどん新しくなっておりますので、そういった一定技術の進歩に合わせて施設の設備についても更新をかけていかないと、竣工当初は予定していないような故障というか不具合とか。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"今回この入札の辞退者のところで、２番、３番が予定価格超過と書いてあるのです。やはりそれなりの設備をするときには、それなりのお金がかかるのだろうと思うのです。結局安いのにして、これからいろいろな対応がしにくい状況になると本末転倒かなという思いがあるので、その辺を見越した設備が必要なのではないかと思うのですが、今回２番、３番、辞退も含めてどういう状況だったのか教えてほしいです。","respondent":"佐藤経理課長","answer":"予定価格については、仕様に基づいて最新の単価ですとか、そういったところを積算して出しておるわけなのですけれども、事業者のほうで改めて設計の詳細を確認してそれぞれで積算したところ、金額に合わなかったというところが、この２者目、３者目ということだと思います。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問","question":"もちろん分かります。でもそうであるならば、やはりそういう業者の方々や企業のほうで、これから将来にわたってこういう施設が必要だというような状況があれば、やはりそれは大切にしたほうがいいと思うのですけれども、そういうことは加味されていなかったということなのか、それともそれはもう考えなくていいということなのか、まだそこまで行っていませんということなのか、どうなのでしょうか。","respondent":"長尾施設整備課長","answer":"今回の音響設備の更新に関しては、もともとあった音響設備を何か非常に最新のグレードのものに、最新バージョンに更新をかけるというよりは、今の時点での同グレードのものに置き替えるというところの工事仕様で計画をして、その内容で積算をして。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"分かりました。いろいろ使われて不具合もいろいろあると思うのです。というのは、これがまた次に替わるというときは１０年ぐらい後になるわけですね。そうすると１０年後にはもっと音響設備はよくなっています。今から予測はできないにしろ、今まで使っていた方々にとって不具合がある、もう少しこうあったらいいのにというようなご意見などはいただいてはいないのでしょうか。そこの現状を教えてください。","respondent":"大森文化観光戦略課長","answer":"現状でメジャーなものに今回の工事でしていただくというような形になるのですけれども、これが先々どういうもので対応していくといいのかというところまでは、なかなか先読みできないので、物によってはすぐにすたれていってしまう音源。","id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"経理課長にお聞きしたいのですが、今回、これが２件目の設備更新なのですけれども、設備更新の基準というのは、恐らくこの品川区で四、五十年前に決めた基準だと私は思うのです。現在、各こういう設備でも部品でも性能はまず良くなっている。品川区のこういう設備更新に対して、この方たちはやりたくないのでしょうか。そういうふうにやっているわけですから、その辺について少しお聞かせください。","respondent":"長尾施設整備課長、佐藤経理課長","answer":"その基準の考え方については、国であるとか東京都であるとか、ほかの自治体などもおおむね同じような考え方でやっているところです。１つ目は、品川区の工事をやりたくないのかということですけれども、今回３者ですけれども、手を上げていただいているということで、その上で辞退に関しては、先ほども少しご説明いたしましたけれども。","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問・要望","question":"意見だけ言わせていただきます。パーツとかこういうものを設置しなくてはいけないというのは、どこの業者だってみんなそれぞれ業者も勉強しているわけですから。車だってそうではないですか。では車が１５年で駄目ですが、２０年で駄目ですか、そのようなことはないのです。期限もやはり何十年前に作った期限を目安にするのではなくて、やはり性能に応じた新しい基準をぜひ設けていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"}]},{"id":"topic-03","title":"第８９号議案、中原保育園および中原児童センター改築機械設備工事請負契約の変更","agenda":"第８９号議案、中原保育園および中原児童センター改築機械設備工事請負契約の変更","exchanges":[{"speaker":"西本委員","kind":"質問","question":"工期が令和７年７月３０日なのですね。そうすると来月に終わりになるのでしょうね。何回か変更があったのですけれども、今回５.５％増ということで、当初は令和５年だから２年前になるのですね。前は０.７％とかいう形だったのが、今回５％にアップしたという何か理由があるのでしょうか。","respondent":"佐藤経理課長","answer":"インフレスライドについては、ここ何年もですけれども、例年３月になりますと、残りの工事期間について改めて賃金水準ですとか鋼材料とかの水準がかなり急激に上がっているということなので、その差額を改めてお支払いするということに対して。","id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"ということは、今やっているものもいろいろ継続的にやっていると思うのですけれども、これもどんどん、５％以上と議会に報告すると決めていますけれども、もしかしたらもっと上がってくるのか、そういう案件も増えてくるのかと心配しているのですけれども、今はどのような感じになっているのですか。","respondent":"佐藤経理課長","answer":"改めて新規で発注する際は、そのときの最新の単価と人件費の水準で発注いたしますけれども、どうしても継続的に上がっているというところですので、工期が長い複数年度にまたがるときについては、工事の質の担保という点からも。","id":"exchange-016"},{"speaker":"西本委員","kind":"質問","question":"ということは、この増額分については、この点に関して言うと一般財源になってくるのですね。そうした場合、今は分からないから計算できないと思うのですけれども、今後そういうこれからの物価高に対しての金額をこれくらい用意しておかなくてはいけないとか、これぐらい負担が増えてくるだろうという、何かそういう予測とかはしておられるのでしょうか。大雑把でよいのですが。","respondent":"佐藤経理課長","answer":"今後の予測は正直分からないというところではありますけれども、ただ傾向としましては、例えば人件費に係る設計労務単価というところは、国のほうで全国調査をやった上で示して、それに基づいて工事を発注しておりますけれども、既に１３年連続で上昇しているというところで。","id":"exchange-017"},{"speaker":"須貝委員","kind":"質問","question":"その人の会社では、この間ある建物をやったら実際もう２００億円赤字だけれども、契約をその場で３年前にしてしまったから、そのまま２００億円の赤字で請け負っていかざるを得ないのだということをおっしゃっていましたけれども、我々品川区内でもそれぞれいろいろ合理化、それから経費削減、いろいろしているわけですから、ぜひ民間の業者にも協力してもらうように。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"山本委員","kind":"質問・要望","question":"私からも質問します。今回の契約に関して、このインフレスライド条項の適用の仕方について確認をさせていただきたいです。これは、事業者からの要請に応じて、経理課のほうでそれが正しいと思って承認する形なのかということです。違うとすれば、区の経理課側で算定して、こうではないでしょうかと区側から申し出るのかというところです。仕組みのところを確認させてください。","respondent":"佐藤経理課長","answer":"インフレスライドにつきましては、ここ数年ずっとですけれども、毎年国のほうで主に人件費の部分についてこのぐらい上がったというところを踏まえて、３月に継続する工事について、残りの部分について人件費、鋼材費等、上がった部分について契約変更するというところで。","id":"exchange-019"},{"speaker":"山本委員","kind":"確認","question":"そうすると、あとは事業者から申請をされるというのはある程度区としても想定ができるのかなと思いますので、既存の契約については、その賃金および物価上昇に対する契約金額の上昇可能性というのは、ある程度見通せるところもあるのかなということで、これは感応度と言いますか、そういった先々への財政のインパクトというのは。","respondent":"佐藤経理課長","answer":"実際区の仕組みとしましては、当然年度ごとの予算を組んでおりますので、そういった事業者からの申出で一定増額分が決まるわけなのですけれども、それで年度内の予算で収まらない場合は補正をお願いしたりですとか、あるいは流用等で対応したりですとか。","id":"exchange-020"},{"speaker":"山本委員","kind":"質問・要望","question":"現状について理解をいたしました。今度意見になりますけれども、それぞれの工事によるというところもおっしゃるとおりのところはあるかなと思いますけれども、共通するようなところもあるかと思いますので、全体として先々物価上昇に応じてどれぐらいの上昇が見込めるかというのも、併せて検討していくのが良いのかなというところで、こちらのほうは要望といいますか、意見として言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"}]},{"id":"topic-04","title":"第９６号議案、児童用ロッカー他の買入れ","agenda":"第９６号議案、児童用ロッカー他の買入れ","exchanges":[{"speaker":"西本委員","kind":"質問","question":"城南第二小学校と第四日野小学校が新しい校舎になるということなのですが、新しく備品を購入するということは、前に使っていたものがありますよね。あれはどう処分されたのでしょうか。当然新しい校舎なので、新しいものをそろえたいという思いはもちろんあるのですけれども、ただ、前に使っていたものを有効活用しているのかどうかというのが気になったので、教えてください。","respondent":"石井学務課長","answer":"ですので、引き続き同じものを使っているものもあります。","id":"exchange-022"},{"speaker":"西本委員","kind":"質問","question":"そういう子どもたちが不公平にならないような配慮はされているのですよねというのと、ロッカーも新しいほうがきれいだしいいのだろうなというのがある。これはやはりそうなのかなと思うのですけれども、でもそうすると、結局前に使っていたけれども要らなくなるものが当然出てくると思うのですけれども、その処分とかいうのは、どのような処分をされているのでしょうか。","respondent":"石井学務課長","answer":"そういう意味では、引き続き同じものを使うというのもひとつあるのかなと。実際には使えなくなったものに関しては、例えば調査をかけた上でまとめて処分をしたりですとか、そういったこともしています。","id":"exchange-023"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろ配慮されていると思うので、せっかく新しい校舎なので子どもたちもわくわくすると思うのです。議題とはちょっと違うようですけれども、そこら辺はどういうところに使っていただいている実績があるとかいうのも含めて教えていただきたいのですけれども。","respondent":"石井学務課長","answer":"児童・生徒のよりよい学習環境を整えるというものは、教育委員会でしっかりやってまいりますということがまず１点と、あと、例えばここで使ったものがどこで使われているかというところまでは追い切れていないのですけれども、例えばまず学校間で。","id":"exchange-024"},{"speaker":"西本委員","kind":"質問・要望","question":"一つ要望ですけれども、児童センターはすごく老朽化が激しいものが多いのです。なので、やっているとは思いますが、学校間だけではなくて、児童センターとかそういうところも含めていただいて有効活用して、本当に古いものは処分してもいいのではないかというものもあるので、ぜひお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"}]},{"id":"topic-05","title":"第７２号議案、品川区特別区税条例の一部を改正する条例","agenda":"第７２号議案、品川区特別区税条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"（１）の特定親族特別控除創設というところでは、大学生辺りの年代の方々が、いわば１０３万円の壁というものへの対応をされた控除なのだろうと思うのですが、この(１)とか、あと(２)の給与所得控除の最低保障額のところ、その後の方々はあまり関係ないのですけれども、その最低保障額のところが引き上がったということだと思うのですけれども、こういう控除が充実してくるといいますか。","respondent":"宮澤税務課長","answer":"先ほどご説明させていただきました令和７年度の税制改正、まさに控除が増えるということは、納税義務者の税負担が減る。","id":"exchange-026"},{"speaker":"石田（ち）委員","kind":"質問","question":"減収となることがどこまでかはちょっと分からないですけれども、それを問題視するほどではないのか、その減収となった分をどうしようとしているのかというところまでお考えがあるのか、伺えたらと思います。それとあと、均等割り軽減ですけれども、均等割りが課税がされている方というのが、今区内ではどのくらいいらっしゃるのか、分かれば伺いたいと思います。","respondent":"宮澤税務課長","answer":"減収の見込みというところなのですけれども、正直対象となる方がどのぐらいになるかというのは正確にはできないのですが、令和７年度の課税方式で多めに試算すると、例えば特定親族特別控除を創設されることによって。","id":"exchange-027"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。均等割りのところも５人前後ということだったので、一律１０００円になってしまうというところが、要は不利益になっていくのかなと思ったのですけれども、そこは今様々な所得控除、さらに１０３万円の壁というところでの控除の対象が広がるというところで相殺されるものなのか、そこは伺いたいと思います。それと、(５)の公示送達制度、これが要は閲覧することができるようにしていると。","respondent":"宮澤税務課長","answer":"均等割課税の部分につきましてです。先ほどの説明で１００万円を越えてくる場合、住民税が課税されてきて、均等割と所得割というのが課税されます。","id":"exchange-028"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、公示送達のほうなのですけれども、要は督促、その後の差押えというのをしていくためにと言いますか、そういうことに進めていくためにはこういう掲示、住民票の住所に届かない場合にこういう措置をする、これをしたことによって、督促や差押えというところに進めるというものなのですけれども、その差押えするということは、要は銀行口座とかそういうところが分かっているなら。","respondent":"宮澤税務課長","answer":"公示送達の部分です。公示送達する場合なのですけれども、まずは郵便で通知書を送りまして、それが郵便局から宛て所なしということで戻ってきます。その段階で職員のほうで調査をした上で、それでも居所が分からない場合は公示送達をするという段取りで行っております。","id":"exchange-029"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで、それをすることで差押えまで進められるわけですよね。そうすると、では何を差し押さえることになるのか。本人と連絡が取れないのに、何を差し押さえることになるのか伺いたいと思います。","respondent":"宮澤税務課長","answer":"差押えにあたりましては、金融機関での預貯金等がないかとか、生命保険等に加入してないかとか、そういったところを調査して、差し押さえられるものがあるかどうかというのを調査しております。","id":"exchange-030"},{"speaker":"石田（ち）委員","kind":"質問","question":"いや、私は分かるのですけれども、そうすると、そこまで調べて差し押さえられるということは、個人と連絡が取れるのではないですかということを言いたいのです。そこを何か知る前に、こちらに個人情報が出てしまう、提示されてしまう、しかも今回インターネットでできてしまうというところでは、すごく懸念を感じているのですけれども、そこはどう考えますか。","respondent":"宮澤税務課長","answer":"公示送達される方、いわゆる連絡先である電話番号等も不明であったり、郵便を送っても戻ってくるというところで、こちらからのアプローチができない方になりますので、ただできないからといって、例えば滞納がある場合そのままにしておくわけではなくて。","id":"exchange-031"},{"speaker":"西本委員","kind":"質問","question":"これはどういうレベルで高くなるのか教えてほしいのと、それから今の公示送達の件なのですけれども、これは連絡がつかないから、掲示板に一定の期間を設けて掲示するという形になると思うのですけれども、インターネットでやったとしても、その人が見るというのはあまり考えられなくて、となると何かインターネットの意味があるのかというのがあるのです。これは品川区において新しく作るのですか。","respondent":"宮澤税務課長","answer":"それと加えて、掲示板で掲示、もしくは例えば税務課の窓口で電光掲示板のような形で表示するというのが、この２つ目のパソコン画面等での表示という部分になっておりますが、デジタルデバイドの観点から見れば、掲示板での掲示というところになろうかです。","id":"exchange-032"},{"speaker":"西本委員","kind":"質問","question":"私はたばこを吸わないのでよく分からないのですけれども、ある程度増税ですよね。それと、もう一度（５）の公示送達のことなのですけれども、これは事務所にまたはと書いてあるのですけれども、だからパソコンを設置してそこで見られるようにするということは品川区はやらないで、今やっている掲示板だけになってくるのか、ここで言っているのはどちらかですか。どちらを採用するのかと。","respondent":"宮澤税務課長","answer":"今回のたばこ税の課税基準の見直しに伴って、販売価格のほうも見直されると予想されるというところですが、銘柄等によってもその幅はありましょうし、そちらは販売のメーカーの対応です。公示送達の部分ですけれども、インターネットによる公表というところはやっていきます。","id":"exchange-033"},{"speaker":"石田（ち）委員","kind":"質問","question":"公示送達は今もそうなのですよ。それで支払われるということは今まであるのですかというのをお聞きしたいと思います。","respondent":"宮澤税務課長","answer":"その後、公示送達した方が納付したとしても、その因果関係については不明ということです。","id":"exchange-034"},{"speaker":"松本委員","kind":"質問","question":"例えば今回１１０万円のずれを知らない人というのは結構世の中にいるのではないかなと思っていて、そうすると、そこの把握をどうするのかなというところが、これまでも１００万円と１０３万円のところに３万円のずれがあったと思うのですけれども、その幅が拡大することで、ここの把握というのをどうされるのかというところをお伺いできればと思います。","respondent":"宮澤税務課長","answer":"住民税は賦課課税方式になっておりまして、区のほうで課税資料の収集をした上で課税するというところになります。特に給与収入をお持ちの方であれば、給与支払報告書というのがお勤め先から区に提出されますので、そこの金額等を判断して課税するという形になります。","id":"exchange-035"},{"speaker":"松本委員","kind":"確認","question":"基本的にはもう区のほうで、事業者ではなくて労働者のほうで特に申告しなくても大丈夫ということで、あとは事業者側がきちんと申告していれば、基本的には把握できるという理解で良いかだけ、最後確認して終わります。","respondent":"宮澤税務課長","answer":"委員ご指摘のとおりです。","id":"exchange-036"},{"speaker":"石田（ち）委員","kind":"意見","question":"賛成なのですが、先ほども１０３万円の壁のところでは、大学生等の学ぶ環境の整備のほうも進めていくべきだと思いますし、公示送達のほうはインターネットで掲示していく意味、これまでも掲示板に掲示すればその先を進めていけたのに、それをさらにインターネットで個人情報を出していく方向に進んでいくというところには、大変懸念を感じておりますので、そこを注視しながら、賛成します。賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"大体そうなってくるのではないかと思うのですけれども、そもそも有給休暇が取れている状況にあるのか実態を、有給休暇の取得率が分かれば教えていただきたいと思います。","respondent":"宮尾人事課長","answer":"本２条例の対象とする子の年齢ですが、第７３号議案では、子育て部分休暇の取得形態の今回見直しをご提案していますが、子育て部分休暇については、小学校のお子さんを持つ職員とイメージをいただければと思います。","id":"exchange-038"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"休みの形態が様々、選択肢が増えるというのか、そういうところでは良いのかなと思うのですけれども、そもそもの有給休暇も、忙しすぎたり人材不足だったりで取りづらいという声も聞いたりしますので、休暇というものが取りやすい環境になっていけばいいと考えていますので、引き続きそこは私たちも声を聞きながら求めていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"西本委員","kind":"質問","question":"分からないところがあるのですけれども、これは無給ということですね。だから、有給で１日２時間早く帰るとかって、そういう対応はできるのですか。有給休暇は１日とか半日とかいうくくりだと思うのですけれども、そういう理由があれば、例えば改正後の1)、2)というものも適用可能なのですか。それは可能ではないですか。","respondent":"宮尾人事課長","answer":"今回の改正となる子育て部分休暇、それから部分休業、いずれも現在無給となった上での取得となるのですが、それは改正後においても、無給という部分について変更はございません。取得する、その代わりその分は無給となるという前提での改正です。","id":"exchange-040"},{"speaker":"西本委員","kind":"質問","question":"でも、こういう理由で、この1)と2)のほうを有給の中で使える制度なのですかということです。言っていること分かりますか。そういう制度になっているか、例えば有給で１時間とか、この1)、2)というのが、有給の中でも時間的な融通性があるのですかということです。","respondent":"宮尾人事課長","answer":"例えば例を挙げると、子どもの看護のための休暇、我々子看休暇などと呼んでいますが、これは有給で、もちろん取得の上限、１年間に取れる日数というのは上限がありますが、有給でお子さんを理由として取れる休暇制度というものもあります。","id":"exchange-041"},{"speaker":"西本委員","kind":"意見","question":"というのは、だから無給になるので、初めは有給を使ってそういうやり方をして、なくなってしまった場合には、無給になるけれども、こういう取り方でもいいですよということですね。だから、働きやすくなったという理解で良いのですね。","respondent":"宮尾人事課長","answer":"そうですね。これはやはりそもそも今回の趣旨といたしましては、職員が仕事と子育てをよりしっかり両立できるためのそういった環境を整えていこうという趣旨ですので、手前みそにはなりますが、大きく前進をしていると考えています。","id":"exchange-042"},{"speaker":"西本委員","kind":"質問・要望","question":"というのは、子どもが病気をしたりとか、介護も一緒なのですけれども、そのときには雇用主が保証してくれるというようにしてほしいです。だからこういう制度が民間のほうにも波及できるように、ぜひ宣伝ではないですが、役所の中でのこういうふうなものをもう少し宣伝してほしいと、広げてほしいと思うのですけれども、いかがでしょうか。","respondent":"宮尾人事課長","answer":"公務員の中でも、地方公務員と国家公務員との中で大きなそごが出ないようなという趣旨も入っておりますので、私たちもそういった均衡というものを常に注視をしていきながら、いろいろ制度等を整備していけたらと考えています。","id":"exchange-043"},{"speaker":"山本委員","kind":"質問・要望","question":"何点かお伺いします。それから、それぞれの議案の（２）のほうで、意向確認というものをする背景といいますか、実際取られたときに、周りの職場の方ができるだけ影響を受けないというか、スムーズにやっていくという趣旨なのかなと思っていますが、その辺りはどうなのかというところだけ教えてください。以上３点、お願いします。","respondent":"宮尾人事課長","answer":"３点ご質問をいただきました。","id":"exchange-044"},{"speaker":"山本委員","kind":"確認","question":"お答えください。続けて言いますが、４月からの適用で１２人という人数というのはどう受け止めていらっしゃるかということと、１２人の方々でそれぞれ５０回ぐらいというと、その方々は結構取られているということなのかなということで、その利用の仕方で、そういう理解で合っているのか。そういう理解でいいのかというのをお願いします。その意向確認のところも分かりました。では２件、お答えお願いします。","respondent":"宮尾人事課長","answer":"それから子育て部分休暇、４月以降の取得状況ですけれども、人数としてはまだこれからもう少しさらなる周知が必要かなと考えています。１人当たりの取得回数については、ほぼ想定していた範囲内での回数かと捉えております。","id":"exchange-045"},{"speaker":"山本委員","kind":"質問・要望","question":"ぜひ今回の改定でより多くの方々が取りやすくなるように望むのと、あと周りの皆様もうまく勤務ができるような体制づくりを進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"須貝委員","kind":"質問・要望","question":"１点意見だけなのですが、今回、職員のこういう条例改正ですか。けれども、なかなか人手不足で取れない、取得できないということもあるので、ぜひそういう方たちにも取得できるような何か知恵をお貸ししていただければありがたいなと、これは特に国に要望したいと思います。終わりです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"澤田委員","kind":"質問","question":"周りの人も使う人もお互いの気持ちを思いやるではないですけれども、そういうことがすごく大切かなと思って、そこら辺についても進めていくと条例には書いてあったと思うのですが、具体的にはどのようなことをされていくのかというのを教えていただけますか。","respondent":"宮尾人事課長","answer":"この２点が大きなところではあるのですが、今まさに委員がおっしゃったように、制度があってもそれが絵に描いたもちになっては、これはもうあってはならないことだと思いますので、それを職員がどうやってちゃんとしっかり取れるか。","id":"exchange-048"},{"speaker":"澤田委員","kind":"質問・要望","question":"それもすごく大事だと思うのですけれども、今例えば「妊婦様」や「子持ち様」などという言葉があったと思うのですけれども、やはり子どもがいるからと、そういうふうに私たちに全部負荷がかかってくるよねみたいな、そちらのケアというか、取る側の人も当たり前の環境をつくるというのはすごく大事で、それももちろん進めていただきたいと思うのですが、それと同時に周りの負荷をかぶるではないですけれども。","respondent":"宮尾人事課長","answer":"そのためには、まずはしっかりと休みに入る職員が休んだとしても組織としての力が落ちないような人的な補強をいかにしできるかというところ、なかなか全ての部署において１００点の人的補強ができているかと言われると。","id":"exchange-049"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"今回のこの改正にあたっては、現場とか働く方々からのいろいろな要望があって、1)だけではなくて2)というのも付け加えたということで伺っているのですけれども、具体的にどういう場面、どういうニーズでこういう１時間単位で年間７７時間という選択肢ができたのかというところと、あと年度内で７７時間３０分の範囲内としたことの妥当性ですね。ここだけ確認でお願いします。","respondent":"宮尾人事課長","answer":"でも、実際やはり育児に関わる職員からすると、必ずしもきれいに毎日２時間休めばいいという状況ではなくて、場合によっては半日ちょっと休みたい、場合によっては１日休みたい、こういうものを状況によって組み合わせることができないのか。","id":"exchange-050"},{"speaker":"西本委員","kind":"提案","question":"賛成ですが、少しだけ意見。これは第７４号議案にも関わるのですけれども、先ほども何人かの委員も言っていましたが、やはり民間に対しての波及性を少し意識してお願いしたいと思っています。周知して利用しやすい環境づくりというのは当然なのですけれども、それを含めてやはり民間事業所の方々にこれは当たり前なのだということは、指導と言うか提案していただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"},{"speaker":"山本委員","kind":"質問・要望","question":"質問したかったのは、実際どれぐらいの利用を今後見込んでいて、そのためには各職場でやはりその時間の間は一時的に減ると思いますので、それをどれぐらい見込み、どう穴埋めしていくかというのをお聞きしたかったのですが、これはまた別の機会にお聞きしますし、ぜひそういった計画性をもって、取りやすい環境、そして周りの人も負担のない環境づくりを目指していただきたいと思います。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"西本委員","kind":"質問","question":"第９１号議案のほうなのですが、資料に落札と、それから未満というのがあって、辞退は理由が書いてあります。それと、所在地のところが、これはいろいろなところがあると思っています。これは東京都がやったものなのですか。品川区がその契約というか申込というか、今までと違う契約関係が入っているのですけれども、その点を教えてください。","respondent":"佐藤経理課長","answer":"委員ご指摘の所在地がいろいろなところというのは、今回橋の上部工の工事ということで、非常に特殊と言いますか、あまりない工事ですので、ほかの案件のように区内の事業者に限らず、そのノウハウを持っている事業者を広く入札の要件といたしましたので。","id":"exchange-053"},{"speaker":"西本委員","kind":"質問","question":"それは出していないのですか。そうであっても、これは差があるのは約１億円ですからね。落札したところと、それから１１番のところの差は結構な差があって、これほど差があるというのは何ですかというところなのです。それでやめているわけですね。こういうことはあり得るのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"西本委員","kind":"質問","question":"今までになかったので、どういうことかなと思って、その現状というか背景というか分かれば教えてください。","respondent":"佐藤経理課長","answer":"最低制限価格については冒頭申し上げたとおりでして、予定価格を出しますが、あまりにも低い金額で、区役所の仕事を取ること自体が目的のような形で非常に低い金額で応札された場合、その工事に対しての質の担保というところから非常に問題があるというところで。","id":"exchange-055"},{"speaker":"西本委員","kind":"質問","question":"やはりその最低価格というのは提示しないまでも、そういうことがあるというのは分かるはずではないですか。なおかつ、そのパーセンテージか何かよく分かりませんけれども、それはある程度の国の指針とかが一応あって、それを事業者の方々は知らないということですか。ということは知らないで出してきているわけですね。それはいかがですか。","respondent":"佐藤経理課長","answer":"最低制限価格制度についてですけれども、予定価格の７５％から９２％の間で、一定の算式に基づいてその金額を決める。だから金額自体は公表してないという制度になります。","id":"exchange-056"},{"speaker":"西本委員","kind":"質問","question":"もう一点だけ。品川区内の事業者でなくてもできるということなのだと思っているのです。技術も品川区内よりも、区外を多く取ったほうが、間口を広げたほうが、技術的にも進んでいるところとか、いろいろなノウハウを持っているところとかがあるのではないかと思うのですが、その辺はいかがなのですか。","respondent":"佐藤経理課長","answer":"逆に言うと、品川区の事業者ではなかなか難しいノウハウが必要だというものについてはその条件をなくして、広く事業者を募集するという形になっております。","id":"exchange-057"},{"speaker":"須貝委員","kind":"質問","question":"経理課長にまた別の方向から質問します。この落札の状況を見て、未満の事業者がこれだけいるわけですよね。ということは、妥当な入札価格というのはこの中の範囲に入っていなくてはおかしいのではないですか。それを、いや１者だけ下限を上回っているからここを決めましたというのは、平等性から言っても客観的に見ても、それで落札者を決めたというのは矛盾していませんか。教えてください。","respondent":"佐藤経理課長","answer":"数字を決めての入札になりますので、各事業者が応札した中で、その金額を下回るということは出てくると思います。結果的にはこういう形になりましたけれども、制度運用上はそういうこともあり得るということかと思います。","id":"exchange-058"},{"speaker":"須貝委員","kind":"質問","question":"これだけの事業者がこの金額で収まっているということは、こちらのほうがどう見たってもう過半数以上、もう大半ですよね。だから、大半の方がここまでの金額を出して皆さん応札しようとしているならば、こちら側で今回は特例で決めましたとか、やはりそういうことがあっていいのではないですか。これはどう見たって、このようなこと、この入札決定書を見せたらおかしいと思いませんか。","respondent":"佐藤経理課長","answer":"入札に関しては、開札するまでは、もちろん入札金額について我々も含めて分からないということが基本的なルールですので、今回結果的にはこのような状況になりましたけれども、入札の手続き自体には特段瑕疵はないと考えています。","id":"exchange-059"},{"speaker":"須貝委員","kind":"質問","question":"我々は皆さんがきちんと落札者を決めているということで、こうやってイエスということでやっていますけれども、いろいろ状況によってこのようにきちんと出たならば、やはりそれはある程度応用というか、変えてもいいのではないですか、それのほうが区民に対する説得、区税を使う、区民の皆さんの税金を使って我々はやっているわけですから、できるだけ区民が納得するような、同意を得られるような入札価格。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"松本委員","kind":"質問","question":"それで、予定価格掛ける一定の割合を出して算定しているということかと思うのですけれども、私もこの分野や詳しくはないので間違っていたらあれですけれども、他の自治体を見ると、入札の平均入札額も使いながらやるという自治体も見られるように思われるのですけれども、当区のほうは、こうした有効な入札の平均入札額をここに用いるというようなやり方はされていないのか。","respondent":"佐藤経理課長","answer":"先ほど申し上げたとおりでして、国の算定モデルに準拠して区のほうでは運用しているということでして、中央公契連モデルと言いますけれども、工事費ですとか仮設費、現場管理費等から、一定の割合を掛け算して最低制限価格を出すという形の算式なのですけれども。","id":"exchange-061"},{"speaker":"松本委員","kind":"意見","question":"そうすると、先ほど申し上げた平均入札額を使うような方式は使われていないということかと思います。他の自治体ではこうした制度を導入して、税の見直しというところもあると思いますので、今日いろいろな委員からの意見がありましたので、そちらのほうを研究していただいて、制度自体今の状態でいいのかということは検討していただければと思います。以上です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-062"},{"speaker":"石田（ち）委員","kind":"質問","question":"第９２号議案の下部工事のほうの変更で、工期に変更はないけれども中身が変更で、金額も変更ということで、それで上部の工事の請負契約も入ってきているというところで、下部工事は、ではこのまま今回の変更程度で進んで、上部工事に予定どおり入れるということでよいのか。それで、上部工事はどれぐらいから始まる見込みでいるのか、伺いたいと思います。","respondent":"森道路課長","answer":"工事の内容ですので、私のほうからお答えします。下部工につきましては、予定どおり順調に工事が進んでおりまして、今年度１０月末までが工期となっておりますけれども、それには十分間に合う形で進んでおります。","id":"exchange-063"},{"speaker":"塚本副委員長","kind":"意見","question":"その上部と下部で、橋げたのところと橋そのものというのが別々の工事になっているのですけれども、橋の工事というのは普通こういうふうなのかどうか。素人考えですけれども、一つの会社に丸ごと全部やったほうが、経済的には規模のメリットみたいなのが生まれるのではないかと思ったりもするのですけれども、そこの辺、下部と上部と分かれていることについての理由をお聞かせください。","respondent":"森道路課長","answer":"業者ともいろいろな意見交換をする中で、上部工であったり、今年度末に予定しております橋詰工と言いまして、橋の根元の部分ですね。","id":"exchange-064"},{"speaker":"石田（ち）委員","kind":"意見","question":"共産党はこの下部工事に反対をしてきています。ここはまちづくりビジョンに示されている共同化、建替え等、有効な土地利用の促進が再開発としてうかがえる中身があるので、これを契機にこの周辺の再開発になっていくことが考えられるということで反対をしているところですので、反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-065"},{"speaker":"須貝委員","kind":"質問・要望","question":"一応賛成します。ですが、入札方法については、やはり経理課のほうで様々な状況、やはり一つのやり方ではないと思うので、区民に疑問・疑念を抱かれないような入札方法を私はつくり上げていただきたいと思います。終わりにします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"}]},{"id":"topic-06","title":"第９３号議案、子どもの森公園改修工事請負契約","agenda":"第９３号議案、子どもの森公園改修工事請負契約","exchanges":[{"speaker":"山本委員","kind":"質問・要望","question":"１点目なのですけれども、この資料概要書を拝見しますと、バスケットボールコートの場所なのですけれども、前回、過去の委員会等でご説明をいただいていたところの設置場所というのか、この資料で言うと野球場から見て右側に当初予定として示されていたものが、今回の説明資料によると左側の部分に移っておりまして、ここら辺の変更の経緯などがあれば教えていただきたいと思います。","respondent":"大友公園課長","answer":"２点目、工期のご質問です。公園全体の工期といたしましては令和８年度末までとなりますけれども、工事の仕様書において、野球場部分を先行で整備、工事を実施いたしまして、来年、令和８年７月２０日までに完了、供用を開始することとしております。","id":"exchange-067"},{"speaker":"山本委員","kind":"質問・要望","question":"もともとこの少年野球場を使っている方々もいらっしゃいますので、そういった方々が引き続きできるだけ工事で影響を受けないよう工夫をしながら工事を進めていただけるということで、ぜひそのように進めていただきたいのと、できる限り部分で使えるようになっていったら早めにオープンをしていただいて、早く皆さんに使っていただけるように工夫をいただきたいと思います。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"西本委員","kind":"質問","question":"所管を外れてしまうかもしれませんが、平面図のところが分かりにくかったので教えてほしいのですけれども、この複合遊具と、それから上の平面図で言うと怪獣が２体ぐらいいると思うのですけれども、これは別のものという認識でよろしいですか。","respondent":"大友公園課長","answer":"平面図のところの左側にイメージとして、左上のところ、怪獣モニュメント等々載せております。別のものとなっています。複合遊具と、あと怪獣のモニュメントです。","id":"exchange-069"},{"speaker":"西本委員","kind":"質問","question":"なので、この怪獣たちがどうなるかのがすごく心配で、今の怪獣たちは老朽化が激しくなっているのですけれども、それが新しくなったりするのかなというのがちょっと心配なのですけれども、それと新たにここの遊具もあるということ、これはそれにちなんだ似たような雰囲気があるような遊具にしていただいているのかと思うのですけれども、その辺はいかがでしょうか。","respondent":"大友公園課長","answer":"それ以外にも、品川学園の生徒を対象としたワークショップでいただいたアイデアを生かした、恐竜をモチーフとした複合遊具等々を設置してまいるというところで考えております。","id":"exchange-070"},{"speaker":"西本委員","kind":"質問","question":"ここは非常に今の雰囲気をそのまま活かしてほしいというご希望がすごく多いので、安心しました。ただ、ここの場所的には交通の便とかいろいろあるので、その辺は今はそれほど事故とか起きるような状況ではないのですけれども、この周辺の安全確保というのは何かサインプラス安全に考慮した何かそういう取組はないのでしょうか。","respondent":"大友公園課長","answer":"見通しというところで、一定恐竜公園はジャングル的な雰囲気もあるものは残しつつも、見通しの良い剪定等々を行いまして、子どもが陰にならない、危なくないというような観点の視点で整備してまいりたいと考えています。","id":"exchange-071"},{"speaker":"石田（ち）委員","kind":"質問","question":"今の質問に関連してですけれども、私もこの怪獣公園は小さい頃からすごく遊んでいた公園でして、本当に怪獣に名前をつけて遊んだりしていたのですけれども、その頃からある怪獣ということになってくると、やはり８体のうち５体はなくなっていくのかという少し寂しい気持ちもしますけれども、３点残るということで、それで子どもたちのアイデアを取り入れた複合遊具の配置というところで。","respondent":"大友公園課長","answer":"こちらに整備内容には書いていないですが先ほどご説明させていただいた中に、新たに６体を整備するという恐竜のオブジェについても、人気のある恐竜を整備をしていくというところです。","id":"exchange-072"}]},{"id":"topic-07","title":"第９４号議案、第二戸越幹線整備工事（北品川特殊人孔等整備）請負契約の変更","agenda":"第９４号議案、第二戸越幹線整備工事（北品川特殊人孔等整備）請負契約の変更","exchanges":[{"speaker":"西本委員","kind":"質問","question":"１９ページの４の変更概要の(７)その他のところ、週休２日制確保モデル工事というのがあります。それから、熱中症対策に資する現場管理費というのが入っているのですけれども、これはどのようなものでしょうか。","respondent":"関根河川下水道課長","answer":"１点目、週休２日制確保モデル工事ですけれども、本工事は東京都下水道局からの受託工事となっています。その中で、東京都下水道局において、週休２日制確保工事実施要領というのがございまして、それに基づくモデル工事の今回対象の案件となっているものです。","id":"exchange-073"},{"speaker":"西本委員","kind":"質問","question":"そうすると、これがいろいろな制度上そういう形で補正されたということは分かりました。それに対する補填額というのは、これは品川区が全部出すのか、１０分の１０で都から補填される理解でよろしいのでしょうか。","respondent":"関根河川下水道課長","answer":"本工事は東京都からの受託工事になりますので、こういった補正による増額分も含めて、全ての工事費は東京都から歳入という形で区に入ってくる形となっております。したがって、区の持出しといいますか区の負担はないという形になってあります。","id":"exchange-074"},{"speaker":"石田（ち）委員","kind":"質問","question":"この施工方法の変更に伴って契約金額を変更するということだと思うのですけれども、施工方法は何で変更しなくてはいけなくなったのか伺いたいと思います。","respondent":"関根河川下水道課長","answer":"その後、協議等を踏まえて最終的な形が決まったことから、それに伴う変更等を行ったものです。それ以外にも、いわゆる発注時点では当時の現場状況に応じて想定をしていた部分もありますので、そういったものが確定したことによる変更という形になっております。","id":"exchange-075"}]},{"id":"topic-08","title":"第７５号議案、品川区附属機関の構成員の報酬および費用弁償に関する条例の一部を改正する条例","agenda":"第７５号議案、品川区附属機関の構成員の報酬および費用弁償に関する条例の一部を改正する条例","exchanges":[{"speaker":"西本委員","kind":"質問","question":"給付型大学奨学金運営委員会なのですが、これは人数とか、それから開催日数とか、これに関わる金額というのはあると思うのです。どのぐらいを考えているのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"西本委員","kind":"意見","question":"報酬日額はどうなっているか。中身は聞いていないです。金額だけです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-077"},{"speaker":"西本委員","kind":"意見","question":"もう少し多いのかと思ったのです。なので、これは集中的にやったら、４人でやって年２回の報酬がこれでいいのだろうか。これはもっとかかるのではないか。選定なので、どこまでやるかにもよると思うのですけれども、感覚的にはもう少しレベルから言うと月に何回かとかいうレベルではないかと思ったのですけれども、そうではないのですね。金額が安過ぎるのではないかと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-078"},{"speaker":"山本委員","kind":"質問","question":"まさに今おっしゃっていただいたその報酬日額が、この品川区給付型大学奨学金運営委員会は委員が１万４,０００円になっていまして、一方で災害弔慰金等支給審査委員会は、会長が２万３,０００円、委員が２万円となっていて、新旧対照表にもほかの附属機関等の情報とかもあるみたいなので、その辺りをどのように設定されたとか、どのように妥当だと考えていらっしゃるかというのを教えてください。","respondent":"藤村総務課長","answer":"会長ですとか副会長のほうの報酬が高いというところに関しましては、会長に関しては会が始まる前に少し早く来ていただいて、ご説明ですとかをやっていただいたりですとか、運営というところがありますので、差額を設けているような考え方でやっております。","id":"exchange-079"},{"speaker":"山本委員","kind":"質問","question":"１点だけ追加で、そうすると、この奨学金運営委員会には会長職がないというのは、区の職員の方が務められるからということでないということでしょうか。","respondent":"藤村総務課長","answer":"会長のほうは区の職員というところなので、選定はございません。","id":"exchange-080"},{"speaker":"西本委員","kind":"質問","question":"そうすると、品川区児童福祉審議会の委員が２万円なのです。それで、品川区災害弔慰金等支給審査委員が２万円なのです。けれども、ほかの委員は１万４,０００円なのです。これは専門性の違いということで、こういう金額に差があるという理解でよろしいですか。","respondent":"藤村総務課長","answer":"児童福祉審議会の委員にどういった方がおられるかというところは手元に資料がないのですけれども、一般的にはそういった先ほど申し上げたような専門性の高い委員がいらっしゃる場合が２万円ですとか少し高額になっていて。","id":"exchange-081"}]},{"id":"topic-09","title":"令和７年請願第１０号、国に対し適格請求書等保存方式（インボイス制度）の廃止を求める意見書の提出","agenda":"令和７年請願第１０号、国に対し適格請求書等保存方式（インボイス制度）の廃止を求める意見書の提出","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"共産党は、インボイスを廃止しろと一貫して求めてきました。そこは埼玉県のような形には、地方議会というところでは同じなのにそうならないのかというのを、自民党さんにお聞きしたいのですけれども、どうでしょうか。そういうやはり各地と言いますか、これだけの３６７自治体で制度の中止、延期、見直しを求める意見書が上がっているというところでは、賛成多数というところだと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"石田（ち）委員","kind":"質問","question":"様々同じ政党でも地域で違うというところもあるのだろうと思いますけれども、この１万人アンケートを見ても全国の声が紹介され、全国の中小企業、中小業者、個人業事業主、フリーランスが苦しいと、このままでは廃業すると、死も考えるという声を私も伺ってきました。消費税の負担感も合わせると９０.８％ですね。そして、価格に転嫁できるか。ですので、ぜひ皆さんのご意見をお聞きできたらと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"西本委員","kind":"質問・要望","question":"ただ、それはそれとしても、品川区がどう判断するかということになるかとは思うのですけれども、私としては、このインボイス制度が始まったことによって、区内業者がどうなっているのですかということ。コロナの影響はどうなのだと言っても、結局調べようとしないし、なので私はそちらのほうが品川区議会としては改善を求めていかなくてはいけないことであって、それが先だと私の意見としては思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-084"},{"speaker":"山本委員","kind":"質問・要望","question":"会派としての見解、理由を述べます。一方で、請願に込められた事業者の皆様の切実な声、特に免税事業者やフリーランス、文化・芸術関係者の皆様が感じている不安や懸念については、私自身、これまでも多く伺ってまいりました。制度によって実際に影響を受ける方々が存在することは重く受け止めるべきであり、その声が制度設計に適切に反映されるように求めていくことは必要であると考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"塚本副委員長","kind":"質問","question":"本日結論を出します。結論は不採択です。その一方で、この導入によって大きな影響を受けている方々については、インボイスだけではないと思うのですけれども、昨今の物価高騰における経済対策とか、あるいは事務負担の軽減とか、そういうところについては、廃止とは別の議論として議論していく必要はあると考えますけれども、本請願については不採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-086"},{"speaker":"石田（ち）委員","kind":"質問","question":"本日結論を出すで、採択でお願いします。ですので、その新たな方策というのを考えるなら、もう消費税を５％に減税すれば、今は物価高ですからね、区民生活も支援できるし、インボイスも廃止できるということにもなると思うのです。出せるものなのです。なので、区議会として意見を上げていく、そのことこそ、議会がやるべきことだと思いますので、採択してインボイス廃止の意見を上げていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-087"},{"speaker":"松本委員","kind":"質問","question":"本日結論を出すで、不採択でお願いいたします。今、国の制度でも地方から声を上げていけるというお話がありました。その上でこのインボイスについては、もう参議院選挙も近いわけですから、事業者の皆様、区民の皆さんはこの参議院選挙でしっかりと意見を出していただく、投票という形で結論を出していただくというところを私も見守りたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-088"},{"speaker":"須貝委員","kind":"提案","question":"そもそも国税庁が消費税を導入した中で免税領域を求めたことが、私は今回大きな発端だと思います。どうぞ今回この意見書、請願を提案された皆さんには、前も申し上げましたが、本当に国のほうに、国会議員のほうに働きかけていただきたいと思います。ですが、今回、また繰り返しますけれども、国会への廃止を求める意見書ということで、私はそれについてはこの請願に賛成いたします。以上です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-089"},{"speaker":"西本委員","kind":"質問","question":"本日結論を出すということで、不採択でお願いします。これに対して、今までも議会の中でたくさん請願・陳情を含めて議論してきました。でも、私も一貫して言っているのは、現状どうなのですか、品川区の事業者に関してということに対して、国がやることだからということで、今の品川区は踏み出すことはないのですね。だからそこがおかしいだろうと思っているのです。なので、不採択という形で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-090"}]},{"id":"topic-10","title":"はじめに、(1)令和６年度品川区一般会計予算繰越明許費繰越計算書","agenda":"はじめに、(1)令和６年度品川区一般会計予算繰越明許費繰越計算書","exchanges":[{"speaker":"西本委員","kind":"質問","question":"繰越しということなのですけれども、大体現状はというところで終わっていますという形なのですが、これは都支出金の場合、なぜ遅れているのですか。これはどういうことですか。例えば都からの支出金が遅延しているとかという原因なのですか。本来は令和６年度内に収めるべきものだと思うのですけれども、それができなかったという理由は何かあるのでしょうか。それと一般財源もあります。","respondent":"加島財政課長","answer":"７００万円で年度内の執行ということで見込んでおりましたが、９００万円以上、想定以上に寄附をいただきましたので、ただ頂いた寄附のものを別の用途に使うことはできませんので、それをそのまま繰越しさせていただいて。","id":"exchange-091"}]},{"id":"topic-11","title":"専決処分の報告について（報告第２１号）","agenda":"専決処分の報告について（報告第２１号）","exchanges":[{"speaker":"西本委員","kind":"質問","question":"１点だけ、すみません。(2)のところにも書いてある専決処分というのは、もちろん別に悪いというわけではなくて、どういうときに、報告ではなく専決になっていますね。その意味は何でしょうか。しかし専決処分になっているのですね。ということは、報告もなく専決処分というのは、それは時期的な問題なのか、何か理由があるのでしょうか。","respondent":"佐藤経理課長","answer":"これを受けまして、区長の専決処分事項に関する指定についてということが区議会で議決されておりまして、本件のような契約金額の５％以内の変更に係る部分については、令和４年７月７日に区議会で議決を受けているということになりまして、これらの規定に基づきまして。","id":"exchange-092"},{"speaker":"西本委員","kind":"質問","question":"５％以下は分かるのですけれども、本来は報告が先ではないのですか。だから議決ではなくて報告をしてとか、専決というのは時には必要だと思います。しかし本来は報告が先ではないのかと思いますが、そうではないのですか。何でもかんでも専決でやったら、５％以内だったら何でもかんでもやってしまうではないですか。ちょっとそのお答えください。","respondent":"佐藤経理課長","answer":"先ほど引用しました地方自治法の第１８０条ですが、この第２項で、専決処分したときは、普通地方公共団体の長はこれを議会に報告しなければならないとなっておりまして、専決処分をした後で、議会のほうに報告するという手順になっておりますので。","id":"exchange-093"},{"speaker":"須貝委員","kind":"質問","question":"それともう一点なのですが、普通障害物撤去等に伴う工期延伸に合わせた工期の変更ということですが、主に経費としてかかるのは、地中障害物撤去に対する工事費がかかるのは分かるのですけれども、これは両方とも機械設備工事請負契約と電気設備工事請負契約、両方にダブってくるということはあっていいのでしょうかと思ったのですが、その辺についてご見解を、１本でいいのではないのでしょうか。","respondent":"長尾施設整備課長","answer":"建築工事に地中障害物の撤去に起因して工事期間が延びましたので、その期間と併せて電気工事、機械工事についても工期を延ばさなければいけなくなりましたので、その延びた期間の分の現場事務所の維持であるとか、そういった経費を今回は増額の内容として。","id":"exchange-094"},{"speaker":"須貝委員","kind":"質問","question":"それにしては、実に両方とも増加したのは１,８３５万円と１,８２９万円ときれいに金額が並んでいるように見えるのですけれども、それほどきちんとこのようになるものでしょうか。だって、機械設備と電気設備工事というのは、これは誰が見ても、聞いても内容は違いますよね。でも、このようにぴたっと合ってしまうのですか。合ってしまうものなのですか。","respondent":"長尾施設整備課長","answer":"これは結果的に似たような金額になったというところでしかないかと感じております。","id":"exchange-095"}]},{"id":"topic-12","title":"今定例会の一般質問に係る所管質問ですが、本定例会の一般質問中、総務委員会に係る項目","agenda":"今定例会の一般質問に係る所管質問ですが、本定例会の一般質問中、総務委員会に係る項目","exchanges":[{"speaker":"須貝委員","kind":"質問・要望","question":"何かかなり重要性、重大性があるような質問の内容だったような、西本委員の発言からはそのように受け止めたのですが、その辺について区側に教えていただきたい。これからいろいろ改善云々をするのでしょうけれども、あくまで中心は職員に対する処遇というか、職員の働く環境を区側で構築しようとしている中の問題なのだと思うのですが、ほとんど分からなかったので、それを教えていただきたいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-096"},{"speaker":"西本委員","kind":"確認","question":"質問の中身は、アンケートをしたのかどうかということで、事実確認はしたのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-097"},{"speaker":"西本委員","kind":"確認","question":"やったということの確認だけはしています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-098"},{"speaker":"松本委員","kind":"意見","question":"今のところで、須貝委員はアンケートの中身とかの話があったと思うのですけれども、答弁の中で流出、漏洩したという話もあったと思うのです。これはコンプライアンスなので総務委員会に入ってくると思うのですけれども、そこの部分も、一応この都政新報の記事を見ると、そのアンケートは去年の１２月に職員が明らかにされたみたいなことも書かれてあったと思います。これはコンプアイアンスの関係です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-099"},{"speaker":"須貝委員","kind":"質問","question":"ちょっといいですか。今、情報漏洩というお話だったのですけれども、そうではなくて、どのような内容だったのですかと。ただそれを私としては聞きたいのであって、誰かが通報したとか何とかって、例えばもう極秘のこれは絶対口外してはいけないことを、そうすると何か区でやっていたのですかというと疑念になってしまうから、そうではなくて……。それは松本委員が聞きたいのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-100"},{"speaker":"西本委員","kind":"質問","question":"これは毎月毎月とか、委員会ごとにとかいうことではないのでしょうか。なので、出納検査結果というのはそういうものなのですか。そうすると、何月付、２月付、３月付、４月付と書いてあるわけだから、その月々にとか、例えば令和７年度の予算のときにでも発表するものではないのか、どうして今回まとめてどーんと出てきたのか、私が仕組みを考えるべきか、少し不思議だったので教えてください。","respondent":"黒田監査委員事務局長","answer":"例月出納検査につきましては毎月行っておりまして、監査委員のほうで検査をして、区長および議長のほうには報告しておりますが、その内容について、定例会ごとに報告するです。","id":"exchange-101"},{"speaker":"西本委員","kind":"質問","question":"これは４月末におけるというのが５月になっているから、定例会ごとに発表するという形になるとすれば、大体定例会のときに１月、２月は報告できるのでないかと思ったのですけれども、そのようにはならないのですか。どうなっているのでしょうか。","respondent":"黒田監査委員事務局長","answer":"繰り返しになりますけれども、出納検査は毎月行っておりまして、その監査委員協議会で検査しまして区長や議長に評価してございまして、出納検査の結果につきましては、議案発送のときに合わせて、資料としてお送りしておりますので。","id":"exchange-102"},{"speaker":"西本委員","kind":"質問","question":"そうすると、１月末が２月１８日で、２月が３月だからということで、だから第１回定例会のときには間に合わないから、第２回定例会でまとめましたということでよろしいのでしょうか。分かりました。時期的な問題ですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-103"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/121362?Template=document&Id=7103#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":74423,"voices":378}},{"id":"r07-20250701-6","meetingId":"r07-cm07","date":"2025年7月1日","dateIso":"2025-07-01","committee":"区民委員会","time":"午前１０時００分～午前１１時３１分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件抜き出しています。","topics":[{"id":"topic-01","title":"令和７年国勢調査","agenda":"令和７年国勢調査","exchanges":[{"speaker":"高橋（伸）委員","kind":"質問","question":"分かりました。もう一点なのですけれども、登録調査員は、今までのＯＢの方とかいろいろあると思うのですけれども、昨年品川区から新規調査員の方の登録をお願いしていると思うのですけれども、この１５１人の中で新規の方はどのぐらいいるのでしょうか。","respondent":"平原地域活動課長","answer":"今新規とその辺のところは資料がございませんが、前回令和２年は登録調査員が１１１名に対しまして、今回、令和７年は現時点で１５１名ですので、前回増ということでは約４０名の増となっています。ただそこが新規かどうかという内訳は大変申し訳ございません。","id":"exchange-001"},{"speaker":"高橋（伸）委員","kind":"意見","question":"これもずっと引き続きこうなるかと思うのですけれども、今後においても新規の調査員の成り手というのが重要になってくると私は思うのです。今後について、周知も含めて増加、増員していくというのが望ましいと私は思っているのですけれども、その辺についてご見解をお願いしたいと思います。","respondent":"平原地域活動課長","answer":"そういったところを併せて、今後の国勢調査においても、必要数を確保するといったところと、国全体においても、国勢調査の在り方というのは継続的に検討が進んでおりますので、そういった状況も見ながら、今後品川区においても登録調査員の確保を進めてまいりたいと考えています。","id":"exchange-002"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"この国勢調査は基礎資料をつくるためにも本当に重要ですので、今、課長が答弁されたように、今後も町会・自治会、新規登録者も含めて、次のときにはぜひともそういう方向を見据えてやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"おぎの委員","kind":"質問","question":"そういった地域を知っている方をもってしても、面会できないというか、連絡がないというか、訪ねてもいなくて、１０月以降、督促等を配布するようですが、それでも実態をつかみ切れない割合というのは、過去にどれぐらいあるのでしょうか。","respondent":"平原地域活動課長","answer":"接触が難しいといったところでは、国でも昨今マンションが増えているような状況で、そういったところを把握してございまして、今回令和７年の国勢調査から、例えばマンションなどで居住実態が管理組合などで把握できたときには、もう接触せずに投函するというか。","id":"exchange-004"},{"speaker":"おぎの委員","kind":"質問","question":"品川区はタワーマンションとかもすごく増えていますので、マンションの管理人ということは、管理している自分のマンションで当たってもらうということかと思うのですが、外国の方、または外国の方がオーナーで買われて、そこにほかの方が住んでいるとか、そういった場合の難しさみたいなものはどうでしょうか。","respondent":"平原地域活動課長","answer":"回収自体がなかなか困難という問題もございまして、今回の令和７年国勢調査では、前回から進められているインターネット調査をさらに拡大すべく、最初の配布段階のところで、アクセスキーといったものを、もう個別に特定したものを配布するということで。","id":"exchange-005"},{"speaker":"おぎの委員","kind":"質問","question":"こういった調査を通して、今までは３世帯だったのがどんどん減ってきている、２世帯とか、核家族が増えているとか、１世帯の人員が子ども２人だったのが、最近どんどん減っているとか、そういうのもこういったものを通して把握して、また世帯とか、住んでいる方に合った政策に落とし込んでいけると思いますので、ぜひ実態とか家族の形を把握して、またほかの課と情報共有というか。","respondent":"平原地域活動課長","answer":"私どものところで調査しましたものは、最終的には総務省のほうから公表という形になりますけれども、そういった数字を今後に活かしてまいりたいと考えています。","id":"exchange-006"},{"speaker":"こしば委員","kind":"質問","question":"国勢調査はまず認知されることが当然必要だと思うのですけれども、そういう意味では、調査書類が配布される９月２０日前の認知を高めていく取組、当然区だけでなく、国のほうでもＣＭとか何か、そういったものは使うのかもしれないですけれども、区のほうで特別にご案内するようなことはあるのでしょうか。","respondent":"平原地域活動課長","answer":"国勢調査はそもそも国全体の話ですので、国の周知はもちろんのことですけれども、区におきましても、区が持っている様々な媒体を活用いたしまして、国勢調査の実施年であること、調査方法、あるいは回答内容、そういったところについては周知をしっかりやっていく所存です。","id":"exchange-007"},{"speaker":"こしば委員","kind":"質問","question":"その上で９月２０日から調査書類が配布されるということで、地域の方といろいろと話をしていると、長年やっている方ですと、慣れているのかもしれない。実際の現場では、なあなあでやられているようなケースも少し耳に入ってきていますので、その辺りの状況把握、また対策ではないですけれども、取組について教えていただければと思います。","respondent":"平原地域活動課長","answer":"説明会につきましてはこれからという形になりますけれども、前回のコロナ禍のときには、かなり分散して行いましたので、回数自体が増えて、１回当たりの時間が短くなったのですが、今回そういうことのないように、１回当たりの時間を長く取るような形で。","id":"exchange-008"},{"speaker":"こんの委員","kind":"質問・要望","question":"５年前のときには１９項目あったのですね。私が調べたのが間違いでなければ、今回１７項目で２項目減っているかと思うのですが、前回と今回の調査項目の違いと、何がどういうふうに違ってきているのかというのを１つ教えていただきたい。そのときにマンション管理人・管理組合というところを特にお聞きしたいのですけれども、ここは今３９人となっています。","respondent":"平原地域活動課長","answer":"こちらは今委員がご指摘のとおり、まず自らのところが基本となるのですけれども、内容によってはそれ以外のところ、周辺地域もやるとか、そういったお話もありますが、基本はまず自分のところでやるといったところが１つポイントです。","id":"exchange-009"},{"speaker":"こんの委員","kind":"確認","question":"項目は、分かりました。調査員の確保のマンション管理人・組合も、そういうことを確認させていただきました。そもそもそういう集合住宅、マンションは、管理人ないし管理組合に委託というか、ダイレクトに調査員をお願いすることはできないのですかね。そんな体制が取れるともっと確保できるのではないかと思うのですが、その点について見解を伺います。","respondent":"平原地域活動課長","answer":"今の数といたしましては、まだこのぐらいの数になっているところですけれども、今後私どもといたしましても、そういったところへの周知方法でありますとか、これは義務というわけにはなかなかいかないので、お願いを工夫させていただいて。","id":"exchange-010"},{"speaker":"こんの委員","kind":"質問・要望","question":"この流れは理解したのですけれども、これまでそれを活用して、品川区として施策を、これが大事だ、これが課題だというものが幾つかあったと思うのですが、いわゆる地域活性化、地域活動として総務省から公表された結果についての何か施策で、こんなふうに工夫ができた、これは活用できた、こんなふうに品川区の地域活動を前進させることができたというような事例がありましたら。","respondent":"平原地域活動課長","answer":"そういった形で、国勢調査の数字というものは、国全体がやっている全数調査ですので、一番信頼性が高い数字ということになります。今、例で交通の話と防災の話をお示しさせていただきましたが、それ以外のところでもしっかり役立てていくというふうに考えているところです。","id":"exchange-011"},{"speaker":"こんの委員","kind":"質問・要望","question":"活用ありがとうあります。いかがでしょうか。","respondent":"平原地域活動課長","answer":"そういったところは今後の私どもの町会・自治会支援をはじめとした地域活動に活かしてまいりたいと考えています。","id":"exchange-012"},{"speaker":"せらく委員","kind":"質問","question":"今回もインターネット回答をやるということだったのですけれども、前回は非接触型ということもありまして、デジタル化によって調査の効率化を図ると思っているのですけれども、まず、前回調査におけるオンラインの回答率と、今回はこの程度の回答率を目標というか、見込んで設定しているかを教えてください。","respondent":"平原地域活動課長","answer":"品川区における前回のインターネット回答の割合ですけれども、４１.８％でございました。今回区として具体的なところはございませんけれども、国におきましては５０％以上を目指そうという動きになっているところです。","id":"exchange-013"},{"speaker":"せらく委員","kind":"質問","question":"先ほど調査員の確保の課題だったり、品川区は人口が増加傾向、でも日本全体で見ると、減少傾向にあると思いますので、国は５０％以上を目標で、どういうふうなインターネット回答の広報というか、お伝えの仕方、例えば、先ほど訪問してインターネットでもできますという話がありましたけれども、直接お会いできない方にはどういった周知の方法を考えているのかというところを教えてください。","respondent":"平原地域活動課長","answer":"インターネット回答の促進といいましょうか、そういった取組ですが、今、調査員から調査票の配布は非接触という形でやらせていただきますので、直接のご説明というよりは、資料をお読みいただく形になるのですけれども、そこに記載されている中で。","id":"exchange-014"},{"speaker":"せらく委員","kind":"意見","question":"インターネットでの回答がすごくしやすく、簡単になっているということで、分かりました。調査員の確保について、若い世代に声をかけたり、町会の中でも若い方たちがやってくれることもあるかと思うので、世代一体となって、精度の高い調査をしていけたらいいなと思います。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"}]},{"id":"topic-02","title":"（仮称）八潮ジムの開設","agenda":"（仮称）八潮ジムの開設","exchanges":[{"speaker":"こんの委員","kind":"質問","question":"内覧会が６月２８日にあったのですが、予定があって見にいかれなくて残念でした。申し訳ありません。とてもいい施策展開をしてくださっていると思います。幾つかお聞きしたいのですが、まずスケジュールのところから行くのですが、既にプレオープンをしてくださって、今日で３日目ぐらいなのですか。既に利用されている方がいますが、その様子をまずお聞きしたいと思います。","respondent":"今井八潮まちづくり担当課長","answer":"プレオープンについては本日で３日目です。６月２９日、３０日までの２日間で利用者数は２０名程度でございまして、利用されている内容としては、エアロバイク、あとはランニングマシンの利用が多い状況と聞いております。","id":"exchange-016"},{"speaker":"こんの委員","kind":"質問","question":"今回のこの事業については、高齢者の方の健康づくりといったところであるかと思うのですが、高齢者の方の参加はどうだったのかというのが１つと、八潮地域はシルバーセンターがないので、そうした観点も含めて、高齢者の方の交流の場、健康づくりにこの場を活用されていると思っているのですが、そういうことでよろしいでしょうかというのが２点目です。自分でやりたいだけの時間を設定するのでしょうか。","respondent":"今井八潮まちづくり担当課長","answer":"今後利用状況等を見まして、あまりにも混雑して待ち時間が長くなるようでしたら、受付簿のようなものをつくらせていただいた上で、例えばランニングマシン１人３０分までといったように時間設定するというところを検討させていただきたいと考えています。","id":"exchange-017"},{"speaker":"こんの委員","kind":"質問","question":"年齢層は分かりました。だからこそ利用する方がなるべく利用待ちしないような形を取れるといいなと思うのです。話が前後してしまうのですけれども、区民活動交流施設は、そもそもここは何かに使っていたお部屋を転用するという形だと思うのですけれども、これを転用してしまって、ここの場所でやっていた交流はできなくなってしまう、大丈夫だったのですかというところを最後にお聞きしたいと思います。","respondent":"今井八潮まちづくり担当課長","answer":"利用時間等の設定については、ほかの品川健康センターなどですと、台帳を置いて、そこで何分から使い始めましたということを管理していたり、あとはそれぞれ利用者にタイマーをお渡しして、時間を設定していただくというような取組をされていますので。","id":"exchange-018"},{"speaker":"こんの委員","kind":"質問","question":"タイミングが合って、空いた場所をうまく活用できているケースだと思います。これからも利用する方々が楽しめる、また八潮団地以外やその周辺の方々も利用できるような施設になってほしいと期待しまして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"おぎの委員","kind":"質問","question":"私も先日プレオープンでお伺いさせていただいて、非常にいろいろな種類の器械が並んでいて、体力づくりに非常にいいかなと思います。そのときトレーニングマシンは中古ということでお聞きしたのですが、品川健康センターからの中古ということでしょうか。","respondent":"今井八潮まちづくり担当課長","answer":"こちらのトレーニングジムの委託の運営費につきましては、現在１００万円程度で委託契約を締結しています。","id":"exchange-020"},{"speaker":"おぎの委員","kind":"質問","question":"品川健康センターの器具を入れ替えた際のものをメンテナンスして使われているということで、コストも抑えて非常にいいなと思います。高齢者の方もいらっしゃっていたというお話を先ほどお聞きしているのですが、急な体調不良への対応というのは、どんな感じになっているのでしょうか。","respondent":"今井八潮まちづくり担当課長","answer":"体調不良者への対応については、委託事業者と協力しながら緊急時のマニュアルを既に作成しておりまして、そちらに基づいて必要に応じて救急通報等をしていただくということで確認をしております。","id":"exchange-021"},{"speaker":"おぎの委員","kind":"確認","question":"委託の方がそうやってマニュアルを準備して、それに従ってやっていただくということで確認いたしました。急なときはやっぱり慌ててしまうので、そこに在駐しているスタッフの方がどれだけ訓練されているのかとか、時々そういったチェックといいますか、区のほうでも見回りを行っていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"こしば委員","kind":"質問","question":"先週の土曜日に内覧会に参加させていただきました。委託の方、受付といいますか、そこにいらっしゃった方から、いろいろと詳細な話を聞かせていただきました。そういうのは、３,０００円のコースがありますけれども、こういうコースに入っていなくても、現場で運営委託の方に、使い方が分からないから少し教えてとか、その辺の対応ぐらいはしていただけるという認識でよろしいですか。","respondent":"今井八潮まちづくり担当課長","answer":"委託の仕様上、機器の使用方法の指導についても委託事業者へお願いしていますので、言っていただければ、常駐しているスタッフが使い方についてもきちんとレクチャーするものになります。","id":"exchange-023"},{"speaker":"こしば委員","kind":"質問","question":"長時間使用しないでくださいというのは、トレーナーから注意喚起ではないですけれども、そういう話はぜひしていただければ、ある程度防ぐことができるかなと思います。こちらは内覧会のときは土足で入らせてもらったのですけれども、これはずっと土足のまま入って構わないのですか。何かその辺、多分子どもも入れると思うので、その辺は衛生的に少しどうかと思いました。","respondent":"今井八潮まちづくり担当課長","answer":"１点補足として、今回のトレーニングルームについては、１５歳以下の方については使用不可というようなルールを設定しておりますので、お子様については入っていただくことはできないというものです。","id":"exchange-024"},{"speaker":"こしば委員","kind":"質問","question":"そうしたら、４番の親子体操教室というのは、これはまた別の場所ということですか。","respondent":"今井八潮まちづくり担当課長","answer":"こちらのコース型運動教室の中に予定している親子体操教室については、参加者の年齢制限等は特に設けていないものになります。","id":"exchange-025"},{"speaker":"こしば委員","kind":"質問","question":"運動する、また夏場ですから、大量の汗をかく方もいらっしゃると思うので、水分補給が必要になってくるかなと思います。たしか１階に給水機があったかなと思うのですけれども、その辺、できれば同じトレーニングの部屋にあればなと。それはもう仕方ないとしても、給水機のポイントとかそういうのはなるべく分かりやすくお示ししていただければと考えていますので、その辺りをお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"せらく委員","kind":"質問・要望","question":"スケジュールのところで確認させていただきたいのですけれども、６月２９日から７月４日は毎日オープンしていて、地域住民等を対象にしているということで、７月５日からは、トレーニングルームが毎週土曜日、週１回のオープンというところで、認識が間違っていないでしょうか。確認させてください。","respondent":"今井八潮まちづくり担当課長","answer":"委員のご認識のとおりです。","id":"exchange-027"},{"speaker":"せらく委員","kind":"質問","question":"そうなると、先ほどお話しいただいたのが、日曜日は若い方が多くて、平日は高齢者の方が多いということだったのですけれども、土曜日だけに限定されてしまうと、高齢者の方は、年齢によっては使いづらくなってしまって、仮称というか、トライアルの事業になるので、効果検証がしづらくなってしまうのではないかと思ったのですけれども、土曜日にした理由があれば、教えてください。","respondent":"今井八潮まちづくり担当課長","answer":"委員からご指摘いただきましたとおり、できれば曜日を分けて実施したほうが、それぞれの曜日ごとにどのようなお客様の層がいらっしゃるのかという効果検証ができたところなのですが、今年度についてはトライアル事業ということで。","id":"exchange-028"},{"speaker":"せらく委員","kind":"質問・要望","question":"分かりました。トライアルということで承知しました。やっぱり地域に貢献したいというトレーナーをぜひ採用していただきたいというのもありますし、この地域の医療関係とかに限定しまして、高齢者の方が健康でいられるようなプログラムにしていただけたらという思いで、質問させてください。","respondent":"今井八潮まちづくり担当課長","answer":"こちらの事業者については、ほかの自治体等でもトレーニング指導ですとか、指定管理業務なども取り扱われているような事業者になりますので、そういった豊富な経験を活かして、今、委員からご指摘いただきました高齢者の健康づくりに特化したものですとか。","id":"exchange-029"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"私も内覧会に、早い時間にお邪魔して、せかして申し訳ございませんでした。若い自治会長とお話ししたときに、今こみゅにてぃぷらざ八潮が拠点になっていると。運営事業者なのですけれども、千葉県大網白里市にアリーナがあるのです。それと味の素のナショナルトレーニングセンターのトレーニングジムも運営事業者がやっているという中で、この事業者を選定した背景を教えていただきたいと思います。","respondent":"今井八潮まちづくり担当課長","answer":"委員からご案内いただきました内容、大網白里市のトレーニングルームですとか、ナショナルトレーニングセンターのトレーニングルーム等の運営をされているということで、事業者を決定した後に、こういったところの運営形態ですとか。","id":"exchange-030"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"契約期間というのはいつぐらいなのかというのを教えていただきたいと思います。本当に実績のある事業者なので、アンケート結果を踏まえて今後というのがあると思うのですけれども、まず契約期間だけ教えていただきたいと思います。","respondent":"今井八潮まちづくり担当課長","answer":"今回の令和７年度の八潮ジムの運営委託契約につきましては、年間で契約を結んでおりますので、令和７年４月１日から令和８年３月３１日までの１年間ということになってあります。","id":"exchange-031"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"それで内覧に行ったときに、事業者に更衣室はどこにあるのですかとお尋ねしたのです。そういった声は内覧会ではまだ何もないですけれども、どういうふうに、アンケート結果を踏まえてという部分があると思うのですけれども、現状を教えていただきたいと思います。","respondent":"今井八潮まちづくり担当課長","answer":"その辺の附帯設備的なところも含めて、シャワールームを含めて、今回利用者に個別にアンケートを取らせていただく予定になっておりまして、こういった機能がさらにあるといいというような。","id":"exchange-032"},{"speaker":"高橋（伸）委員","kind":"質問","question":"メインターゲットというのですか、八潮に在住している人たちが恐らくメインになると思うのです。そのほかに運動とかにいらっしゃる八潮地区にグラウンドがあるではないですか。そういう投げかけと、あとメインは八潮の方なのだけれども、区内在住の方も多分いらっしゃるわけだから、地図を見れば分かるけれども、こみゅにてぃぷらざ八潮の中はすごく分かりにくいじゃないですか。","respondent":"今井八潮まちづくり担当課長","answer":"委員からご指摘いただいたところは、今年度はトライアル事業という位置づけの中で、なるべく予算をかけずにスモールスタートでというような位置づけで始めたものではありますけれども、仮に一定の効果検証が図られて、今後本格運用に向けて事業を拡大していく、例えば年間で。","id":"exchange-033"}]},{"id":"topic-03","title":"令和７年度文化センター等工事による休室・休館予定","agenda":"令和７年度文化センター等工事による休室・休館予定","exchanges":[{"speaker":"こんの委員","kind":"質問・要望","question":"そもそも論から確認したいのですけれども、スクエア荏原が竣工したのはいつでしたでしょうか。そこを確認させていただきたい。","respondent":"大森文化観光戦略課長","answer":"スクエア荏原の竣工は今から１１年前という形になりますので、２０１４年です。","id":"exchange-034"},{"speaker":"こんの委員","kind":"質問","question":"２０１４年ということですので、今回の改修内容に非構造部材の耐震化工事と入っております。なので、これまでそもそも建てるときに非構造部材がない状態での建物を建てられたのではないでしょうかというところが気になったので、なぜ今この工事なのですかというのが１つ、併せて、荏原文化センターの大ホールのほうは非構造部材の耐震化は大丈夫なのですかというこの２点をお聞きしたいと思います。","respondent":"大森文化観光戦略課長","answer":"こちらについては、昨年、五反田文化センターのホールもやっているところでございまして、今、荏原文化センターのほうが済んだかどうかというところは確認できないのですけれども、そういったことで耐震化の強化ということで進めさせていただいているところです。","id":"exchange-035"},{"speaker":"こんの委員","kind":"質問・要望","question":"分かりました。そうであるならば、これは大事な工事だと思います。荏原文化センターのホールの非構造部材の耐震化というのは、後でまたお答えをいただければよろしいかと思いますので、非構造部材の耐震化というところが気になりましたので、質問いたしましたけれども、よく分かりました。その点について何かお取組などされていることがありましたら、ご紹介ください。","respondent":"大森文化観光戦略課長","answer":"場合によっては、機材等を置くに当たって使えなくなる部屋も出てくるので、そういったところも、ローテーションで一、二週間使えないという部屋があるところに対して、長期的に物を置く部屋ということで、使えなくなる部屋が出てくるということも考えられると思いますので。","id":"exchange-036"},{"speaker":"こしば委員","kind":"意見","question":"五反田文化センターのことで、全室が休室だということで、こちらですと防音設備の整った部屋があったかと思うのですけれども、例えば、そこで大太鼓をやる団体とか、いろいろとありますけれども、そうなるとこの期間はもう一切ここは使えなくなると、代わりにどこかといっても、代替施設を探すのはなかなか難しいと思うのですけれども、その辺のご案内といいますか、紹介とか。","respondent":"大森文化観光戦略課長","answer":"私のほうでも、お寺で音楽会をしたり、練習をしているといった情報を、方々探しながら、そういったところをマッチングというか、ご紹介するといったことをしているのですけれども。","id":"exchange-037"},{"speaker":"こしば委員","kind":"質問・要望","question":"多分まだ知らないと思いますので、そういったところで寄り添っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"高橋（伸）委員","kind":"質問","question":"（２）の学校プール夏季一般開放なのですけれども、実施校は６校あって、今、源氏前小学校が改修工事をやっていますよね。改修工事に入る前は、源氏前小学校も開放実施校だったのです。そうすると源氏前小学校があったときには７校あったのか、あるいは、荏原地区でいうと、源氏前小学校の代わりに第二延山小学校になっているのかというのを最初に教えてください。","respondent":"守屋スポーツ推進課長","answer":"ご質問の開放校の件ですけれども、基本的に学校との協議により決定しておりまして、本年度につきましては、鈴ヶ森小学校と源氏前小学校は工事が入っていて利用できないということで、６校で開放を実施しています。","id":"exchange-039"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"改修工事で使用できないというのは分かっていますけれども、鈴ヶ森小学校と源氏前小学校に代わる、そうすると今まで開放校が８校あったということですよね。２校減ってしまっているわけだから、近隣の方からすると、これはもう決まっていることだから、それでいいのですけれども、それも検討していただきたいと思ったので、それについて何かあれば教えていただきたい。","respondent":"守屋スポーツ推進課長","answer":"開放校につきましては、学校のプールの配置状況などによって、学校との協議により開放できる学校と開放できない学校があると認識しておりますので、開放できない年についてほかの学校を開放して調整することもできるのではないかというご意見につきましては。","id":"exchange-040"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"今まで使用していたところが減ってしまっているわけだから、それは教育委員会ともぜひ折衝というか、すり合わせしていただいて、例えばさっき申し上げたように、旗台小学校にするとか、増やしていただきたいという、要望で終わらせたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/541601?Template=document&Id=7109#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":29840,"voices":111}},{"id":"r07-20250701-7","meetingId":"r07-cm07","date":"2025年7月1日","dateIso":"2025-07-01","committee":"厚生委員会","time":"午前１０時００分～午後 ０時０６分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件抜き出しています。","topics":[{"id":"topic-01","title":"令和６年度品川区障害福祉計画等実績","agenda":"令和６年度品川区障害福祉計画等実績","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"１９ページなのですけれども、重度訪問介護の時間数が見込みよりも実績が倍近くになっていますけれども、これは２４時間利用という方も、なかなか品川区にはいなかったと思うのですけれども、そういう方も今いらっしゃるのか、いらっしゃるとしたら何人くらいいらっしゃるのかについて伺いたいと思います。そして、見込みに対してもゼロという状況がなぜなのかということも伺いたいと思います。","respondent":"松山障害者支援課長","answer":"４点ご質問いただきました。１９ページの重度訪問介護についてです。委員おっしゃられるとおり、２４時間介護をご利用される方が増えているです。５人弱ぐらいの方がおります。それから２点目ですけれども、行動援護についてです。","id":"exchange-001"},{"speaker":"鈴木委員","kind":"質問・要望","question":"２３日まで使えるということですけれども、先ほど、放課後等デイサービスを誘致して３か所できて、さらに２か所で、合わせて５か所新たなところができるというところで、誘致のところも、区のほうとしても取組みをされていると思うのですけれども、実際問題、希望する日数が通えないというのが今の状況はあると思いますので、さらなる誘致というのを、何か所、何人分が必要で。","respondent":"佐藤障害者施策推進課長、松山障害者支援課長","answer":"整備の状況の数字等を表に出している状況については今のところございませんけれども、内部では、今後必要な活動を踏まえて、こちらを区内に整備されるような支援の方策を引き続き検討してまいりたいと考えているところです。今、区内には地域定着支援のサービス事業所はございませんけれども、障害者の地域サポート２４事業、あるいは今回新たに精神障害者の退院居住支援事業といった中で地域定着支援を包括した。","id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問","question":"地域生活サポート２４というのは、障害者の方からは、すごくいい制度で、本当に充実してほしいという声もいただいていまして、それが法内という形になると、この地域定着支援事業ということになるということであれば、この地域生活サポート２４を地域定着支援事業の法内にして報酬を受け取れるような、そういう制度にはできないのかなという思いがしたのですけれども、そこら辺のところというのは。","respondent":"松山障害者支援課長","answer":"区としましては、地域自立支援協議会で協議して、様々な委員の方々からご意見をいただくとともに、今後、移動支援事業者連絡会を開催する予定で、待遇とかに関しても事業者のお声を聞きながら考えてまいります。","id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問・要望","question":"地域生活サポート２４は本当に親身になってやっていただいて、すごくいい事業と伺っておりますので、そこのきめ細やかなところは引き続き継続していただきながら、検討もしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問・要望","question":"このままこういうスパンで開かれるというふうに考えておられるのか、その辺についてまず伺いたいと思います。やっぱり、その会議の場でも、これは開かれたことはすごく評価されたと思うのですけれども、年２回なわけですよね。これはこのまま目標値として増やす方向で考えていっていただきたいなと思うのですけれども、その点について目標の立て方と、そのものがどうなのかというのをまず伺いたいと思います。","respondent":"佐藤障害者施策推進課長","answer":"現状の会議の内容ですとか参加されている方、そのほかの方のご意見を踏まえまして、これから次期の計画の策定の作業も進めてまいりますので、そこの部分については適切な開催の回数、内容も含めまして、どういった形で進めていくかというのは検討しまして。","id":"exchange-005"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ、検討ということですけれども、前向きな検討でお願いしたいと思います。やっぱり分科会でいろいろな方たち、当事者の方、当事者団体だけではなく、いろいろな方たちが参加する中で、具体的な施策なども検討されて、それが全体の自立支援協議会の中で整理されていくというのがいいのかなと考えていますので、ここはもうちょっと計画の中とか成果目標として書き込んでいただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"紙ベースで２４ページですけれども、（２）の相談支援のところの障害児相談支援の件数なのですが、件数が見込みよりも少ないということで、児童サービスの利用量は見込みよりも増えているのですけれども、減っているということで、もしかしたら、事業所が充足していないのかなと思えたりして、その辺の実態をお伺いしたいのと、もしかしたらセルフプランが増えている可能性もあると思いますけれども。","respondent":"松山障害者支援課長、佐藤障害者施策推進課長","answer":"私から、紙ベースの２４ページ、障害児相談支援の推移です。こちらは、ケアプランを作成した実人数ということになっております。定員ですけれども、児童発達支援と放課後等デイサービスを合わせまして、施設の規模としては合わせて２０名の定員を予定しておりまして、それぞれ、児童発達支援１０名、それから放課後等デイサービスについても１０名を予定しています。","id":"exchange-007"},{"speaker":"やなぎさわ委員","kind":"確認","question":"障害児相談支援の件で一応確認なのですけれども、区としては、事業所の数は足りているというような認識、例えば利用者の方からちょっと足りていないとか、そういう声とかというのはあったりするのか、確認です。いかがでしょう。","respondent":"松山障害者支援課長","answer":"かなり業務量が多くなっているです。今後、児童発達支援センター等が開設されますので、そういった開設状況の事業所の推移を見ながら、また事業者の意見を聞きながら検討していきたいと考えております。","id":"exchange-008"},{"speaker":"やなぎさわ委員","kind":"意見","question":"ちょっと内容が変わりまして、今回、この計画になかった障害児通所支援事業に対しての無償化が実施されるということになりまして、児童発達支援ですとか放課後等デイサービスが無償化されて、区内の事業所は当然需要も増えるかなというふうに想定されると思うのですけれども、今後どれぐらいの規模で誘致をするのかというのと、もしくは目標、何か所ぐらい増やすかという目標数値がもしお決まりでしたら。","respondent":"佐藤障害者施策推進課長","answer":"障害児通所支援の事業所有地につきましてですけれども、現時点で、この箇所数まで増やすというところの目標値については、お出ししているものはございませんが、先ほども申し上げたとおり、現在児童数ですとか利用数の把握等を行っているところ、それから。","id":"exchange-009"}]},{"id":"topic-02","title":"品川区立大原児童発達支援センター開設","agenda":"品川区立大原児童発達支援センター開設","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"先ほど、児童発達支援と放課後等デイサービスの定員は１０名ずつで、５人から始めるというご答弁だったのですけれども、保育所等訪問支援はどのくらいのレベルの規模でやっていくのかということを１つ伺いたいのと、インクルーシブひろばベルも今までと変わらない規模なのか、どれぐらいまでの受入れなのかというのを伺いたいと思います。","respondent":"佐藤障害者施策推進課長","answer":"インクルーシブひろばベルにつきましては、場所としましては、今回３階建ての建物を造りまして、主に２階のスペースを利用するような形で、スペース的には従前こちらの場所で実施していた規模とは大きく変わらない形で実施しておりますので、受入れの数としましては。","id":"exchange-010"},{"speaker":"鈴木委員","kind":"質問","question":"なかったとしたら、車で来た場合、駐車スペースとか何かはあるのか、ちょっとその点も教えてください。それともう一つ、ここでは、公認心理師の方もいるということなのですけれども、ＷＩＳＣとかの検査とかはできる体制はあるのか、その点についても伺います。","respondent":"佐藤障害者施策推進課長","answer":"ＷＩＳＣの検査については、今年度に関しては、実施はございません。ただ、次年度以降につきましては検査等を含めましては、施設の設備的なところ、それから、先ほどおっしゃっていただいた公認心理師などの対応を含めて検討はしてまいりたいと考えているところです。","id":"exchange-011"},{"speaker":"鈴木委員","kind":"質問・要望","question":"インクルーシブひろばベルの送迎とかは前からもご希望があったと思うのですけれども、そこら辺のところは検討されなかったのでしょうか。ちょっと２回とも都合がつかないといった場合、利用したい場合はどうなるのかなと思ったのですけれども、その点伺いたいと思います。","respondent":"佐藤障害者施策推進課長","answer":"そういった部分につきましては、個別のご事情についてお伺いして、対応については別途調整する猶予については想定しておりますので、そこについてはお伝えできる内容とかがありますので、なるべく基本的には説明会でこちらの内容を聞いていただいて。","id":"exchange-012"}]},{"id":"topic-03","title":"令和６年度品川区介護保険制度の運営状況","agenda":"令和６年度品川区介護保険制度の運営状況","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"特に、要支援２が全国平均１４.１％に対して２７.３％なので、２倍近い数になっているのですよね。それから、認定率なのですが、認定率も２３区平均は２０.６％ぐらいあるということなのですけれども、それも若干低いかなと思いますが、前に比べればだんだん上がってはきているのですけれども、この認定率も低いというところは、区としてどう捉えているのか、まずその点について伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"しかしながら、認定の結果が全国構成比と比較して、要支援の割合の方がかなり高くなっているということは数字でも如実になっておりまして、区としても認識しております。","id":"exchange-013"},{"speaker":"鈴木委員","kind":"質問","question":"それから次に伺いたいのが、３ページなのですけれども、３ページを見ると、先ほどもご説明がありましたけれども、特定施設のところが４５億円を超えて、介護保険財政の中で最も財政を使っているのがこの有料老人ホーム、特定施設だということなのですよね。この黄色い部分が要支援なので、特定施設有料老人ホームであれば、要支援の人まで入れるわけです。その２点をまず伺います。","respondent":"菅野高齢者福祉課長","answer":"今、保険料等、そういった財源の基で運営されているというお話なのだと思うのですけれども、介護保険の中で地域支援事業が、健康づくりとか、生きがいづくりなどの介護予防に関する事業として実施をしているという趣旨の下、そういった制度に当てはめて。","id":"exchange-014"},{"speaker":"鈴木委員","kind":"質問・要望","question":"選んで特別養護老人ホームに入りたい、有料老人ホームに入りたい。認定率も誤差の範囲と課長は言われましたけれども、２３区平均よりも認定率も低いわけです。要支援１、要支援２というと、本当に５万円とか１０万円しか使えないという軽い認定になっているにもかかわらず、品川区の保険料が高い理由はどういうところから来ているのか、区としてどう考えられているのか伺いたいと思います。","respondent":"菅野高齢者福祉課長、樫村高齢者地域支援課長","answer":"事実、品川区は現在介護認定が少し軽度に出ている傾向があるというような状況の中で、保険料が高いということはありますが、基金の現在の状況とか、それを国の見える化システムというところにいろいろとはめ込んで。総合事業における他自治体の財源等ですけれども、ちょっと今正確な資料は手元にありませんので正確にお答えできないのですけれども、多くの自治体では品川区同様に介護保険会計のほうで、同様に支出していると理解をしております。","id":"exchange-015"},{"speaker":"鈴木委員","kind":"質問","question":"ちょっと今の保険料がなぜ高いのかというのは、今の説明だとよくわからなかったのですけれども、介護認定が軽く出ているというのも、サービスを抑えるということになっていると思うのですよね。認定率はそんなに大きくは変わらないとしても、要支援の方が圧倒的に多いわけですから、そこら辺はなぜなのかというところは、またもうちょっと分かるような形でご説明をご検討いただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"吉田委員","kind":"質問・要望","question":"先ほどの介護認定が厳しく出るというのは、多分鈴木委員は地域の方たちからのご意見としてお聞きになっていらっしゃると思うのですけれども、私の場合は事業所をヒアリングしたときに、事業所の方から「なぜだろうね」という感じで、「介護保険の認定が厳しく出るね」というのをご意見として伺っております。それは先ほどの介護認定の話の中で申し上げることなのですけど。研修はしっかりあるのですって。","respondent":"菅野高齢者福祉課長","answer":"ただ今のお話ですと、事業者が言っている、事業者の立場でまたそういうお話もされているというところは真摯に受け止めて、どういった差異があるのかなというところは考えて検討していきたいと考えています。情報提供ありがとうあります。","id":"exchange-017"},{"speaker":"吉田委員","kind":"提案","question":"ケアマネジャーの質という言い方をしていいのかどうかも分からないのですけれども、やっぱり当事者のご要望をいかに聞き取るかというのと、当事者がこうだから、もうそのサービスは要らないのだと判断してしまっていいものか。だから、基本、介護保険というのは、当事者の方たちのためでもあるけれども、やはりそばでケアをしているご家族の状況とか、ご要望とかというのも汲み取らなければいけない。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ありがとうございました。昨日も申し上げましたけれども、昨年、父が介護状態になって、介護認定の調査をお願いしたときに、やはり訪問をしていただくまでにものすごい時間がかかった。もし、そうだとするならば、何か改善をされているのか、それとも、すごく厳しい状況というのは、今一旦落ちついているという状況なのか、その辺りについて教えていただきたいと思います。","respondent":"菅野高齢者福祉課長","answer":"今年度についてはその傾向が大分収まりまして、今ですと、本来ならば３０日以内にというのが国の規定なのですけれども、そこはちょっとまだ難しいのですが、４０日から４５日、１か月半ぐらいで判定が出るような傾向には落ちついてきております。","id":"exchange-019"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"職業病といいますか、８割ぐらい当たるのですけれども、ここ数年当たらなくなってきた。ぜひこういった取組みを増やしていっていただきたいなと思うのですが、現在いかがでしょうか。どれぐらいの見込みに対しての需要があるとか、これから増やしていくとか、そういった何か展望というのがありましたらお知らせいただきたいのですけれども、いかがでしょうか。","respondent":"樫村高齢者地域支援課長","answer":"今後も、そういった利用者のお声ですとか実績等を踏まえまして、新たに枠を増やすとか新たな事業を展開するとか、そういったところを検討しながら進めてまいりたいと考えています。","id":"exchange-020"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"ぜひこういった健康寿命を延ばす取組みを積極的にやっていただけるといいのかなと思っていて、ただいわゆる総合事業とかのデイサービスというか、通所とかと比べて何が違うかというと、送迎がないというところがやっぱり大きくて、どちらを使うかと迷っている方で、送迎があるから総合事業のデイサービスを使うという方もいらっしゃったりして、今後、ちょっと所管が変わってくるかもしれないのですけれども。","respondent":"樫村高齢者地域支援課長","answer":"委員ご指摘の方法等も含めて検討していきたいと考えていますが、そもそも元気な方は徒歩で、その会場に行っていただくというのも一つの運動、予防にもつながると考えていますので、そういったところも含めて検討していきたいと思います。","id":"exchange-021"},{"speaker":"やなぎさわ委員","kind":"意見","question":"おっしゃるとおりなのですけれども、これから夏場とかで、本当に１０分歩くだけでももう大変になってしまって、それだけで疲れてしまって、中でむしろ運動ができなくなってしまったりということもあるかもしれないので、ぜひいろいろ総合的に考えていただければと思います。お願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"障害者の入所施設の現状と課題ということなのですけれども、グループホームは入所施設というくくりになると思うのですけれども、グループホームとかもぜひ入れていただきたいと思うのですが、そういうことでいいのかだけ確認をお願いします。","respondent":"田中委員長","answer":"説明が不十分で失礼いたしました。正副あるいは理事者との協議の中でも、障害者グループホームも含めてということで進めておりましたので、委員ご指摘のとおりグループホームも含みます。","id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/166682?Template=document&Id=7107#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":36401,"voices":79}},{"id":"r07-20250701-8","meetingId":"r07-cm07","date":"2025年7月1日","dateIso":"2025-07-01","committee":"建設委員会","time":"午前１０時００分～午後 ０時１０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を52件抜き出しています。","topics":[{"id":"topic-01","title":"令和７年７月区営住宅入居者募集","agenda":"令和７年７月区営住宅入居者募集","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"９番の参考の直近の倍率なのですけれども、過去２回で申込者数が大きく違うのですが、この理由はどのように分析されておりますでしょうか。","respondent":"川原住宅課長","answer":"１月の募集時点では、ちょっと内容は変わってしまいますけれども、高齢者住宅の募集を秋に実施をしていますので、そういった、年間を通じての募集の時期というところも関係があるのではと考えています。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"例年、そのような傾向があるということだとは思うのですけれども、いずれにしても２０倍から３０倍と。ここ５年間の平均、事務事業概要を見ますと、ここ５年間でならすと倍率が３８.９倍、４０倍近い倍率であるのですが、これぐらい求めておられる方がいるということです。やはり区の政策として、私は区営住宅の増設というものを位置づけていく必要があると思うのですけれども、いかがでしょうか。","respondent":"川原住宅課長","answer":"このような民間住宅の入居の強化というところも、現在区では行っております。こういった民間住宅の支援や、また公営住宅については、維持管理をしっかりと行っておりますので、両方の住宅を見据えながら、今後も実施していきたいと考えています。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"様々区も手を打っているという話ですけれども、そういった政策を打っていただきたい。民間にも空きがあると言います。ですから、ここでしっかりとその区民のニーズに向き合って、住まいは人権ということですから、区として責任を大きく果たす意味でも、私は区営住宅の増設というものに踏み出していただきたいと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"今区営住宅の増設について、議論がありましたけれども、改めて２０倍、３０倍という状況ですから、区営住宅の増設の計画を持つべきだと思います。やはり区営住宅のほうが家賃も安いし、またご高齢の方はそのまま住み続けられることができるし、民間住宅にはない住宅のよさがあるから、これだけの方が申し込んだのではないかなと私自身は思っておりますけれども、区の考えを伺いたいと思います。","respondent":"川原住宅課長","answer":"今年度もさらに増えまして、今９８社まで増えました。高齢や低所得者、障害者の方の入居の促進といったところもしっかりと行いながら、区営住宅落選した方への対処というところも、住宅課全体で行っていきたいと考えています。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"落選された方への対処をしているということですけれども、私は、先ほど区営住宅をつくらない理由に、民間住宅で空きがあるとご答弁があったので、ならば民間住宅に空きがある中で、なぜこれだけの多くの方が申し込むのか、その理由をどう考えているのかと伺いました。ぜひその理由をご説明いただきたいと思います。","respondent":"川原住宅課長","answer":"一方で民間の賃貸住宅に関しても、セーフティーネット法が今度１０月に施行されるのですけれども、民間の賃貸も家賃の低廉化ができるものという形で、例えば高齢者に関しては、見守りつきの住宅というところも、非常に民間の大家からは要望とされているところですので。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"いろいろおっしゃいますけれども、明確な理由は示し切れていないのではないのかなと思います。今民間住宅に住んでいる方が、これだけの方が区営住宅に申し込んでいるわけですから、民間アパートの支援はしつつも、これだけの方が区営住宅に申し込んでいるという実態を見れば、区営住宅の増設が必要だということは明らかだと思います。強く要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"ゆきた委員","kind":"質問","question":"前回の申込数も、募集戸数に対して２３０戸と、かなり応募がなされていますが、この申込者数の年代別の統計など取られているのか、お聞きできればと思います。","respondent":"川原住宅課長","answer":"申込み者の世帯の内訳といったところです。細かな人数までは把握はしていないのですけれども、窓口での対応状況など、そういったところのヒアリングをさせていただいたところ、やはり６０歳以上というところの要件がありますので、単身者住宅を希望する方は高齢の方が多いです。","id":"exchange-007"},{"speaker":"ゆきた委員","kind":"質問","question":"今のご答弁の中で、ひとり親家庭や若者世帯もあるということで、でも、やはり高齢者の方が比較的多いと。そこについての情報発信と、足を運ばなくても電子申請できるようにするなど、より一層間口を広げていくことも必要だと思われますが、ここについては今まで議論もされてきたところだと思われますけれども、改めてここについて、何かあればお聞きできればと思います。","respondent":"川原住宅課長","answer":"おっしゃるとおり、現在は郵送を可とする形としておりまして、特に単身で申込みができる６０歳以上の高齢者の方については、窓口でその住戸の詳しい説明などもしながら、その場でここに申し込むといったようなかたちで、１世帯につき１戸のみ、重複の申込みはできませんので。","id":"exchange-008"}]},{"id":"topic-02","title":"カーボンオフセット都市ガスの導入","agenda":"カーボンオフセット都市ガスの導入","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"カーボンオフセット都市ガスとはどのようなものなのか教えてください。どのような原理でカーボンオフとなる仕組みなのか教えてください。それと、ゼロカーボンシティしながわの達成に向けて、最後のところですけれども、今後順次進めていくということなのですが、ほかのどの施設まで最終的には導入を進めていくという予定を持っているのか、伺いたいと思います。","respondent":"中西環境課長","answer":"どの施設まで導入していくかといったことです。区有施設の全てがゼロにならなければ、ゼロカーボンは達成できないところになりますので、最終的には全ての施設に導入していくということを進めてまいりたいとは考えてあります。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問・要望","question":"これは重要なことなので進めていっていただきたいのですけれども、ちょっとごめんなさい、Ｊ－クレジットという話が分からないのです。それ以前の問題で、もともと都市ガスというものは、燃やせばいろいろＣＯ２も発生するわけですし、それをつくる、生成するところでもＣＯ２は発生するわけなのですけれども、なぜこのカーボンオフセット都市ガスというものは、ゼロになるのでしょうか。","respondent":"中西環境課長","answer":"そちらに関しましても、当然東京ガスなど様々なガス事業者のほうで、今どういったことができるか検討され、例えば水素とＣＯ２を結合することで合成メタンをつくって新しい都市ガスをつくるような技術も進んでいるというようには聞いてあります。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"クレジットとして売買できることになって、実質ゼロカーボンになるのだというご説明ですが、ＣＯ２の排出量自体は減っていないということなのでしょうか。つまり、大事なことはＣＯ２の排出の総量を減らすことだと私は思っているのだけれども、この実質ゼロという言い方が、減ったこととみなすという意味なのか、そこをちょっとご説明いただきたいのです。","respondent":"中西環境課長","answer":"委員から今ご指摘いただいたとおりで、実質ゼロという言い方です。あくまでもみなすといったものです。先ほど安藤委員からもお話がございましたが、やはりエネルギー由来のＣＯ２排出というものを減らしていかない限りは、ゼロカーボンというものは達成できないところです。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"なるほど。ではＣＯ２を減らしたわけではなくて、ＣＯ２を減らしたとみなすということだというご説明でよいのでしょうか。品川区が掲げるゼロカーボンシティしながわとは、ＣＯ２の総量を減らす計画ではなくて、ＣＯ２を減らしたこととみなすということを掲げているのか、そこを確認させてください。やはり、今日も朝から暑くて、朝起きて部屋の温度を見たら２９度でした。","respondent":"中西環境課長","answer":"ゼロカーボンシティしながわ宣言におきましては、二酸化炭素排出量を実質ゼロにするゼロカーボンシティしながわというものを宣言しているものです。ただ、とはいえ、できる限り減らしていくといった思いは持ちながら努力をしています。","id":"exchange-012"}]},{"id":"topic-03","title":"大井町駅周辺地区バリアフリー計画の改定","agenda":"大井町駅周辺地区バリアフリー計画の改定","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"バリアフリー化ですね。その辺ちょっとお伺いしたいと思います。何かこれ結構先の話なのではないですかというか、まだ全然建物も建っていないし、跡地の活用については全くどのようなものが建つかすら、まだ検討中ということなのですけれども、このタイミングでの改定は時期的にそぐうのかなと、少し疑問なのですが、その辺についてはいかがでしょうか。","respondent":"櫻木地域交通政策課長","answer":"タイミングにつきましては、どのタイミングが適切かということで、全てが出そろうところまで待っていると、なかなかバリアフリー化も進まないということと、一定ＯＩＭＡＣＨＩ ＴＲＡＣＫＳ等のめどが見えてきたということと、法改正に対応する必要もあるということで。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"その際にぜひ説明会を開催していただきたい。こちらぜひ検討してもらいたいのですが、いかがでしょうかということが１つ。これらのことについて、計画策定に伴い改善するように求めたいのですけれども、いかがでしょうか。その計画策定に伴って、いつも大事だと言われるものが障害当事者団体の当事者参加なのですけれども、これはどのように具体化するお考えなのでしょうか。伺いたいと思います。","respondent":"櫻木地域交通政策課長","answer":"そこのご意見もいただきながら、計画ができるかどうかというところを含めて検討していきたいと考えています。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりました。当事者参加のまち歩き、それが一番いいのではないかなと思うのです。特に品川区視覚障害者福祉協会など、団体の皆さんのまち歩きのやり方や、あるいはメンバーなどについては、最大限当事者の皆さんの要望を踏まえた上で、具体的に実施していただきたいなと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"中塚委員","kind":"提案","question":"これは何の障害がある方なのか、別の言い方をすると、どの障害がある方の団体の代表なのか、そこをご説明いただきたいと思います。ぜひこの協議会に、メンバーとして初めから障害者枠の人数を増やして、区分というのでしょうか、それぞれの障害の区分の方から意見が言えるように、提案ができるようにしていただきたいと思うのですけれども、いかがでしょうか。","respondent":"櫻木地域交通政策課長","answer":"ある意味協議会の場というよりは、本当に実際にお声を聞いて検討を進めていくことが大事かと思っておりまして、その際には障害者支援課と連携して、７団体、それぞれの団体の方にお話を通して、実際まち歩きをしたり。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"７団体の会長ということですけれども、その協議会のメンバーも人数を増やすべきだと、改めて要望しておきたいと思います。この当事者アンケート調査、まち歩き点検等について伺いたいのですが、この当事者アンケートの当事者とは誰なのか伺います。今述べたところは、それぞれ意見が言えるようにアンケート調査をつくっていただきたいと思いますが、いかがでしょうか。","respondent":"櫻木地域交通政策課長","answer":"当事者のお声を聴くということであれば、それぞれの団体のほうにお伺いしてお話をお聞きする、またはまち歩きを通じて実際に意見交換をする等で、丁寧に拾っていければと考えています。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"いかがでしょうか。先ほど具体的に言いましたけれども、視覚、聴覚、肢体不自由、知的、精神、あと、高齢者、ベビーカーなどなど、それぞれの要望をリアリティーを持って聞けると思いますので、ぜひそうした取組をしていただきたいと思いますが、いかがでしょうか。バリアフリー計画ですから、例えば１か所だけで１週間となると、そこに来ること自体が大変なわけです。","respondent":"櫻木地域交通政策課長","answer":"はオープンハウス型説明会につきましては、現時点では、申し訳ございません、何もまだ、日程や場所等は決まっておりませんが、幅広にお話を伺う機会を設けるという趣旨はご指摘のとおりかと考えていますので、委員の意見を参考にしながら。","id":"exchange-018"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"私も大井町周辺での自転車、電動キックボードのマナーについては、何度も声を直接伺っているところです。改定スケジュールを見ると、６番の改定スケジュールのところでは、８月からまち歩き点検、１０月から心のバリアフリーワークショップが計画されていますので、進めていく中で、要望に対応していただきたいと思います。","respondent":"櫻木地域交通政策課長","answer":"心のバリアフリー化に関連して、自転車のマナーです。この１０年、委員のご指摘のとおり、自転車をめぐる環境も様々変化してまいりました。一定、区としましても地域交通政策課の中に交通安全担当ということで組織がありまして、そこで様々な取組を行ってきたところです。","id":"exchange-019"},{"speaker":"ゆきた委員","kind":"意見","question":"ほかの対策としても、自転車安全指導員の強化というようなことも行われていると思います。様々と対策を取られている中で、より一層対策を強化していただければと思います。このスケジュールの中である、まち歩き点検とか心のバリアフリーワークショップの中でも、地域住民の意に沿う形になるように進めていただければと思いますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"すみません。協議会の質疑の中で、障害団体は障害７団体の会長が参加するということでしたが、今回やはりバリアフリーの問題なわけです。今現在、７団体の会長は視覚障害の方ではないので、やはり視覚障害、品川区視覚障害者福祉協会の会長もぜひ入れていただきたいというか、入れることが絶対必要なのではないかと思うのですけれども、いかがでしょうか。","respondent":"櫻木地域交通政策課長","answer":"この協議会という場は、そのような意味でいうと、前者に近いところでして、どちらかというと、いただいたものを基に皆で頑張っていこうということで、様々な関係当事者を入れると、立場の違う方々を入れるというところになってありますので。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"毎年品川区視覚障害者福祉協会からは、まちづくりについてということで、別建てで、かなりバリアフリーのことについてご要望をいただくのです。それは区のほうにもそうですし、議会の会派にもそうなのです。まだ、８月からということなので、若干スケジュールも余裕がありますから、本当にリアリティーを持って、当事者参加といえば、もう本当に当事者中の当事者だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"せお副委員長","kind":"質問・要望","question":"バリアフリー計画というところで工事は重要だと思うのですけれども、ご理解いただくという面で何か考えてこと、対策というか、そういったものがあれば教えていただきたいのですが。すみません、漠然としていて。","respondent":"森道路課長","answer":"あるいは通行の制限をする必要があります。それにつきましては、事業者と、それから担当職員がご丁寧にしっかりと説明をして、ご理解いただけるように努めているところですけれども、なかなか自分の思ったとおりにならないというようなことは、どうしても出てくるかなと思います。","id":"exchange-023"}]},{"id":"topic-04","title":"一定規模以上の土地の形質変更に伴う手続きの未届事案について（土壌汚染対策法等）","agenda":"一定規模以上の土地の形質変更に伴う手続きの未届事案について（土壌汚染対策法等）","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"これは土壌汚染を防ぐための届出制度だったのかを確認したいと思います。ふだんは新しい制度や届出が創出されたとき、どのように漏らさずに徹底されているのかという状況をちょっと教えていただければと思います。","respondent":"森道路課長","answer":"ですから、先ほど今後の対応ということでお話したように、研修であったり、具体的な仕様書のほうにもう入れてしまっておいて、それが漏れのないようにしていきたいというところを、今後の対応として考えているところです。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"なぜそのようなことが起きるのかなというものが正直な私の受け止めですけれども、ぜひ反省していただいて、今後の業務に活かしていただきたいとはまず思います。対応策としては、研修をしていきます、仕様書に初めから書いておきますという対応策が示されましたけれども、改めて、なぜこうした事態になってしまったのか、起きてしまったのか、そこをご説明いただきたいと思います。","respondent":"森道路課長","answer":"そうなりますと、実際に所管課長ともいろいろお話をしていく中で、やはり担当者によって少し認識の違いがあったり、知識なり経験なりの積み重ねが少し足りていなかった部分もあったのかなと思いますし、例えば年度替わり、工事は大分長く続くものが多いもので。","id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"ただ、一定の大きさを超える場合は土壌汚染の調査が義務づけられて、いや、近所にあるニコンの解体がそうだったので、そうお聞きしているんですが、それで説明会も行われて、地域の方々も参加して説明を聞いて、工事が無事終わったわけですけれども、やはり法令や都条例が変わるというタイミングはこれからも必ずあると思いますので、徹底していただきたいと要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"教えていただきたいところがありまして、法に基づけば具体的な法令違反に該当し罰金刑などが適用されるものと思われますが、自治体として法に処罰される対応についてどうなるのか。３の調査対象年月日が平成１３年以降となっていますが、それ以前について同じような事案はないのか、また今後調査が行われるのか、この辺についてお聞きできればと思います。","respondent":"森道路課長","answer":"それで、基本的にはどういった用途で使われていたかということは、そのほかにもそれぞれ必要とする情報ではありますので、何かしらの調査はしていたかもしれませんけれども、ちょっと今回は平成１３年以降に法令が適用されているということですので。","id":"exchange-027"},{"speaker":"ゆきた委員","kind":"確認","question":"確認できました。本来であれば、自治体は、法令遵守の模範となるべき主体であります。再発防止についてもうたわれていますが、明確にそこを認識して、対処に当たっていただければと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]},{"id":"topic-05","title":"子どもの森公園改修工事","agenda":"子どもの森公園改修工事","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"よくポスターに出てくる黄色いアロサウルスのような、あれが残るのかということは確認させていただきたいと思います。あれは非常にシンボル的なものなので、確認させていただきたい。あれはなかなか知られていないのですが、かなりすばらしい施設だと思っていまして、子どもたちにめちゃめちゃ喜ばれているのですけれども、そうものは残るのか伺いたいと思います。","respondent":"大友公園課長","answer":"様々な手法で区民の声等と意見を聴取しています。品川学園の生徒を対象としたワークショップということ、また子どもの森公園周辺の住民へのアンケート調査、また子どもの森公園利用者へのヒアリング調査、また近隣の保育園などの調査を実施しています。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問・要望","question":"怪獣についてはこの公園のシンボルということで、子どもたちが残してほしいなというものを、ぜひ必要な補修も含めて残していただきたいという要望です。少年野球だけではなく、地元の高齢者クラブの方々がグラウンドゴルフの活動をしているということで、その工事期間中の活動保障というものを求めて質問もしてまいりましたけれども、そちらとしては最終的にはどうなったのか伺いたいと思います。","respondent":"大友公園課長","answer":"工事の方針といたしまして、段階的整備を行い、工事で使えなくなる期間をできるだけ短くしたいというところで考えているところです。こちらの野球場を先行整備いたしまして、野球場の完成とともに、野球場のみ、まず先行で開放したいというところで考えております。","id":"exchange-030"},{"speaker":"安藤委員","kind":"質問・要望","question":"様々な関係機関とも調整いただいて、こういった工事期間中の配慮というものを具体化していただいたということは、本当にすばらしいことだなと思います。今後の様々な公園などの工事も、今後ほかの公園でもあると思うのですけれども、住民の皆さんの声を聴いて、できる限りそうした対応をしていただきたいというようにご要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"松永委員","kind":"質問・要望","question":"幾つかご質問させていただきたいと思います。この少年の野球場についてなのですけれども、以前、ネットが低いのでネット上げてくれなど、そうした要望はあったのですが、その後、改良されてネットの高さが上がるのかどうかということ。","respondent":"大友公園課長","answer":"その中のグラウンドについて、天然芝なのか人工芝なのかというところにつきましては、天然芝での整備を予定しています。","id":"exchange-032"},{"speaker":"松永委員","kind":"質問・要望","question":"ご説明ありがとうございました。いろいろとご要望を叶えていただきまして、ありがとうあります。その中で、公園内はもちろん、自転車の乗り入れというか、乗って移動するところというものは、基本的に禁止でよろしいのでしょうか。","respondent":"大友公園課長","answer":"基本公園内、自転車の乗り入れというか、乗る形での運転は禁止という形の運用になるかと考えています。","id":"exchange-033"},{"speaker":"ゆきた委員","kind":"確認","question":"子どもの森公園で行われたグラウンドゴルフと、あともう１点、熱中症対策の２点について伺いたいと思います。ここの確認と、天王洲公園でのグラウンドゴルフ利用は、地域の事情によっては工事完了後も継続の可能性があるのか、お聞きしたいと思います。","respondent":"大友公園課長","answer":"２点ご質問いただきました。グラウンドゴルフの今後の利用についてというところですけれども、こちらのほう、工事完了後はまた天然芝の野球場としてオープンするのですが、グラウンドゴルフの利用も継続して利用していただく形で考えているところです。","id":"exchange-034"},{"speaker":"ゆきた委員","kind":"確認","question":"それぞれ確認できました。熱中症対策のほうについても、現在体調を崩された場合は、逃げ場として事務室が避暑する場所となっていると思います。ここについてもＡＥＤも設置されていると思われますが、全面改修と同時に、こういったお子さんが万が一の安全体制と予防対策についても、今後とも考慮していただければと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"せお副委員長","kind":"質問・要望","question":"全面ではなくていいと思うのですけれども、この子どもの森公園の改修において、障害がある方が使える、お子さんや大人の方に配慮した部分など、そういった部分があれば教えていただきたいということと、５年前ですか、子どもたちのアイデアを活かした公園づくりのワークショップを行ったときは、特別支援学校のお子さんも入ってお話合いをしていただいたと思うのですけれども。","respondent":"大友公園課長","answer":"インクルーシブの視点、どのような配慮がされているのかという点におきましては、今回、広い公園の整備というところにで、円滑に移動ができるようにという視点をまず第一に考えているところです。","id":"exchange-036"},{"speaker":"せお副委員長","kind":"質問・要望","question":"ワークショップも、そうですね、学年を決めてやるときも、品川学園には支援学級ありますので、ぜひそういった方、支援学級のお子さんも入っていただきたいですし、今後も、そのテーマが違ったとしても、当たり前に障害あるお子さんも入って話し合えるような場をつくっていただきたいなと思いますので、そちらも要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"安藤委員","kind":"質問・要望","question":"このような、何か斬新な新しい施設が入ると、すぐ料金を取るという悪い癖がまだまだ残っているものですから、やはりここらを契機に子どもたちにはしっかりと使ってもらおうと、それは保障しようではないかということで、管理棟もありますけれども、管理の問題もあるかもしれませんが、ぜひそのようにしていただきたいのですけれども、これは要望でもありますし。","respondent":"大友公園課長","answer":"追加で補足でご説明するのですけれども、先ほど少しずれた答弁をしてしまったのかなというところで、ワークショップには、特別支援学級の生徒にもご参加いただいているところです。","id":"exchange-038"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後のは私の好みなのですけれども、恐らくお子さんからもすごく人気も高いものだと思うので、その辺は、必要な改修というものはあるかもしれないのですが、ある程度そこは子どもの要望優先ということで考えていただきたいなと思います。それとバスケットボールコートに関しては大変失礼いたしました。無料で開放するという施設だということで、本当にそこは高く評価したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"}]},{"id":"topic-06","title":"東品川海上公園拡張整備工事","agenda":"東品川海上公園拡張整備工事","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"参考までに、土地賃貸借契約満了ということなのですが、どちらが貸していたのか。それは行政なのか、民間なのか。それがどのような理由で返還されたのかということを教えてください。","respondent":"大友公園課長","answer":"今回拡張整備予定地は、ここ、隣接する民間企業者がこれより以前から占用しておりまして、区事業者間の協議の結果、平成６年から有償で貸付けを開始したというところでございまして、令和５年度末に土地の賃貸借契約が満了となったというところで。","id":"exchange-040"},{"speaker":"ゆきた委員","kind":"質問","question":"ドッグランに限らず、区が公園の管理者として事業者の運営状況を定期的にチェックして、必要に応じて指導助言を行うための専門部署や担当者を配置するなど、こういった監督体制を強化する必要があると思いますが、この件についてお考えをお聞きできればと思います。","respondent":"大友公園課長","answer":"そこの管理運営について、品川区といたしましても、指導助言等々、また適正に管理できているかというところを努めていく必要があるというところはありますけれども、こちら今現存する公園課というところの中で、引き続き実施をできる体制を整えていきたいと考えているところです。","id":"exchange-041"}]},{"id":"topic-07","title":"第二戸越幹線整備工事（北品川特殊人孔等整備）","agenda":"第二戸越幹線整備工事（北品川特殊人孔等整備）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"様々な変更の理由分かりました。今回、かなり時間がかかってはいますけれども、今回のこの戸越第二幹線ですね。第二戸越幹線の整備がされた後に、どのような効果があるかということについて改めて伺いたいのですが、何mm対応になるのかなど、改めてお伺いしたいと思います。","respondent":"関根河川下水道課長","answer":"どの程度の効果、特に何mm対応になるかですが、こちらの事業の背景といたしまして、東京都が平成２６年に改定した東京都の豪雨対策基本方針に基づいて進められている事業です。","id":"exchange-042"}]},{"id":"topic-08","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"震災時、水道がかなり出なかったというところが大きな問題になりました。先ほどの所管事務調査のまちづくりというところもありましたが、１つそういったところも重要な課題になってくるのではないかと思いますので、能登のほうに行かれるのであれば、その辺についてもぜひ調査項目に加えていただければという要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"}]},{"id":"topic-09","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"先ほど委員長に概要をおっしゃっていただいたとおりなのですけれども、改めて、戸越１９番地に関する質疑の中で、部長の答弁より、風の状況について、ビル風が強い、倒れそうになったと、そのような住民の声を区長に伝えているとの答弁がありました。それを受けて区長からはどのような指示があったのか、ご説明いただきたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"区長のほうからは、地域からの声をしっかり受け止め、引き続き再開発組合に対して必要となる指導を行うことといったご趣旨の指示があったところです。所管といたしましては、区長からの指示を受けまして、引き続き再開発組合に対して必要な指導助言を行ってまいります。","id":"exchange-044"},{"speaker":"中塚委員","kind":"質問・要望","question":"ご説明ありがとうございました。もう少し掘り下げて伺いたいのですけれども、まず、区長に声を伝えているということですが、どのような状況というか、どのように伝えたのか伺いたいと思います。メールとか、紙とか、それとも口頭のみなのか、それとも本会議前の答弁調整会議の場で、このような質問を機に伝えているのか、どのようにされたのかということを伺います。","respondent":"大石まちづくり立体化担当課長","answer":"区長の指示を受けてからの変更点というご質問だったかと思うのですけれども、今現在再開発組合のほうからは、今後実施予定のモニタリング調査や、専門家ヒアリングの結果を基に対応策を検討する予定と聞いているところです。","id":"exchange-045"},{"speaker":"中塚委員","kind":"質問・要望","question":"分かりました。でも何か、一般的なやり取りだなというように感じました。１９番地は風がひどくなり、風害で悩まされている。１９番地については今後対応を検討するということですけれども、少なくとも被害が起きないような、具体的な対応策を区長には求めていただきたいし、こうした風の環境を悪化させる再開発の実施そのものも、ぜひ抜本的に見直していただきたいと要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"安藤委員","kind":"質問","question":"ですから、採用している評価方法について、どのような方法を採用していているのか。それは区がこれを採用してくださいというように指導しているのか、その辺どうなのかということを伺いたいと思います。なぜそれが適切な評価方法だと考えているのかついて、説明が全然まだまだ足りないといいますか。その辺についても併せて伺わないと、この組合への指導云々とならないと思うので、その辺聞かせてください。","respondent":"大石まちづくり立体化担当課長","answer":"こちら、戸越５丁目１９番地につきましては、前者の風工学研究所による評価指標を用いて評価検証を行っているというところで、その点を踏まえまして、区といたしましては、その評価がしっかりとされているものということで、本会議の答弁に至った経緯です。","id":"exchange-047"},{"speaker":"安藤委員","kind":"質問","question":"それをなぜ区は適切だと考えたのかというところなのです。ですから、なぜその評価方法を適切だと考えているのかという区の考えをお伺いしたい。東京都が採用しているからということなのですか。それが区の考えなのですか、伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"様々な防風植栽を設ける等、そういった形で対応いたしまして、この結果を、区といたしましては、ビルが建って一定風が強くなるところではありますが、指標に基づいてしっかりと検証されているというところで、適切な評価がなされているという評価をしています。","id":"exchange-048"},{"speaker":"安藤委員","kind":"質問","question":"一定風が強まっているということは認めるのだけれども、ただ、それは範囲内ですということなのです。そのように度々出されているわけですから、私はこの評価方法を採用していれば、基準を満たしていればよしとするという区の姿勢は改めるべきだというように、改めて申し述べておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"安藤委員","kind":"質問・要望","question":"筒井ようすけ議員の一般質問で、羽田空港アクセス線についての質疑があり、東山手ルートについての答弁がありました。一体区は何を、どういったところを検討しておられるのか、それは何ルートについて検討しているのか、それと、どの辺について研究しているのか、こちらをさらにお聞かせいただきたいと思います。","respondent":"高梨都市計画課長","answer":"２、これまで区が行ってきた調査、検討では、東山手ルートにおきまして、物理的に駅の設置が可能な場所や、ほか自治体の事例について検討等を行ってまいりました。","id":"exchange-050"},{"speaker":"安藤委員","kind":"質問・要望","question":"すみません、ちょっと確認なのですけれども、ＪＲ東日本としては東山手ルートのところを担当していると。それで、品川区が検討しているのも東山手ルートのみということなのかということを確認させていただきたいということと、それと、これ検討予算がついているわけなのですけれども、検討の予算の額と、あと検討委託先の名称ですか、どういったところに検討を委託しているのかということをお伺いします。","respondent":"高梨都市計画課長","answer":"最初の質問ですけれども、現在整備が進められているものが東山手ルートのみとなっていますので、当然区といたしましても、この東山手ルート沿線において、周辺のまちづくりとともに新駅設置の可能性について検討するといったことで進めてあります。","id":"exchange-051"},{"speaker":"安藤委員","kind":"質問","question":"分かりました。それと資料３の今後の予定というところで、臨海部のまちづくりの可能性や方向性を検討とあるのですけれども、その臨海部のまちづくりの可能性というものはどのような、何を指すのかということを伺いたいということと、それと最後の行で、関係機関と協議していくとありますが、関係機関というものはどこになるのか伺いたいと思います。","respondent":"高梨都市計画課長","answer":"東山手ルートのほかのルートはといったところですが、現在ＪＲ東日本によりますと、東山手ルート以外のルートにつきまして、具体的な開業目標や整備の予定等が公表されているような状況ではございません。","id":"exchange-052"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/570689?Template=document&Id=7153#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":42934,"voices":167}},{"id":"r07-20250701-9","meetingId":"r07-cm07","date":"2025年7月1日","dateIso":"2025-07-01","committee":"文教委員会","time":"午前１０時００分～午後 １時４２分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を58件抜き出しています。","topics":[{"id":"topic-01","title":"学校改築の進捗","agenda":"学校改築の進捗","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"全体の工事のところで、今、資材高騰がずっと続いていると思うのですけれども、そうした影響で遅れる心配などはないのかどうか、伺いたいと思います。","respondent":"荒木学校施設担当課長","answer":"資材高騰によるスケジュールへの影響ですが、特段ないと考えております。資材高騰により単価などは上がりますが、その都度、インフレスライドなどで対応していきますので、特段、スケジュールに関して影響はないかと考えております。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"それと、今回、浅間台バルコニーというものが造られるということで、これが１つ、特徴的なのかと思ったのですけれども、この利用イメージというのですか、どういうふうに今後使っていこう、活用していこうと考えているのか、伺いたいと思います。それと、太陽光パネルの設置など、図面上はあるのか分からないのですけれども、どれだけ設置されるのか、伺いたいと思います。","respondent":"荒木学校施設担当課長","answer":"３点目の太陽光パネルの設置ですが、現在、１０キロワットのパネルを屋上に設置ということで設計を進めてあります。４点目の高低差の解消ですが、擁壁が、資料の図面をご覧いただいて、西側と南側、あと東側の一部に広がっております。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"太陽光パネルは１０キロワットということで、この建物の規模からいくと少ないと感じてしまうのですけれども、これ以上つけられないということなのか、今後の温暖化のことを考えたら、ぜひできるだけ多くの設置をしていくということが必要かと思うのですけれども、そこを伺いたいと思います。","respondent":"荒木学校施設担当課長","answer":"そういったところで、最大限、１０キロワットでも確保したという計画です。","id":"exchange-003"},{"speaker":"高橋（し）委員","kind":"提案","question":"それを確認。いろいろほかの一般質問なども出ていますが、工事中のプールの活用について、これまでどうしても学校の中ではできないとなると、ほかの外部を借りるという提案なども、ほかの議員の方がされていましたけれども、そういったプールの授業の確保についてどのようにお考えになっているか。教育委員会としてリクエストというか要望していくのだとは思うのですけれども、そこのところを。","respondent":"荒木学校施設担当課長","answer":"３点目の今後の改築ですが、委員がおっしゃいますとおり、新庁舎建設が控えておりまして、区全体の投資的経費の平準化を図っていくことが重要だとは認識しています。","id":"exchange-004"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それぞれありがとうございました。今、新庁舎の関係で云々とありましたけれども、教育委員会として施策を長期的に考えていらっしゃると思うので、それを行政の財政課に対して、しっかりとというか、強くというか、進めていくように、教育委員会としてきちんと要望して実現していくようにするということで、今お話があったので、ぜひよろしくお願いします。鈴ケ森小学校のことだけもう一回。","respondent":"荒木学校施設担当課長","answer":"ですので、今後、学校と調整していきながら、近隣の浜川小学校など近隣校も活用して、水泳授業の確保には努めていきたいと考えております。","id":"exchange-005"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"私もプールの話なのですけれども、利活用の中で、よく移動の困難があるといいますが、例えば浅間台小学校などは、ウエルネススポーツセンターは歩いてすぐ行けるので、ぜひこういった民間のところの活用は形にしていただきたいと思います。それで１点だけ確認ですけれども、浅間台小学校の西門になるのでしょうか、正門になるのでしょうか、みこしのところはここですか。","respondent":"荒木学校施設担当課長","answer":"現校舎で言うところの、一番下の建て替え計画をご覧いただきまして、「既存西」と書かれているところのちょうど左上部分に存在しているということを確認しております。","id":"exchange-006"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"代替地等を考えているということは、あそこを移動するという話なのですか。もう話になってしまっているのですか。そうすると、地域があそこを残してほしいという要望があって、あれはもう取壊しになって、学校の一部になってしまうということなのですか。","respondent":"荒木学校施設担当課長","answer":"ですので、その後の移転先などにつきましては、浅間台小学校の敷地内を含めて、どこで確保できるかというところを、今後、調整しています。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問","question":"今回、法律・条例の改正があって、対象が変わったということで届出が必要になった、対象が変わったので気づかなかったということなのか、伺いたいと思います。これは、やっているところもあればやっていないところもあるというのも、よく分からないのですけれども、その理由を伺いたいのと、各所管課の認識不足ということなのか、そこを伺いたいと思います。","respondent":"つる委員長、荒木学校施設担当課長","answer":"全体の報告があったのですけれども、一応、所管で把握しているほかの所管のところもあれば、お答えください。なぜ今回、届出すべきところに気づかなかったかですが、庶務課を含め、工事発注の所管課において、やはり適正な法令の認識が不足していたというところが原因と考えています。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問","question":"なので、今まで、改正された情報というのはどのように共有されていたのか、伺いたいと思います。それで、調査報告書も未届けだったということなのですか。そういうものが、なぜなのか。基準値を超えているわけですから、いろいろ対応が必要になってくるわけで、いろいろ法律的に必要なことが出てくると思うのですけれども、未届けになってしまったというのは腑に落ちないのですけれども、いかがでしょうか。","respondent":"荒木学校施設担当課長","answer":"ただ実際には、Ａ３の別紙１の資料で示すとおり、どこで土壌汚染が検出されたか、それはどの程度の濃度であったかというものもしっかりと把握しておりまして、工事中にはこれが拡散しないように措置をしっかりと行いながら工事を進めておりましたので。","id":"exchange-009"},{"speaker":"のだて委員","kind":"質問","question":"実態的な被害がなかったのはよかったのですけれども、実際に被害が起こり得るというか、基準値以上の値が出たという中で報告書を出さないというのが、やはり認識が不足していたということなのですけれども、それだけでは説明し切れていないと感じるのですが、情報共有のところの、甘かったということなのですけれども、実際、私が聞いたのは、どういうふうに情報共有されているのですかと聞いたので。","respondent":"荒木学校施設担当課長","answer":"は今後どうしていくかという話ですが、そういったところの認識不足の解消とともに、業務上もシステム的にこういう漏れがないようにチェック表を作成するなど、具体的には、こちらは区の職員と設計者が一体となって事業を進めてありますので、設計仕様書の中に。","id":"exchange-010"},{"speaker":"のだて委員","kind":"質問・要望","question":"いろいろ業務上も段階としてやっていくということなので、ぜひ、そうしたことも位置づけて、漏れがないようにしていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]},{"id":"topic-02","title":"令和８年度 新入学者の受入枠","agenda":"令和８年度 新入学者の受入枠","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、中学校のところで、４０人学級から３５人学級に編成を変えるということで、今後、３年間かけて中学校も進めていくということで、よかったと思うのですが、実際、教室が、今後進めていく中で足りるのかどうかというのを恐らく試算していると思うので、そこを伺いたいと思います。","respondent":"石井学務課長","answer":"現在、中学校につきましては、まず１年生の段階で３５人学級にするための中１ギャップ措置というものがございまして、基本的には３０人学級、あとはきめ細やかな指導をする場合については教員の加配措置というところでなってありますので、今回改正があったところで。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問・要望","question":"分かりました。ぜひそれを進めていっていただきたいと思いますし、さらにいろいろ効果についてもお話しいただいて、さらに小学校はもう一歩踏み出して、３０人学級をぜひ実施していっていただきたいと思うのですけれども、いかがでしょうか。","respondent":"石井学務課長","answer":"学級編制につきましては、もちろん法令で定めていく部分と、あとは当然、その他の部分で全体の調整の中で、それこそ教員の加配や教員の担保といったことも含めて総合的に判断されるところですので、現段階で、例えば３０人学級のほうがいいか、またはそれ以上。","id":"exchange-013"},{"speaker":"のだて委員","kind":"質問・要望","question":"いろいろ法律や、確かに職員の確保というのが必要になって、もちろん教室の確保が必要になってくるということになりますけれども、ぜひここは、やはり少人数になったほうが教員の負担も減りますし、子どもたちも教員と触れ合う時間も持てるようになると思いますので、少人数学級を区としてもぜひ進めていただきたいと要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"高橋（し）委員","kind":"確認","question":"では全ての学校で、各学年の少人数の授業、例えば２クラス３展開などを展開しないという弊害は起きていないという確認でよろしいでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"特段、２学級３展開、３学級４展開などという形で小学校は行っていますけれども、教室が足りなくてできないというような状況は起こっておりません。","id":"exchange-015"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"普通学級を確保することによって、教室あるいはスペースが足りなくなって、それができなくなるということは、少人数の授業を行うことの深い意義が薄れてしまいますので、ぜひ今後もそういったことがあったときは確保していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"まつざわ委員","kind":"質問","question":"今のに関連するわけではないですけれども、先ほどもお話がありましたけれども、人口流動があるわけです。少数の人数が足りないといったときに、では隣の学校で教室がぱんぱんでどうしようもないといったときには、そういう学校で連携するという、ブロック連携というのですか、そういった考え方というのは現状あるのかと感じた次第です。","respondent":"石井学務課長","answer":"今の段階では、そういったブロック連携を実施しているという実績はないですけれども、本当に、例えば改築します、あとは教室増の工事をします、それをしてでも、なおも教室が足りないというような状況というものは、当然、将来的に発生しないとも限らないと思います。","id":"exchange-017"},{"speaker":"筒井副委員長","kind":"確認","question":"改築工事は、今現在、城南第二小学校でやっていると思うのですけれども、この人数が入れる教室というか体制は整えられているのでしょうか。それを少し確認したいと思います。","respondent":"石井学務課長","answer":"現在、学区域変更に伴い、改築の影響に伴って増える、恐らく今回の資料だと２４学級の形になると思いますけれども、その分の教室は確保しているよう進めているところです。","id":"exchange-018"}]},{"id":"topic-03","title":"品川区フリースクール等利用料助成金","agenda":"品川区フリースクール等利用料助成金","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"チラシで申請期間が来年３月３１日までとある中で、各期間ごとの申請開始時期というのが書いてあって、４期に分かれているというのが少し分かりづらいのですが、申請は期ごとにしなくてはいけないということになるのか、そこを伺いたいと思います。実際、フリースクールは一般的に、平均的にどのぐらいかかるものなのか、伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"４期に分かれて、それぞれ申請していただければ、その都度その都度、それに合った金額を助成していくという考え方です。","id":"exchange-019"},{"speaker":"のだて委員","kind":"質問","question":"申請のところは、そうすると申請機会が４回あるということなのですか。","respondent":"丸谷教育総合支援センター長","answer":"８月１日以降であれば随時受付をしておりますので、ただ、期間を区切って助成していくという考え方で、申請のタイミングが４回、４期あるということで、支払いのタイミングも４回設けている。ただし、遡っての助成も可能ということで説明はしていこうと考えております。","id":"exchange-020"},{"speaker":"のだて委員","kind":"質問","question":"１回でどんともらってもいいということでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"１回でまとめて３月に申請して、年間分、助成をもらうということも可能ですし、８月に申請していただければ、４月から６月分については最大６万円助成されるということで、その都度その都度助成されるか、それとも年間を通じて行うか、それとも、例えば第３期目に申請して。","id":"exchange-021"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回、フリースクールを利用した場合ということですけれども、やはり不登校の子どもたちで、フリースクールに行かないで、タブレットの教材などを使ったりして学習している子もいると思うのですけれども、それが対象になるのかどうかということも含め、ならないのであれば、そういったことも支援していただきたいと思うのと、あと、学校に行けば給食費が無償化されているということですけれども。","respondent":"丸谷教育総合支援センター長","answer":"区の施設の中でできることは今後も継続していきたいと考えておりますが、現在、フリースクールに通われているお子さんや、なかなか自宅から外に出られないお子さんに対しての支援というのは、引き続き検討が必要かと考えております。","id":"exchange-022"},{"speaker":"のだて委員","kind":"質問・要望","question":"いろいろ慎重な判断が必要だというお話もありましたけれども、ぜひ不登校の子どもたちにも支援して、学びを止めないということも含め、それ以外のことも実現していっていただきたいと求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"高橋（し）委員","kind":"質問","question":"なかなか教育委員会の範疇から外れてしまうという部分もあるのですけれども、実際、区に在籍しているお子さんたちが通っているということで、東京都の助成の対象となるいわゆる通所施設は、以下の条件を満たすものということで、東京都が２０項目近く出していると思うのですが、それを満たしているということで、一定の質といいますか、ある程度の質は確保されるのではないかと思うのですけれども。","respondent":"丸谷教育総合支援センター長","answer":"東京都も要件というものを示していますので、例えば通所型の施設である、健全育成を図っている、学校・教育委員会と連携・協力できるといった定めがありますので、こういったところで一定程度の質は担保しているとも考えております。","id":"exchange-024"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"困っている方が、もう本当にわらをもつかむ思いでお子さんを預けているところですので、教育委員会の範囲ではなくて、指導はできないと思うのですけれども、今後、実際、フリースクールに通われているということは学校を経由して分かるので、東京都のリストにも品川区のフリースクールで助成しているところがあるので、教育委員会としてできる限り、お子さんが通っているフリースクールの現状というか。","respondent":"丸谷教育総合支援センター長","answer":"我々教育総合支援センターとしても、そういったフリースクール事業者との連携というものも今後進めていきたいと考えております。情報共有や子どもたちの様子などといったところは、しっかりと連携して、フリースクールの状況等も確認していきたいと考えております。","id":"exchange-025"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"学校との連携でフリースクールについて関わっていっていただけるということで、ひとつ安心したので、ぜひお願いします。どうしても法の谷間でいろいろな事故など悲しいことが起きたりするので、そこは今、法的に整備されていないところを何とかカバーしていっていただきたいと思います。これは要望でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"まつざわ委員","kind":"質問","question":"今の話ですけれども、例えば、せっかく、このいい助成金を、品川区で５０名と限定して出すわけではないですか。そうすることによって、先ほどお話がありましたけれども、内情なども見えてくる部分というのがあるので、せっかく助成金を出すのですから、その辺も最後までやっていくというのは方法論の１つでいいのかなと、今お話を聞いて思ったのですけれども、いかがでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"一定程度、こちらも予算を組んで行っているものですので、今、想定としては５０名ですけれども、これを超えた場合でも支援はしていこうという考えもあります。効果検証も兼ねまして、アンケートや利用者の感想などといったものは、何らかの形で取っていきたいと考えております。","id":"exchange-027"},{"speaker":"筒井副委員長","kind":"質問","question":"私からは、今回の予算の５０人という想定なのですけれども、その想定の根拠は何なのか。つまり、この事業は東京都フリースクール等利用者支援事業助成金の交付決定者の方なので、今、既に東京都の助成を利用されている方のニーズを把握した上で、この５０人というのを想定しているのか。その辺り、今回の５０人の想定の根拠を教えてください。","respondent":"丸谷教育総合支援センター長","answer":"ですので、年度のいつから利用したかということも含めて、全体の予算の枠の中で支援をしていきたいということと、場合によっては補正予算を組ませていただいてというようなことも視野に入れながら。","id":"exchange-028"}]},{"id":"topic-04","title":"区立学校におけるいじめの重大事態の発生状況","agenda":"区立学校におけるいじめの重大事態の発生状況","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"それと、今回、事案番号２は、分類で言うと、２号もありますけれども１号もあるということで、これが生命、心身、財産に重大な被害が生じた疑いがあるということですけれども、分類としては、ひどくぶつかられたり、たたかれたり、蹴られたりということで書いてありますが、もう少し詳しくというか、どのような事態だったのかというのを、説明できるところがあれば伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"事案番号２についてですが、こうした事案の細かな部分については、この場では説明は控えしますけれども、いじめの態様の分類にあるようなことが行われた結果、１号および２号に当たるような事態を招いたです。","id":"exchange-029"},{"speaker":"のだて委員","kind":"質問","question":"なかなか、この場ではそういったことは語れないということだったのですけれども、そうしたら、今後フォローをどうしていくのかというところが１つ重要なのかと思いますけれども、その点はどう考えているのか、伺いたいと思います。それは今後どう考えていらっしゃるのか、伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"いじめが起こったときに、どういった形で解決していくかということですけれども、やはり学校が組織的にどのような支援や指導が必要かということを検討しながら進めていくことが大切だと考えておりまして、中にはお互いの謝罪で納得して解決するものもあれば。","id":"exchange-030"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"令和４年から重大事態は、ホームページで公開されているところ、２４件あったわけで、これまで大きな記者会見までされて起きたところから、現在までのいじめについての、大きな話ですけれども傾向と、区の対応はここまで、令和４年、令和５年、令和６年、３年少したったわけですけれども、それはどうだったかということで、現状を踏まえて、ここ数年の状況に対するお考えをいただきたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"月に１回だけではなくて、毎朝、登校時に、心の健康観察ということで、その日の気分を打ち込むような取組も全校・全学年で行っております。そういった、子どもの変化に気づき、早期に対応していくという仕組みも併せて行ったところです。","id":"exchange-031"},{"speaker":"高橋（し）委員","kind":"確認","question":"それぞれ詳しくご説明いただきましたので、今後、本当にゼロになるのを目指して、お願いします。１つだけ確認なのですけれども、調査結果の公表を望まない保護者の方がほとんどなのですが、２件だけ公表されました。それで、非公表の内容について、先ほど教員の研修のときには、こういった事例があってこうだということを、区内の教職員では共有することが可能なのかどうかだけ確認をお願いします。","respondent":"丸谷教育総合支援センター長","answer":"やはり、事案の共有というものは必要だと考えておりまして、ただ非公表になっているので、なかなか事細かなところまでは全校展開するのは難しいと考えております。","id":"exchange-032"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"本当に今、概要版というお話があったのですけれども、言い方は少し失礼なのですけれども、研修慣れしてしまうと、抽象的な言葉や、何というのですか、そういう基本的なことだとあれなので、なるべく具体的で、秘密、プライバシーが守られるような中身で、やはり、より具体的で、教員の方々が自分事と捉えられるような形で、ぜひ研修の資料といいますか、作って。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"横山委員","kind":"確認","question":"先ほどの質疑でも少しお話があったと思うのですけれども、被害を受け、いじめを受けた関係がある児童・生徒の子どもご本人と、あと家族に対してもやはり傷つきがあるかと思うのですけれども、この辺りも、教育委員会と、教育委員会以外の関係機関ももし関わられていましたら、そのサポートやケアの状況というのは、どういうふうに品川区として今後やっていくのか。","respondent":"丸谷教育総合支援センター長","answer":"場合によっては関係機関というところで、子ども家庭支援センターや、あと、これは主に加害のほうになりますけれども、内容によっては警察との連携ということも、国のガイドライン、本区の基本方針にも掲げておりますので。","id":"exchange-034"},{"speaker":"横山委員","kind":"質問・要望","question":"なので、そのケースそのケースによって、どうしていくのがいいかというのはなかなか判断が難しいかと思うのですけれども、学校内の環境調整だけにとどまらず、家庭内にどこまで踏み込んでいけるのかという、それこそ子ども家庭支援センターや、また加害というようなケースの場合には、警察や少年センター、本区は児童相談所もありますので、そういったところなど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"}]},{"id":"topic-05","title":"これからの市民科","agenda":"これからの市民科","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今後、市民科の在り方を検討していくということで、区の問題意識としては、この間の課題などというのはあるのかどうか、伺いたいと思います。","respondent":"唐澤教育施策推進担当課長","answer":"国でも言われているカリキュラムオーバーロード、学習内容を整理していくというのは、区としても同じように認識として捉えておりますので、学習内容についても、また整理・検討していきたいと考えております。","id":"exchange-036"},{"speaker":"のだて委員","kind":"質問","question":"今の道徳のやり方というのが、規範意識を押しつけるようなやり方で進められているということで、やはり、そういうことではない、人権感覚を教えていくといったことが必要かと思うのですけれども、道徳の点についてはいかがでしょうか。","respondent":"唐澤教育施策推進担当課長","answer":"市民科につきましては、道徳も統合して実施しているところですが、国の道徳につきましても、この間、教科化というものが図られてきて、「考え、議論する道徳」という形で発展してきております。","id":"exchange-037"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、押しつけではなくというお話は必要だと思います。やはり今、学ぶということは、自分の考えを整理しながら、いろいろな人と議論しながら考えていくということが必要だと思いますので、ぜひそうした形でやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"まつざわ委員","kind":"質問","question":"そもそも論というか、市民科の経緯、市民科というのは、それこそ社会の一員としての資質や能力、それで市民性の育成と書いてあります。市民性の育成というのは、何というか、すごく抽象的で、何が市民性なのかなとずっと思っていて、「市民性」という抽象的な言葉の中に、学んでいる子どもたちの成長というのですか、そういうものを見いだす、判断するというか、そういう基準は何なのでしょうか。","respondent":"唐澤教育施策推進担当課長","answer":"市民科地区公開講座というものを各学校で実施しておりますから、そうした際に、授業内容や、今みたいなお話など、地域・ご家庭に説明して理解を促しているという現状があります。","id":"exchange-039"},{"speaker":"まつざわ委員","kind":"質問","question":"これがやってきた基礎だというのは、もう十分分かっています。でも、せっかくこれからの市民科について新しくこうやって変えていこうというものがあるのだったら、そもそも一番初めの根幹に持っているものというのですか、こういったものの領域の見直しも含めて、ここをまず考えていく必要性があるのかと思うのですけれども、いかがでしょうか。","respondent":"唐澤教育施策推進担当課長","answer":"これからの市民科についてというところで、これから検討委員会でも検討してまいりますので、今お話のあった内容も含めて検討内容には入ってくるものと理解しております。","id":"exchange-040"},{"speaker":"まつざわ委員","kind":"質問","question":"例えば教科書作成という部分で、現場の先生の話などもどんどん入ってくると思うのですけれども、こういった現場の先生の声というのは非常に大事だと思うのですけれども、現場の先生の声などを、これからの市民科に向けて、どれぐらい反映していくおつもりなのかというのを聞きたいのと、あと、検討委員会メンバーで保護者というのがあるのですけれども、保護者というのは一体誰を指すのかという。","respondent":"唐澤教育施策推進担当課長","answer":"調査研究会につきましては既に実施しておりまして、そのメンバーにまず先生方が入られていますので、実際これから作る資料につきましても、教えられている先生方の意見というのは出していけると考えております。","id":"exchange-041"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ご説明ありがとうございました。その一方で、何で市民科をやっているのですかとか、市民科についてこのようなことを今、身につけているのですということを、学校ごとの考えで結構ですので、やはり保護者の方向けに分かりやすく提示して、市民科をなぜやっていて、今このようにしているというのを知っていただく大チャンスなので、そこを要望したいのですが、その３点をお願いします。","respondent":"唐澤教育施策推進担当課長","answer":"最後に３点目、保護者への啓発というような形では、先ほど申し上げた市民科地区公開講座の中で、今年度実施している学校においては、１つは地域との連携、防災や安全といった観点でやっている学校があったり、あとはいじめ防止について保護者を啓発して。","id":"exchange-042"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"保護者向けについては、今お話があったような内容もいいのですけれども、もう本当に単純に、Ｑ＆Ａみたいに、「なぜ市民科をやっているのですか」、Ａで校長先生の答えとして「こういうことでやっているのですよ」みたいな、本当に簡単なものでいいので、ぜひ公開講座のときに何らかの形で、紙ベースでもいいですし、何かやったほうがいいのではないかと思います。これも要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"横山委員","kind":"質問・要望","question":"ご説明ありがとうございました。少し確認なので、すみません。２番の「現行市民科の状況」の一番下に、「別紙『市民科の実施について』より抜粋」とあるのですけれども、今日の資料には特に別紙というのがなかったのですけれども、もしこちらがありましたらぜひ見せていただきたいと思いましたので、こちらは確認だけお願いします。","respondent":"唐澤教育施策推進担当課長","answer":"調査の対象ですけれども、今後、調査研究会、検討委員会でも諮っていこうとは思うのですけれども、実際、卒業生など、どこまで追えるかというところは、現時点だとなかなか難しいところもあるかと認識しているところですが、実際やはり市民科を学習した９年生につきましては。","id":"exchange-044"}]},{"id":"topic-06","title":"「品川区社会的養育推進計画」の策定","agenda":"「品川区社会的養育推進計画」の策定","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"これを実際、どういうふうに聞いていくのかというところを伺いたいと思います。やはり、いろいろな問題が恐らく中にも書かれていると思いますけれども、すぐに理解するのは難しいので、区民の皆さんに、より分かってもらうためにも、説明会をやって、そのことでパブリックコメントの件数も増えると思いますので、ぜひ実施していただきたいと思いますけれども、いかがでしょうか。","respondent":"柴田子ども施策連携担当課長","answer":"対象は、一時保護中の子ども、児童養護施設で生活している子どもに対して実施する予定です。それから、４点目のパブリックコメントにつきましては、他自治体の状況等を見まして検討してまいりたいと考えております。","id":"exchange-045"},{"speaker":"のだて委員","kind":"質問・要望","question":"パブリックコメントの説明会は、他自治体を見てということですけれども、ぜひ実施していただきたいと要望しておきたいと思います。それが、よりよい計画をつくることになるのかと思いますので。東京都の計画と大きく変わるところはないと、そうすると、品川区でつくる意義というのはどういうところにあるのか伺いたいと思います。","respondent":"柴田子ども施策連携担当課長","answer":"ただ、それぞれの自治体の状況というものを詳細に記載していくところがありますので、それはもう東京都と、数値といった部分は大きく変わりますので、品川区としてつくっていく意義があるものと考えています。","id":"exchange-046"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすると、品川区と向かう方向は一緒ですけれども、細かい課題が品川区に即した対応をしていくということかと思いますので、ぜひよりよいものになるようにしていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"横山委員","kind":"質問・要望","question":"要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"里親への支援に力を入れていくというお話だと思うのですけれども、現状、品川区が今やっている里親の新規登録や委託向上に向けて今やっていることと、例えばこの計画を踏まえた上で、今後、そういったものをどういうふうに、広報や支援体制を強化していくのかと、計画の段階なのであれですけれども、今、大体の方向性が決まっていれば教えていただきたいです。","respondent":"柴田子ども施策連携担当課長","answer":"今後、社会的養育推進計画の中でどういった工夫ができるかですが、国の要領の中には、社会的養育の認知と理解を求めるような取組という項目がありますので、そちらについても検討しながら、具体的に実績につながる取組を検討して、掲載してまいりたいと考えています。","id":"exchange-049"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"これはこの計画になるのか、よく、施設で育つ、施設で育ったなどというと、１８歳で退所、卒業されるケースが多いのですけれども、私もそういう施設を巡らせてもらったときに、やはり大きな課題の１つが、卒業した後は音信不通になってしまうケースが本当に多々あって、せっかくこういう計画を立てるのであれば、そういうことがなるべく起こらないように、区が中心となって。","respondent":"柴田子ども施策連携担当課長","answer":"区では今年度から、卒業、児童養護施設や里親の元を旅立った子どもたちに向けて生活応援の準備資金の用意をし、それから伴走支援ということで予算計上しているのですが、秋ぐらいから相談を専門的にやる窓口、支援の拠点も設置して。","id":"exchange-050"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"これは、子ども育成課の中で策定していくのですか。東京都の推進計画は１６０ページに及び、大変なボリュームがあって、非常にしっかりしたものなのですけれども、そこまでいかなくても、それに近いものを担当の課でつくるとすると、なかなか大変だと思うのですけれども、その辺はいかがでしょうか。","respondent":"柴田子ども施策連携担当課長","answer":"作業に関しましては、子ども育成課が中心に作業を進めていくのですが、どうしても内容に、児童相談所、それから子ども家庭支援センターといった専門機関の内容も含まれますので、現在、ＰＴという形ではないのですけれども、担当の職員をしっかりと組織して、今。","id":"exchange-051"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"心配したのですけれども、その点、業務量との関係で、もちろんきちんとしたものをつくっていただきたいというのが大前提なのですけれども、ぜひその辺の仕事量との関係を、管理職の方がしっかりとコントロールしながらお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"}]},{"id":"topic-07","title":"私立認可保育園の新規開設","agenda":"私立認可保育園の新規開設","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"スケジュールのところを見ると、今年９月から改修工事が始まるということです。改修工事が何をするのか、ビルの中なので保育園に合わせてやるとは思うのですけれども、園庭があるのかというのは確認させていただきたいと思います。事業者はテノ.コーポレーションということで、事業者の保育士の経験年数と離職率が分かれば伺いたいと思います。","respondent":"芝野保育入園調整課長","answer":"ただいまのご質問ですが、まずスケジュールですが、９月から改修工事という形で入らせていただく予定です。こちらはもともと健診センターといって、かなり保育園に近い形で活動されていた施設ですので、そんなに大きな改修ではないと聞いております。","id":"exchange-053"},{"speaker":"のだて委員","kind":"質問・要望","question":"保育士のところは、テノ.コーポレーションの会社としての独自の経験年数と離職率を伺ったので、ご回答いただきたいと思います。","respondent":"芝野保育入園調整課長","answer":"テノ.コーポレーションの保育士の経験年数ですが、申し訳ありません。今まだ把握しておりませんので、この場ではお答えできません。","id":"exchange-054"},{"speaker":"のだて委員","kind":"質問・要望","question":"既に品川区でやっている業者だと思いますので、すぐ分かると思いますのでぜひ把握していただいて、やはり保育士の労働環境が子どもたちの保育の質にも関わってきますので、よりよい保育になるように、ほかの面も含めてやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"}]},{"id":"topic-08","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"高橋（し）委員","kind":"質問・要望","question":"一方で、ハード面でどうしても厳しいところがあるので、現在、品川区の都立児童相談所が、移転というか、閉じるといいますか、大田区のほうということがあって、そこの跡地について、品川区立児童相談所の分室ではないですけれども何らかの施設にできないかということで、一般質問もさせていただいたのですが、それについて児童相談所から区の担当部署に、こういう状況なので、ぜひというような動きを。","respondent":"長谷川児童相談課長","answer":"開設から９か月が経過する中で、一つ一つの実績を積み上げている段階であり、目の前の一時保護中の子ども一人一人のニーズに応じた支援を、児童福祉司や児童心理司と連携しながら、引き続き実施してまいります。","id":"exchange-056"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ですから、そういう点を踏まえて、どこまでそういう発言を区の中でできるのか、私にはなかなか分からないのですけれども、そういうことで、ぜひ頑張っていただいてという言い方は少し失礼に当たるかもしれませんけれども、そういった立場を超えて、一番現場の方がお分かりですので、ぜひともそういった施設の拡大を求めていっていただきたいと思うのですが、そういった要求をしているというわけではなくて。","respondent":"長谷川児童相談課長","answer":"近くにあります東京都品川児童相談所跡地のご質問かと思います。あそこは東京都の所有でありまして、まずは東京都内部で検討されるのではないかと考えています。今、委員からご提案いただいた内容に関しましては、私どもから企画部門にも共有させていただきたいと思います。","id":"exchange-057"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ぜひ、千載一遇というか、あそこにあって、本当に現場で専門的にやられている方が、本当にあそこのほうがいいかどうかというか、その辺の判断があると思いますけれども、大きな機会だと思いますので、今お話があったように、企画部門にぜひ強く要望していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/178682?Template=document&Id=7105#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":49283,"voices":192}},{"id":"r07-20250701-5","meetingId":"r07-cm07","date":"2025年7月1日","dateIso":"2025-07-01","committee":"総務委員会","time":"午前１０時００分～午後 ５時００分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を63件抜き出しています。","topics":[{"id":"topic-01","title":"説明に入る前に、各所管委員会における審査結果","agenda":"説明に入る前に、各所管委員会における審査結果","exchanges":[{"speaker":"西本委員","kind":"質問","question":"民生費のところの病児保育なのですが、国と東京都からも補助金が出ているのですよね。例えば、時期的なものがあるのですか。それから、もう一つは繰入金なのですけれども、繰入金が２億円ぐらいいっているのですよね。これは、補助金で賄えていないものが繰入金でということなのですけれども、どういうところがどれだけ、どういう考えによって繰入金でカバーしてとなっているのか、そこの辺を教えてください。","respondent":"加島財政課長","answer":"こちらは、国の補助メニューに従って充当させていただいたものですが、残りの２億８,０００万円余につきましては、一般財源で手当てしているところになります。","id":"exchange-001"},{"speaker":"西本委員","kind":"質問","question":"繰入金なのですけれども、要は、国や東京都の補助金では賄えない部分について、繰入金でやっていくと思うのですけれども、それをするときに、どういう観点で、今回のメニューの中で必要だからという部分があると思うのですけれども、その中でのいろいろな部署の中で、これは優先順位が高いとか、これは優先順位が低いとか、いろいろ考えながら補正するのだろうと思うのですけれども。","respondent":"加島財政課長","answer":"そこを公表しておきながら、区として何も手当てを早急になさないというところにつきまして、区民の皆様の不安を増大させないよう、今回、６月補正で対応させていただきました。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"繰入金について答弁をお願いします。もう一つが、訪問介護サービスなのですけれども、なぜ今の時期にこれを補正で訪問介護サービスというのが出てきたのかというところで、その経緯というものを教えてください。","respondent":"加島財政課長","answer":"その結果、５５事業所中、３３事業所が収入減になっていたような実情が分かってまいりましたので、今回、６月補正で予算計上させていただきました。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"歳入のほうで、１１ページですか。物価高騰対策とどのように関連づけるのですか。これ、教えてください。それと、病児・病後児保育委託ですか。すみません、基本的なことで恐縮なのですが、急病とか急用ができたときに、ここは使える場所なのでしょうか。多くの区民の地元の人が使いやすいということを考えたら、こちらをもっと重点的にやったほうがいいように思うのですが、どうなのですか。教えてください。","respondent":"加島財政課長","answer":"稼働は９月以降になるのですけれども、例えば、お子様が夜お熱を出されて、どうしても親御さんが翌朝お仕事に行かなければならないというような場合には、親御さんの体力が気がかりな面もありますけれども、何とか朝、予約システムを使って。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"繰り返しますけれども、先ほどの１１ページですけれども、これ、物価高騰対策と載っているのです。重点支援。私は紛らわしいと思うので、これならやはり明確に、強く言えるかどうか分からないですけれども、国に、こんな言葉を使わないでくれと。病児・病後児保育に対しては、様々な対応をやっていただいて、多くの方が助かると思いますので、よりいい方向で進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"松本委員","kind":"意見","question":"充当事業として、初期消火体制強化費に１６０万円を入れていくということで、ここで、その下の説明のところに、補助基本額は３２０万円、２分の１補助が出ていることかと思います。これが歳出のほうでどうなっているかというと、２１ページのほうで、初期消火体制強化費として１６０万円計上されているということかと思います。","respondent":"加島財政課長","answer":"今、ご質問いただきました東京都の補助金につきましては、感震ブレーカー普及事業に充当させていただいているもので、この補助金の仕組みが非常に複雑なのですけれども、２分の１というふうに書かせていただきましたが、あくまで区の歳出に対する２分の１の補助ではなく、区が。","id":"exchange-006"},{"speaker":"松本委員","kind":"質問","question":"分かりました。区の負担の半分の２分の１だということで、感震ブレーカーを買う方の２分の１という理解でよろしいのでしょうか。","respondent":"加島財政課長","answer":"あくまで東京都の補助は上限２万円までしか来ませんので、そのうちの半分、１万円を補助するという考え方で、区は１６０件分の１６０万円の補助していくです。","id":"exchange-007"}]},{"id":"topic-02","title":"一定規模以上の土地の形質変更に伴う手続きの未届事案","agenda":"一定規模以上の土地の形質変更に伴う手続きの未届事案","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"聞き漏らしていたら申し訳ないです。これ全部、やってしまったものはやったもので、後で気がついたということですけれども、その後、検査とかをして、それは全然問題なかったということでしょうか。","respondent":"長尾施設整備課長","answer":"こちらの未届けであった９３件につきましては、届出の状況を今確認できたばかりでして、これから必要な土地利用履歴調査というものを、各案件に関して行っていく予定にしております。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問","question":"４番のところの発生原因というのが、認識不足、チェック不足というのがあるのですけれども、これを見て、法令が変わってくるときというのはいろいろほかにも様々なケースがあると思うのです。それに対してはどういう方法で周知をしていたのか。その周知の方法が徹底されていない理由が具体的にこういうところがあったので、具体的にこのようにしていきますみたいな、そういうのがあるのでしょうか。","respondent":"長尾施設整備課長","answer":"ただ、法改正、条例改正等の情報については入ってきたのですけれども、今回で言いますと、敷地面積としてどこの範囲を捉えるべきかというような認識の違いとかができて、間違って認識していた部分がありましたので、そういった周知は受けていたのですけれども。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"法令と都条例というのがあるわけではないですか。もちろん都条例のほうが厳しくなっているのですよね。今後、職員の方々はどういう認識を持っていくのか。職員というのは人事異動がありますので、その人事異動の際の引継ぎという中で漏れてしまうという部分も多々あるのではないかと思うのですけれども、そこら辺の徹底はこれからどうされるのか。これからの徹底の方法を教えてください。","respondent":"長尾施設整備課長","answer":"人事異動があった際のお話も踏まえてというところですけれども、今回考えている研修につきましては、一部の担当している職員に向けてだけではなくて、工事を所管している部署の技術職、建築、土木造園職の職員、管理職も含めて認識をしてもらえるように。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問","question":"なかなかチェックするのは難しいと思うので、やはりチェック項目をつくって、必ずチェックを入れるとか決めておくと、忘れないで済むかと思うのです。だから、今まで校舎があったところが校庭になったりというのは起きているわけです。当然、それも調査するという形で、全てにおいて今後はチェックを入れていくという感覚でよろしいのですか。","respondent":"長尾施設整備課長","answer":"特に学校につきましては、敷地面積の規模の、敷地を実際に掘るような対象範囲につきましても、条例や法令の届出の対象に基本的にはなってくるものになりますので、必ず最初の調査、土地利用履歴調査というものを敷地全体で行って。","id":"exchange-011"},{"speaker":"山本委員","kind":"質問・要望","question":"この法令に違反してしまっている状況の中で、この法令の中で罰則規定というものがあるのかどうか、確認をさせてください。これも、新設や改修のときに最初の時点で調べるべきものだと理解しておりまして、それが、それぞれの工事が終わっている状況の中でどの程度できるのかというのも思っておりまして、これから何ができてどうするのかというところが、お考えがあればお聞かせいただきたい。お願いします。","respondent":"長尾施設整備課長","answer":"届出ができていなかった９３件に関しましては、まず、速やかに今年度、土地利用履歴調査につきましては進めていきたいと考えております。","id":"exchange-012"},{"speaker":"山本委員","kind":"質問・要望","question":"最後に、要望としては、やはり今回の事例というのは、道路、公園、学校という、多岐にわたる行政の他部門のところでやっていて、届出済みのところも半数ぐらいある中で、できていないところがあるということでいうと、情報共有の仕方とかがとても大事なのかというところで、庁内機能でいえば、これまでもご説明いただきましたけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"松本委員","kind":"確認","question":"もう一個、発覚の経緯のところなのですけれども、２ページ目のほうの届出状況確認の経緯のところに発覚の経緯が書かれているのですが、これ、主語が書かれていなくて、土地利用履歴調査において確認できなかったということなのですが、これはどこの部署というか、誰が確認できないということに気づいたのか。ここのところはどうなのでしょうか。","respondent":"長尾施設整備課長","answer":"技術的な内容も絡んでおりましたので、施設整備課にも情報共有してもらいながら進めていたところでしたが、昨年度末の段階で、届出が一部できていなかったというところが、この調査の中で判明したというところです。","id":"exchange-014"},{"speaker":"松本委員","kind":"質問","question":"通常、企画課がやっていなかったということなのでしょうか。","respondent":"長尾施設整備課長","answer":"それは３,０００m2以上に達していない敷地で建てておりましたので、必要ないと判断をしていたのですけれども、ただ、この調査の中で対象としていたのは、学校として使っていた敷地全体を対象として行った調査でしたので。","id":"exchange-015"},{"speaker":"松本委員","kind":"確認","question":"多分、工事をやっているエリアが何平米かではなくて、敷地が何平米かというところを本当は確認してやらないといけなかったのが、どちらかというと、工事対象の形質変更の広さの部分で見ていたというところが一つなのかと思います。あるいは、これは場合によっては、実際に事業を行う民間の事業者から届出を行うみたいな仕組みはないものかというところはどうなのでしょうか。","respondent":"長尾施設整備課長","answer":"届出ができている案件につきましては、区のほうから、もともとこれは必要だと認識できていたものが基本的にはある。","id":"exchange-016"},{"speaker":"松本委員","kind":"確認","question":"そのまま進めていけるようなものだったから、進んでいって、先ほどおっしゃられた建築確認とかで本当は必要なのだったらそこで止まるみたいなところがあって、これはもちろんここからは区側のほうで過失もあったのだと思うのですけれども、この制度自体がすごく、そもそもの国の所管がどこの所管なのかというところもあったりして、すごく複雑な制度になっているのだというところを、聞いていて理解しました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"塚本副委員長","kind":"確認","question":"このようなことだったのかと捉えたのですけれども、改めてこの届出をしていなかったところについて、本来やるべきだった調査みたいなことができていませんでしたという。本来、土壌汚染を放置するようなことになるようなことはしていないのですよねという確認です。","respondent":"長尾施設整備課長","answer":"今回届出ができていなかった事案に関しましても、実際に工事現場で発生した土地を処理する際に、受入先の事務所と調整した上で、土質検定等を行って、必要な運搬・処分というところを行っておりますので、健康被害等の実質的な支障が出るような事態にはなっておりません。","id":"exchange-018"}]},{"id":"topic-03","title":"東品川海上公園拡張整備工事請負契約","agenda":"東品川海上公園拡張整備工事請負契約","exchanges":[{"speaker":"西本委員","kind":"質問","question":"工事内容のところに、土地賃貸借契約、これはどのような契約だったのでしょうか。区と相手側があると思うのですが、相手方はどんな感じで、どのようにしてこういう契約がなされたのか。経緯を教えてください。","respondent":"佐藤経理課長","answer":"本件土地の賃貸借契約があったというところのご質問ですけれども、こちらはもともと埋立地ということもありまして、土地自体はもともとは国が持っていた部分なのですけれども、平成６年に区が取得したという経緯になります。","id":"exchange-019"},{"speaker":"西本委員","kind":"質問","question":"そうすると、何年契約という形だったのかということと、それから、橋本産業が事業をおやめになるということで、今回、解消するということになったということなのですが、ガソリンとか石油と言っていましたけれども、土壌汚染の話もあったので、そこら辺の、どういう形で返却になっているのかとか、条件はどういう形になっているのでしょうか。","respondent":"佐藤経理課長","answer":"２つご質問いただいたと。契約に関しては、直近では事業の継続が、毎回検討するというところもありましたので、１年ごとの更新ということで直近では動いておりました。","id":"exchange-020"}]},{"id":"topic-04","title":"第二延山小学校空調設備改修機械設備工事請負契約","agenda":"第二延山小学校空調設備改修機械設備工事請負契約","exchanges":[{"speaker":"西本委員","kind":"質問","question":"空調の取り換えということで、これも昨日も同じようなことがありましたけれども、何年かで交換するという決まり事があるのでしょうか。","respondent":"佐藤経理課長","answer":"第二延山小学校は、改築されておりまして、２００７年に建設されていると聞いております。学校の設備については、耐用年数１５年程度ということで更新していると聞いておりますので、今回についても同様ということでご理解いただければと思います。","id":"exchange-021"},{"speaker":"西本委員","kind":"質問","question":"１５年程度ということなのですが、学校改築、いろいろされていて、当然ながら順番とかがあると思うのです。その決め事、順番とかというのは何かあるのでしょうか。今回は第二延山小学校ですけれども、次はとか、これからの計画というのは明確な計画があって、それを毎年更新するとか、そういう状況になっているのでしょうか。","respondent":"佐藤経理課長","answer":"委員ご発言のとおり、順次改築、大規模改修等行われておりますので、それに基づいて順々に計画的に改修等をしていると聞いております。","id":"exchange-022"},{"speaker":"須貝委員","kind":"質問","question":"昨日申し上げましたけれども、これだけの台数、空調機更新工事ということになっております。品川区も、区長を先頭に行財政改革を進めている中で、やはりこういう設備に対しても、使えるうちは使っていくような、そういう方針に転換すべきではないかと思います。もったいないという考えを取り入れていくという方向性も私は必要だと思います。これ、質問してもしようがないので、意見だけで終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"}]},{"id":"topic-05","title":"庁有自動車のカーナビ等に係るＮＨＫ放送受信契約の未締結","agenda":"庁有自動車のカーナビ等に係るＮＨＫ放送受信契約の未締結","exchanges":[{"speaker":"西本委員","kind":"質問","question":"対象機器というのは、１５７台の契約が未締結だったという理解でよろしいですか。ワンセグ携帯電話、テレビが視聴可能なモニター、これ、どんなときに使うのでしょうか。主にはどういう部署の方がお使いになっているのかというのを教えてください。再度、契約をするのでしょうけれども、いつまで遡ってやっていって、どれぐらいの金額になってくるものなのか、そこを教えてください。","respondent":"佐藤経理課長","answer":"モニターについては、説明で会議のときに使う映すモニターと申し上げましたけれども、これに関しては、特にここというわけではなくて、何課かで１台ずつとか、そういったものですけれども、そのほかに、保育園で防犯カメラをつけて、モニターとして確認するのですけれども。","id":"exchange-024"},{"speaker":"西本委員","kind":"質問","question":"そうすると、遡るのが２０年前ぐらいから遡らなければいけないという現状だということですよね。そのイメージはどう思われているのでしょうか。","respondent":"佐藤経理課長","answer":"他自治体で報道されていると申し上げましたけれども、こちらについて、例えば、県庁レベルになると、数千万円というところもありますし、小さい自治体だと、それでも数百万円ですとか、そういった報道はありますので、関係課と調整しておりますけれども、具体的な金額が出てから。","id":"exchange-025"},{"speaker":"西本委員","kind":"確認","question":"それで、事態の発生なのですけれども、認識不足というところなのですが、これ、契約するときとか、誰かしら契約しているわけで、確認が取れなかったのでしょうか。支払わなければいけないという、その内容を、契約するときにチャンスはあったと思うのです。これは全然そういうのはなかったという、チェック機能が働いていなかったという認識でよろしいでしょうか。","respondent":"佐藤経理課長","answer":"現在、区の中でテレビが２４５台ありますということで報告しておりまして、ずっと調査をやっていたところなので、正直、この調査に関しては、テレビの台数を報告するというところで、職員のほうで、私も含めてですけれども、認識していたということになりまして。","id":"exchange-026"},{"speaker":"松本委員","kind":"質問","question":"くにば前議員が、令和２年の第１回定例会の一般質問で聞いているのです。実際にこのカーナビの問題、携帯電話のワンセグ機能について見直すべきと、これは明確に質問していて、当時の濱野区長が答弁に立っているので、本来はこれは令和２年の段階で、もし、くにば前議員の一般質問をきちんと踏まえていたら、こういうことは起きなかったと思うのですが、この点はいかがでしょうか。","respondent":"佐藤経理課長","answer":"委員ご指摘のとおり、そういった区議会でのやり取りも含めて、あるいは裁判での結果の報道を踏まえて見直すタイミングがあったのだということは、現状から見れば、私も思いますけれども、ただ、結果としてはそう至らなかったというところは大変申し訳なかったということで。","id":"exchange-027"},{"speaker":"松本委員","kind":"意見","question":"別に私はくにば前議員の代弁をする必要もないと思うのですけれども、ただ、議会にいらっしゃらないので、もしいらっしゃったら、ここはすごく追及していたのではないかというところで、いらっしゃらない方の声を代弁させていただいたところで、今後は、契約しなくて済むように、そもそも見ていないのに受信料を取られるという制度自体が、一国民としてはおかしいのではないかと思いますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"須貝委員","kind":"質問","question":"私は、区の責任はないかと思うし、テレビが毎年２４５台というのは、調査に来て、きちんと支払っていると。では、ワンセグ系の携帯はどうなのですかと。天下のＮＨＫがこういうお金を取るというのは、私はやはり道理として、社会通念上、おかしいと思うのですが、その辺についてご見解をもう一度お聞かせください。","respondent":"佐藤経理課長","answer":"２００６年に地上デジタルが始まったということなのですけれども、ワンセグ放送の携帯電話に受信料がかかるという確定の裁判が出たのが２０１９年だったというところもありますので、私の立場から申し上げることではありませんけれども、その間に購入した携帯電話等に関しては。","id":"exchange-029"},{"speaker":"須貝委員","kind":"意見","question":"先ほど松本委員もおっしゃっていましたけれども、このようなことをやられるならば、やはりガラケーのものなども、それからあと、車についている、受信できるテレビもそうですけれども、レンタカーなどはテレビが受信できないようになっているし、そのような工夫をして、私はこういうお金こそ払うべきではないお金だと思いますので、それだけはしっかり申し上げておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"}]},{"id":"topic-06","title":"令和７年６月２２日執行 東京都議会議員選挙の結果","agenda":"令和７年６月２２日執行 東京都議会議員選挙の結果","exchanges":[{"speaker":"西本委員","kind":"確認","question":"確かに手ぶらで行けるのです。書かせるだけで、本人確認をしないのです。なぜかというと、本人確認していないので、住所と名前が分かれば、幾らでもやれるわけです。なので、今後は、本人確認はある程度必要なのではないかと思うのですけれども、これは公職選挙法だから、品川区で決められるわけではないので、ただ、そういう疑問はやはり一応話題になっていたということの認識はあるのか。","respondent":"今井選挙管理委員会事務局長","answer":"ですので、委員ご指摘のとおり、不在者投票におきましては、ご自分できちんと書いていただくということが１点ありますし、また、時には投票所入場整理券をお持ちでない方もいらっしゃいますけれども、改めて期日前投票では白紙の入場整理券を用意しておりまして。","id":"exchange-031"},{"speaker":"西本委員","kind":"確認","question":"結局、全て申告制なのですよね。だから、確認をしていないのです。だから、今回、話題になっていたのは、簡単にできるよねと。「手ぶらで行けますよ」、「そのまま行けばいいですよ」と、宣伝は結構しているではないですか。実際、手ぶらで行って、どういう方法だったのかというと、本人確認もしないし、ただ住所を書くだけ。名前を書くだけ。すごく心配しています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"西本委員","kind":"意見","question":"それはそれです。私が言いたいのは、そういう認識を持っていますかということです。持っていなければ、上げようにもないですよねという話で、意識を持っていれば、意見を言う場所があるのだったら、そこに意見を言ってもらいたいし、もちろん議会でやらなければいけないことはあると思うので、議会は議会で動かなければいけないと思います。それについてお答えをお願いします。","respondent":"今井選挙管理委員会事務局長","answer":"こちらの期日前投票の本人確認につきましては、先ほどご説明しましたとおり、ご本人に住所とお名前を書いていただき、選挙人名簿に必ずその方の住所、名前を確認して、そこで選挙人名簿と照合させまして、本人確認をしているという認識です。","id":"exchange-033"},{"speaker":"西本委員","kind":"質問・要望","question":"今まで私たちの意識がなかったところだったのです。なので、こういう指摘をいただいて、本人確認は何かしら必要だろうと。うそをつかないだろうということではなくて、やはり今、いろいろなところで本人確認というのは厳しいです。本人確認します、本人の住所の確認をしますというぐらいは言えると思うのです。今後も含めて。それの方法を探っていただきたいと、お願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"}]},{"id":"topic-07","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"競馬事業についてですが、これは品川区の事業ではないので、品川区の所管事務調査として私はふさわしくない項目だと思います。私はこれを、委員長、副委員長がいらっしゃって、やはり総務委員会ですから、ふさわしくない事業を所管事務調査項目に入れるというのは、再考すべきだと思います。それはしっかり私は言っておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"須貝委員","kind":"意見","question":"委員長の今熱い思いは、がっとこちらに向いているのはよく分かります。だけど、品川区といえども、やはりこの大都市の中にある２３区の抱えている様々な諸問題があると思うのです。そういうことを思うと、これだけ多くの理事者の方が来ていただいている場で、そういうことを議論したい、してほしいというのが、私は総務委員会に対するそういう強い思いがあるので、それで申し上げさせていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"西本委員","kind":"意見","question":"私たちで議論して、こうあったらいい、こうしたほうがいいねといういろいろな提言が出てきたときに、どのようにそれを上げていくのかというのをどう考えていますか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"西本委員","kind":"質問","question":"ＴＣＫとやるのですけれども、いろいろ議論をする中で、理事者の方々の答弁というのは、ＴＣＫの中身のことになると、ＴＣＫの人でないと言えないこととかいろいろあると思うのですけれども、その辺は答弁側としては大丈夫なのですか。それが少し心配だった。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"西本委員","kind":"質問","question":"外部団体という部分はあるので、なかなか資料の収集などでお手数をおかけしてしまうかと思うのですが、年間を通しての総務委員会の所管事務調査として、調査をかけていくので、やはり実のある調査にしていきたいと思っているのです。それと、市町村交流なのですけれども、これ、区民委員会とかぶることはないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"西本委員","kind":"質問","question":"建設委員会も入ってくるというところがあると思うので、そこのところをある程度、他の委員会にも了承していただいた形で進めていただくということでよろしいのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"山本委員","kind":"質問・要望","question":"今回、調査項目２つということで、分かりました。市町村交流については、私も要望していた幾つかの中の一つに入っておりまして、要望をかなえてくださってありがとうあります。","respondent":"石田（秀）委員長","answer":"それだけれども、その運営についてはいいのだけれども、アリーナ建設、その経済効果、区民への対応など、その施設を取り上げてやっていくとなると、建設委員会の仕切りが大分出てきて、そちらは建設委員会というような形の所管事項になるので、今はっきりは言えないけれども。","id":"exchange-041"},{"speaker":"山本委員","kind":"質問・要望","question":"ご説明ありがとうございました。多分その範疇なのかと。なので、建設委員会というよりは、その連携というところを踏まえれば、この調査項目の中にもしかして入れられるのではないかと思いますので、そういったところも踏まえて、ぜひ、もしそこの範疇に入れていただけるのであれば、せっかくなので併せて調査していただきたいという、これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"}]},{"id":"topic-08","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"まして、前にも申し上げましたが、品川区は、この東京の中、大都市の中で、２３区として、４０万人の区民のために奉仕している組織です。ですから、そういう同じような同レベルの自治体ならば私は参考になると思うのですが、やはり地方とこちらの２３区とは、それぞれ違う。事業の仕方がそれぞれ違いますので、似たようなところを選定するならば、私は近隣、周辺の自治体に視察に行くべきだと考えます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"}]},{"id":"topic-09","title":"その他","agenda":"その他","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"私もほとんど内容を知らないまま聞いていたのですが、お話しされている、質問されている項目、内容について、なかなか分かりにくいところがありましたので、第一に、西本委員がどのような内容のことを質問されていたのかお伺いしたいということと、あと、理事者の側から、庁内ハラスメントについてのアンケート調査を職員の間でやられたと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"松本委員","kind":"質問","question":"といいますのも、都政新報の記事を拝読しますと、このアンケート自体は去年の８月から９月に行われて、同年１２月にアンケート結果が職員向けに発表されたということでございました。それが流出したということについて、どのような経路が考えられるのかということと、コンプライアンス上の問題点というところについて伺えればと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"須貝委員","kind":"意見","question":"別段、誰かが例えば犯罪行為に似たような行為があったとか、そういうことでなければ、私は堂々と品川区内で職員間でこういうことがあって、すごく恫喝されたにせよ、上司にこういう問題があった、私はこういうことを感じたということは堂々と発表して、公表して、我々区議会議員からすれば、職員の皆さんの働く環境がよりよくなるならば、私はぜひ聞かせてほしいし。","respondent":"柏原区長室長","answer":"このアンケートを実施したというのは、そもそもの目的のところが、ハラスメントに関する職員の意識、実態を把握するのだといったところで、今回初めて区としても調査させていただいたといったところです。","id":"exchange-046"},{"speaker":"松本委員","kind":"質問・要望","question":"そうすると、そういうのがない状態で地方公務員法第３４条で考えていくのか。ここの内部規定との関係が分かれば、教えていただきたいというのが１点と。なので、可能性として、部下からのハラスメントがある可能性については、議会ではありましたけれども、これは議員からのハラスメントについても、ここに含まれている可能性があるのかというところを伺えればと思います。","respondent":"柏原区長室長","answer":"ただ、全くないかというと、職場環境というのをどこまで捉えるかというのが出てきますので、そこで優位的なものがあったときに、そのやっている中身、仕事といいますか、やっている作業の中で。","id":"exchange-047"},{"speaker":"松本委員","kind":"質問","question":"今のお答えというのは、公式的には多分それでいいと思うのですけれども、問題は、今回はアンケートなので、書いた職員の方たちの主観では、議員からのハラスメントもパワーハラスメントと記載されている可能性があるかどうかというところでは、可能性があると受け止めていいのでしょうか。","respondent":"柏原区長室長","answer":"当然、我々も事実としては、この記事を見ているだけでありますので、そこで議員の方がという今お話があったのですけれども、そこは特定ができているという判断を私もできませんし、この事実だけをもって、あとは想像の話になってしまいますので。","id":"exchange-048"},{"speaker":"西本委員","kind":"質問・要望","question":"今回のリークの件ですけれども、内部告発に近いのではないですか。だけど、では、どうやって取り締まるのですか、どうやって改善していくのですかという具体的なものは何ひとつ言っていないのです。なので、これは正しい議論、誤解されるかもしれないという思いがあるので、やはりどういう質問をしたのか、質問内容、それから、どういう結果だったのかということもきちんと議会のほうに提示してほしいです。","respondent":"柏原区長室長","answer":"いずれにいたしましても、区も答弁していますけれども、こういった結果が出ているということに関しましては、我々職員全員が、特に幹部職員が真摯に受け止めて、そういったものがない職場環境であったり、何かあったらすぐ言えるような環境。","id":"exchange-049"},{"speaker":"西本委員","kind":"質問","question":"役所の皆さんに、職員の方々に、どういうお願い事をしたのかという証拠を見せてほしいです。だから、データや質問内容、それから結果というのは私たちに提示していただくということは可能なのではないのですか。それは出せないですかということが１点です。だから、誤解が生じるので、誤解が生じないように、きっちりと調査をしてはいかがでしょうかと強く申し上げたいと思うのですが、いかがでしょうか。","respondent":"柏原区長室長","answer":"調査云々ですけれども、結果としては、先ほど申し上げましたけれども、こういった結果が出ているということは、区長をはじめ、我々、真摯に受け止めて、この中からどうしたらそういったハラスメントがない職場環境がつくれるのか、それから。","id":"exchange-050"},{"speaker":"須貝委員","kind":"質問","question":"今、誰がハラスメントをしたのか、されたのか、そのアンケート結果に対して、それは特定できてしまうのですか。働く若者が伸び伸び働ける、そういう品川区にしてほしい。もっと前向きに庁舎内で話せるような仕組みづくりをぜひしてほしいのが、私の質問の内容なのだけれども、聞いていると、こちらは一切そういう話ではないから、公表するということはないから話せません。意見だけです。","respondent":"堀越副区長","answer":"今回のアンケートにつきましては、全体の傾向を見るという形で、率直な意見を、特に外部への提供は予定していないという形で実施したものですので、そういった性質のものであるアンケートですので、そういった扱いを我々としてはしていくというのが一つの考え方。","id":"exchange-051"},{"speaker":"西本委員","kind":"質問","question":"これ、３,０００人くらいの職員の方に渡して、２,０００人ぐらいですかね、がお答えになったということなのですけれども、これ、集計はどうやっているのですか。外部の委託で集計ですか。それとも、皆さん、手でやっているのですか。どういう集計の形を取っているのですか。","respondent":"川村コンプライアンス推進担当課長","answer":"こちらのアンケートにつきましては、コンプライアンス推進担当の職員がＡＩ等を用いて集計をしております。外部委託はしておりません。","id":"exchange-052"},{"speaker":"西本委員","kind":"質問","question":"ＡＩというのはどんな、ＡＩというといろいろあると思うのですけれども、何を使ったのですか。","respondent":"川村コンプライアンス推進担当課長","answer":"具体的に申し上げますと、ＢＩツールというものを使っております。ＣｈａｔＧＰＴです。","id":"exchange-053"},{"speaker":"西本委員","kind":"質問","question":"ＣｈａｔＧＰＴ、これ、独自でやるのですか。品川区だけですか。ＣｈａｔＧＰＴだと、外部へだだ漏れになってしまうのですけれども、そういう集計の方法を取っているのですか。セキュリティーの問題はどう扱われているのですか。","respondent":"西澤ＤＸ戦略担当課長","answer":"ＣｈａｔＧＰＴに関しては、ＡｚｒｕｒｅのＡＩ ＣＯＮＮＥＣＴというのを使って、外に流れるというか、対話形式で答えるというものではあるのですけれども、外部への流出に関してはなくて、情報を記憶させるとか、記録させるとか。","id":"exchange-054"},{"speaker":"西本委員","kind":"質問","question":"すみません。うといものですから。外部に流せないようなセキュリティーをやっているという認識でよろしいのですか。ＣｈａｔＧＰＴだと、外部にアクセスできると思うし、結局、生データがそのまま入るわけですよね。だって、それ、どうなのですか。そこら辺、説明してもらっていいですか。誤解すると嫌なので。〔「基本だけ言えばいいんじゃないの。","respondent":"久保田企画経営部長","answer":"私どもが今使っていますＣｈａｔＧＰＴにつきましては、品川区の内部で完結するような仕組みにしていますので、品川区の職員がやったＣｈａｔＧＰＴが記憶して、別の人が外から来て、それをＣｈａｔＧＰＴが参照して外に出すということではありませんので。","id":"exchange-055"},{"speaker":"西本委員","kind":"質問","question":"分かりました。それも質問で言いました。だから、そうならないように、個人を特定するといけないという、もちろん個人を特定することはしたくはないけれども、だから誤解を生じてしまうから、きちんと調べてはいかがですかという。外部の委員会などをつくって、そういう誤解を生じるようなことではなくて、きちんと調査してはいかがですかと言っているのです。該当は３人しかいないではないですか。","respondent":"堀越副区長","answer":"ハラスメント前のコミュニケーションを、良好なコミュニケーションをどう取っていくかという、職場づくりをどうやっていくかということですので、これはご懸念をいただいているからこそのご質問だと思いますが、それはしっかりと対応していきたいと考えています。","id":"exchange-056"},{"speaker":"西本委員","kind":"質問・要望","question":"意見で終わります。その現状を真摯に受け止めますと言っても、区長、副区長がパワーハラスメントをやっていたらどうするのですかということもあるのです。そうではないというのだったら、きちんと調査をして、そうではありませんというのをきちんと示すべきではないですか。きちんと受け止めてほしい。仮にそういう人がいるならば、きっちりと守ってほしい。それだけは言わせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"山本委員","kind":"質問","question":"私からも質問をします。アンケート調査の結果というものの中に、加害者や被害者の方の個人情報というものが掲載されているような内容なのでしょうかというところです。ルール上だったり、行政として支障があるのかどうかというのをお聞きしたい。そうなったときに、区として、それが公開できないから黒塗りにしようというような類いの情報管理になるのかどうかというのをお伺いしたいというところになります。","respondent":"川村コンプライアンス推進担当課長、柏原区長室長","answer":"そこで職員間では実態が共有されているものと思いますので、隠す意図はもちろんございませんが、アンケートに安心して答えていただくためにも、今回のアンケートに関しては、今の基準に、方針に基づいて取り扱うべきかと考えております。後段でご質問いただいた、例えば、情報公開請求というようなお話もあったのですが、今、このアンケートを庁内で周知しているといった内容のことと、それから、情報公開請求とまた制度が違う制度でありますので。","id":"exchange-058"},{"speaker":"山本委員","kind":"質問・要望","question":"その部分、そのようなお考えと、情報公開がもしそういったメディアの方々などからあったときには、そのときにご判断されるということで、理解をしました。もう一つお伺いしたいのが、改善策等についてなのです。これまでのご答弁で、真摯に受け止めているということだったのですけれども、やはり具体的なアクションがどのように取られているかというのを、最後に確認させていただきたいと思います。","respondent":"川村コンプライアンス推進担当課長","answer":"ただ、令和５年から弁護士による外部相談窓口は設置しておるところなのですけれども、そちらの周知につきましては、人事課とも連携して、折に触れ、職員周知しておりますし、個別の相談が受理されたときには、こちらのコンプライアンス推進担当におきまして。","id":"exchange-059"},{"speaker":"山本委員","kind":"質問・要望","question":"外部の相談窓口は令和５年から設置しているということでいうと、このアンケート調査の前から既にあるということですので、特にこのアンケート結果を踏まえて何かアクションがあったというものではないということでいうと、私の質問したものとは少し答えが違うかと思うので、このアンケート結果を踏まえてアクションをしたことがあるのであれば、改めてお聞かせいただきたいということと。","respondent":"柏原区長室長","answer":"先ほどの外部の弁護士の相談窓口については、コンプライアンス推進担当課長から申し上げたとおり、令和５年からスタートさせているというところで、今、手元に数字というのはあれなのですけれども、このアンケートをやった結果、件数が増えているかどうかというところにおいては。","id":"exchange-060"},{"speaker":"山本委員","kind":"質問・要望","question":"ご答弁ありがとうあります。外部の相談件数が正確に把握されていないというのは分かりました。そのためにアンケートを取られたというご説明だったので、なので、アンケート結果が出た結果、どういう打ち手をされているのですかというのをお聞きしているのです。これは要望です。これも要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"塚本副委員長","kind":"意見","question":"パワーハラスメントとかというのは、受ける側がどう受けたかということが大事なので、そういうものを忌憚なく書いてもらおうということもあってやっていたものなので、それを第三者が入ってくると、ややこしくなるというのか、二次被害を生むということも一方ではあると思うので、知りたいという思いに応えて素直にというか、オープンにしていくということは慎重に。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-062"},{"speaker":"澤田委員","kind":"質問","question":"そのスパンは分かりませんけれども、定期的に見ていただいて、職場環境が改善していったかどうかというのは、追って見ていくことは大事なのではないかということと、あと、例えば、これから区役所で働きたいとかという思いのある若い人たちに向けて、職場環境、最初はこうでしたけれども徐々によくなっていったとか、こんなことをやっているから安心して働きに来てくださいと伝えるためにも。","respondent":"川村コンプライアンス推進担当課長","answer":"ご指摘のとおり、対策後の変化を捉えるためのアンケートの実施は重要なことと考えています。ただ、今年度以降、どのような形でアンケートを実施するかどうかも含めて、まだ検討中の段階です。","id":"exchange-063"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/121362?Template=document&Id=7111#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":62796,"voices":190}}]);
